        </div>
      </div>

      {isUser && (
        <div className="flex-shrink-0">
          <div className="w-9 h-9 rounded-full bg-muted flex items-center justify-center shadow-sm">
            <User className="w-5 h-5" />
          </div>
        </div>
      )}
