 * ⚡ 고속 재추천 API
 * MACRec 기반 3초 이내 재추천 시스템
 */

import { NextRequest, NextResponse } from 'next/server';
import { FastReRecommendationEngine } from '@/lib/macrec/FastReRecommendationEngine';
import { searchVehicles } from '@/lib/database';

export async function POST(request: NextRequest) {
  const startTime = Date.now();

  try {
    console.log('⚡ 고속 재추천 API 시작');

    const { userMessage, currentRecommendations, searchQuery } = await request.json();

    if (!userMessage) {
      return NextResponse.json({ error: 'User message required' }, { status: 400 });
    }

    // 고속 재추천 엔진 초기화
    const engine = new FastReRecommendationEngine();

    // 사용자 만족도 체크
    const isUserSatisfied = engine.isUserSatisfied(userMessage);
    console.log(`🎯 사용자 만족도: ${isUserSatisfied ? '만족' : '불만족'}`);

    if (isUserSatisfied) {
      return NextResponse.json({
        type: 'satisfied',
        message: '좋은 선택이시네요! 추가로 궁금한 점이 있으시면 언제든 물어보세요.',
        processingTime: Date.now() - startTime
      });
    }

    // 차량 데이터 조회 (캐시 활용)
