      max: 15000
    }, searchQuery || undefined, undefined, undefined, false);
    console.log(`✅ ${allVehicles.length}대 차량 데이터 로드`);

    // 고속 재추천 실행
    const reRecommendationResult = await engine.executeReRecommendation({
      userMessage,
      currentRecommendations: currentRecommendations || [],
      userFeedback: {
        type: 'not_satisfied',
        details: userMessage
