/**
 * 🚀 통합 스마트 추천 API - 3개 논문 기반 시스템 통합
 * TOPSIS + Alibaba Re-ranking + MACRec 다중 에이전트 협업
 */

import { NextRequest, NextResponse } from 'next/server';
import { searchVehicles } from '@/lib/database';
import { VehicleTOPSISEvaluator } from '@/lib/topsis/TOPSISEngine';
import { FastReRecommendationEngine } from '@/lib/macrec/FastReRecommendationEngine';
import UserProfileLearner from '@/lib/alibaba/UserProfileLearner';

export async function POST(request: NextRequest) {
  const startTime = Date.now();

  try {
    const body = await request.json();
    const {
      userMessage,
      conversationHistory = [],
      userPreferences = {},
      budget = { min: 2000, max: 8000 },
      usage = 'family',
      userId = 'anonymous',
      sessionId,
      feedbackData = null
    } = body;

    console.log('🚀 스마트 추천 시작:', { userMessage, budget, usage });

    // 1. 차량 데이터 검색
    const searchStart = Date.now();
    const vehicles = await searchVehicles(budget, usage, undefined, undefined, false);
    const searchTime = Date.now() - searchStart;
    console.log(`📊 차량 검색 완료: ${vehicles.length}대 (${searchTime}ms)`);

    if (vehicles.length === 0) {
      return NextResponse.json({
        success: false,
        error: 'No vehicles found',
        message: '조건에 맞는 차량을 찾을 수 없습니다.'
      });
    }

    // 2. Alibaba 개인화 프로필 학습
    const alibabaStart = Date.now();
    const profileLearner = new UserProfileLearner();

    // 대화 기록을 학습용 메시지 형태로 변환
    const learningMessages = [
      ...conversationHistory.map((msg: any) => ({
        role: msg.agent === 'user' ? 'user' : 'assistant',
        content: msg.content,
        timestamp: new Date(msg.timestamp)
      })),
      { role: 'user', content: userMessage, timestamp: new Date() }
    ];

    const userProfile = await profileLearner.learnFromConversation(learningMessages);
    const alibabaTime = Date.now() - alibabaStart;
    console.log(`🎨 Alibaba 개인화 완료: ${alibabaTime}ms`);

    // 3. TOPSIS 다기준 의사결정 평가
    const topsisStart = Date.now();
    const topsisEvaluator = new VehicleTOPSISEvaluator();

    // 개인화된 가중치 적용
    const personalizedWeights = {
      priceWeight: userProfile.price_sensitivity || 0.25,
      performanceWeight: userProfile.performance_importance || 0.20,
      brandWeight: userProfile.brand_preference || 0.15,
      fuelEfficiencyWeight: userProfile.fuel_efficiency_importance || 0.20,
      safetyWeight: userProfile.safety_priority || 0.15,
      designWeight: userProfile.luxury_preference || 0.05
    };

    // 상위 50대만 평가 (성능 최적화)
    const topVehicles = vehicles.slice(0, 50);
    const topsisResult = await topsisEvaluator.evaluateVehicles(topVehicles, personalizedWeights);
    const topsisTime = Date.now() - topsisStart;
    console.log(`🎯 TOPSIS 평가 완료: ${topsisResult.ranking.length}대 (${topsisTime}ms)`);

    // 4. MACRec 협업 추천 (필요시)
    let macrecResult = null;
    let macrecTime = 0;

    if (feedbackData || conversationHistory.length > 2) {
      const macrecStart = Date.now();
      const fastEngine = new FastReRecommendationEngine();

      // 기존 추천에 대한 피드백이 있는 경우 재추천 실행
      if (feedbackData) {
        const reRecommendRequest = {
          userMessage,
          currentRecommendations: feedbackData.previousRecommendations || [],
          userFeedback: {
            type: feedbackData.feedbackType || 'not_satisfied',
            details: feedbackData.feedbackDetails || userMessage
          }
        };

        macrecResult = await fastEngine.executeReRecommendation(reRecommendRequest, vehicles);
      }

      macrecTime = Date.now() - macrecStart;
      console.log(`🤝 MACRec 협업 완료: ${macrecTime}ms`);
    }

    // 5. 결과 통합 및 최종 추천 생성
    const integrationStart = Date.now();
    const finalRecommendations = generateIntegratedRecommendations(
      topsisResult.ranking,
      userProfile,
      macrecResult,
      userMessage
    );
    const integrationTime = Date.now() - integrationStart;

    // 6. 추천 결과 포맷팅
    const formattedRecommendations = finalRecommendations.slice(0, 5).map((item, index) => {
      const vehicle = item.alternative.metadata;

      return {
        rank: index + 1,
        vehicle: {
          vehicle_id: vehicle.vehicle_id,
          manufacturer: vehicle.manufacturer || vehicle.brand,
          model: vehicle.model,
          model_year: vehicle.model_year || vehicle.year,
          price: vehicle.price,
          distance: vehicle.distance,
          fuel_type: vehicle.fuel_type || vehicle.fuel_typ,
          sell_type: vehicle.sell_type,
          location: vehicle.location
        },
        scores: {
          topsis: item.score,
          alibaba: calculatePersonalizationScore(vehicle, userProfile),
          macrec: macrecResult?.confidence || 0.8,
          overall: calculateOverallScore(item.score, userProfile, macrecResult?.confidence || 0.8)
        },
        explanations: {
          topsis: generateTOPSISExplanation(item.score, personalizedWeights),
          alibaba: generatePersonalizationExplanation(vehicle, userProfile),
          macrec: macrecResult ? generateMACRecExplanation(macrecResult) : '협업 추천 시스템 대기'
        },
        metadata: {
          personalizationMatch: calculatePersonalizationMatch(vehicle, userProfile),
          confidenceLevel: 'high'
        }
      };
    });

    const totalTime = Date.now() - startTime;

    // 7. 응답 생성
    return NextResponse.json({
      success: true,
      recommendations: formattedRecommendations,
      metadata: {
        totalVehiclesSearched: vehicles.length,
        totalEvaluated: topVehicles.length,
        userProfile: {
          preferences: userProfile,
          confidenceScore: userProfile.confidenceScore || 0.5
        },
        systemPerformance: {
          searchTime,
          alibabaTime,
          topsisTime,
          macrecTime,
          integrationTime,
          totalTime
        },
        algorithms: {
          topsis: {
            criteria: Object.keys(personalizedWeights),
            topScore: topsisResult.ranking[0]?.score || 0
          },
          alibaba: {
            personalizationEnabled: true,
            profileConfidence: userProfile.confidenceScore || 0.5
          },
          macrec: {
            collaborationActive: !!macrecResult,
            confidence: macrecResult?.confidence || 0
          }
        }
      },
      message: generateRecommendationMessage(formattedRecommendations.length, userMessage),
      timestamp: new Date().toISOString()
    });

  } catch (error) {
    console.error('❌ 스마트 추천 실패:', error);

    return NextResponse.json({
      success: false,
      error: 'Smart recommendation failed',
      details: error instanceof Error ? error.message : 'Unknown error',
      recommendations: [],
      processingTime: Date.now() - startTime
    }, { status: 500 });
  }
}

/**
 * 통합 추천 결과 생성
 */
function generateIntegratedRecommendations(
  topsisRanking: any[],
  userProfile: any,
  macrecResult: any,
  userMessage: string
): any[] {
  // MACRec 결과가 있는 경우 가중치 조정
  if (macrecResult && macrecResult.newRecommendations.length > 0) {
    console.log('🔄 MACRec 재추천 결과 통합');

    // 재추천된 차량들의 TOPSIS 점수 조정
    const reRecommendedIds = new Set(
      macrecResult.newRecommendations.map((v: any) => v.vehicle_id)
    );

    return topsisRanking.map(item => {
      const vehicleId = item.alternative.metadata.vehicle_id;

      if (reRecommendedIds.has(vehicleId)) {
        // MACRec에서 재추천된 차량은 점수 부스트
        const boostedScore = Math.min(item.score * 1.2, 1.0);
        return {
          ...item,
          score: boostedScore,
          macrecBoosted: true
        };
      }

      return item;
    }).sort((a, b) => b.score - a.score);
  }

  return topsisRanking;
}

/**
 * 개인화 점수 계산
 */
function calculatePersonalizationScore(vehicle: any, userProfile: any): number {
  let score = 0.5; // 기본 점수

  // 가격 선호도
  if (userProfile.price_sensitivity > 0.6 && vehicle.price < 3000) {
    score += 0.2;
  }

  // 연비 선호도
  if (userProfile.fuel_efficiency_importance > 0.6) {
    const fuelTypes = ['하이브리드', '전기', 'LPG'];
    if (fuelTypes.some(type => vehicle.fuel_type?.includes(type))) {
      score += 0.2;
    }
  }

  // 브랜드 선호도
  if (userProfile.brand_preference > 0.6) {
    const premiumBrands = ['벤츠', 'BMW', '아우디', 'Genesis', '렉서스'];
    if (premiumBrands.some(brand => vehicle.manufacturer?.includes(brand))) {
      score += 0.15;
    }
  }

  return Math.min(score, 1.0);
}

/**
 * 종합 점수 계산
 */
function calculateOverallScore(topsisScore: number, userProfile: any, macrecConfidence: number): number {
  const weights = {
    topsis: 0.5,
    personalization: 0.3,
    macrec: 0.2
  };

  const personalizationScore = userProfile.confidenceScore || 0.5;

  return (
    topsisScore * weights.topsis +
    personalizationScore * weights.personalization +
    macrecConfidence * weights.macrec
  );
}

/**
 * 개인화 매칭 점수 계산
 */
function calculatePersonalizationMatch(vehicle: any, userProfile: any): number {
  return Math.random() * 0.3 + 0.7; // 임시 구현
}

/**
 * TOPSIS 설명 생성
 */
function generateTOPSISExplanation(score: number, weights: any): string {
  const topCriteria = Object.entries(weights)
    .sort(([,a], [,b]) => (b as number) - (a as number))
    .slice(0, 2)
    .map(([key]) => key.replace('Weight', ''));

  return `${topCriteria.join(', ')} 기준으로 ${Math.round(score * 100)}점 획득`;
}

/**
 * 개인화 설명 생성
 */
function generatePersonalizationExplanation(vehicle: any, userProfile: any): string {
  const reasons = [];

  if (userProfile.price_sensitivity > 0.6) {
    reasons.push('가성비 중시');
  }

  if (userProfile.fuel_efficiency_importance > 0.6) {
    reasons.push('연비 우선');
  }

  return reasons.length > 0 ?
    `${reasons.join(', ')} 성향에 맞춰 추천` :
    '개인 선호도 반영';
}

/**
 * MACRec 설명 생성
 */
function generateMACRecExplanation(macrecResult: any): string {
  if (macrecResult.changes && macrecResult.changes.length > 0) {
    return `${macrecResult.changes.join(', ')} 반영하여 재추천`;
  }

  return `${Math.round(macrecResult.confidence * 100)}% 신뢰도로 협업 추천`;
}

/**
 * 추천 메시지 생성
 */
function generateRecommendationMessage(count: number, userMessage: string): string {
  if (count === 0) {
    return '조건에 맞는 차량을 찾지 못했습니다. 다른 조건으로 다시 검색해보세요.';
  }

  return `3개 논문 기반 알고리즘으로 분석하여 ${count}대의 최적 차량을 추천드립니다.`;
}

import { NextRequest } from 'next/server';
import { GoogleGenerativeAI } from '@google/generative-ai';
import { searchVehicles } from '@/lib/database';
import { DynamicCollaborationManager } from '@/lib/collaboration/DynamicCollaborationManager';
// PersonaDetector 제거됨 - 논문 기반 중립적 시스템으로 변경

// 리스 의도 감지 함수
function detectLeaseIntent(question: string): boolean {
  const leaseKeywords = [
    '리스', 'lease', '렌트', '렌탈', '장기렌트', '월납', '월기렌트',
    '리스 계약', '리스 차량', '리스 상품', '월지불', '월결제',
    '리스료', '렌트료', '월기 렌트', '할부', '리스비'
  ];

  const normalizedQuestion = question.toLowerCase().replace(/\s/g, '');

  return leaseKeywords.some(keyword =>
    normalizedQuestion.includes(keyword.toLowerCase().replace(/\s/g, ''))
  );
}

// 예산 추출 함수 (기존 코드 유지)
function extractBudget(question: string): { min: number; max: number } {
  const budgetPatterns = [
    /(\d+(?:,\d+)*)\s*만원/g,
    /(\d+(?:,\d+)*)\s*천만원/g,
    /(\d+(?:,\d+)*)\s*억/g,
    /예산.*?(\d+(?:,\d+)*)/g,
    /(\d+(?:,\d+)*)\s*정도/g
  ];

  let budgetAmount = 2500; // 기본값 2500만원

  for (const pattern of budgetPatterns) {
    const matches = question.match(pattern);
    if (matches) {
      const numbers = matches.map(match => {
        const num = match.replace(/[^\d]/g, '');
        return parseInt(num);
      });

      if (numbers.length > 0) {
        budgetAmount = Math.max(...numbers);

        // 천만원 단위 처리
        if (question.includes('천만원')) {
          budgetAmount = budgetAmount * 1000;
        } else if (question.includes('억')) {
          budgetAmount = budgetAmount * 10000;
        }
        break;
      }
    }
  }

  // 범위 설정 (±20%)
  const min = Math.max(budgetAmount * 0.8, 1000);
  const max = budgetAmount * 1.2;

  return { min, max };
}

// WebSocket connection handler with Dynamic Collaboration
export async function GET(request: NextRequest) {
  const { searchParams } = new URL(request.url);
  const question = searchParams.get('question');
  const context = searchParams.get('context') || 'real_ai_analysis';
  const previousVehiclesParam = searchParams.get('previousVehicles');

  if (!question) {
    return new Response('Question is required', { status: 400 });
  }

  // 이전 추천 차량 데이터 파싱
  let previousVehicles: any[] = [];
  if (previousVehiclesParam) {
    try {
      previousVehicles = JSON.parse(decodeURIComponent(previousVehiclesParam));
      console.log(`🔄 Previous vehicles found: ${previousVehicles.length} vehicles`);
    } catch (error) {
      console.log('⚠️ Failed to parse previous vehicles, proceeding without them');
    }
  }

  console.log(`🤖 Dynamic A2A Collaboration Started: "${question}" [${context}]`);

  // Server-Sent Events 설정
  const stream = new ReadableStream({
    start(controller) {
      (async () => {
        let streamClosed = false;
        try {
          // 실제 차량 데이터 검색
          const budgetRange = extractBudget(question);
          const budget = {
            min: budgetRange.min,
            max: budgetRange.max,
            flexible: true,
            userConfirmed: false
          };

          // 페르소나 로직 제거됨 - 논문 기반 중립적 분석으로 변경

          // 리스 의도 감지
          const includeLeaseProducts = detectLeaseIntent(question);

          const vehicles = await searchVehicles(budgetRange, question, undefined, undefined, includeLeaseProducts);

          console.log(`💰 Budget: ${budget.min}-${budget.max}만원`);
          console.log(`🚗 Found ${vehicles.length} real vehicles from PostgreSQL`);
          console.log(`📊 논문 기반 중립적 차량 분석 시스템 (페르소나 미사용)`);
          console.log(`📋 Lease Products: ${includeLeaseProducts ? 'INCLUDED' : 'EXCLUDED (only regular sales)'}`);

          // 동적 협업 매니저 초기화
          const collaborationManager = new DynamicCollaborationManager(process.env.GEMINI_API_KEY!);

          // 메타데이터 전송
          controller.enqueue(
            `data: ${JSON.stringify({
              type: 'metadata',
              budget: budget,
              vehiclesFound: vehicles.length,
              // 페르소나 정보 제거됨 - 논문 기반 중립적 분석
              timestamp: new Date().toISOString(),
              collaborationType: 'dynamic'
            })}\n\n`
          );

          console.log('🚀 동적 A2A 협업 세션 시작');

          // 동적 협업 실행 (페르소나 정보 포함)
          for await (const event of collaborationManager.startDynamicCollaboration(question, vehicles, budget, previousVehicles, undefined)) {

            // 스트림이 이미 닫혔으면 중단
            if (streamClosed) {
              console.log('⚠️ Stream already closed, skipping event');
              break;
            }

            try {
              // 협업 이벤트를 WebSocket 메시지로 변환
              const message = {
                type: event.type,
                agent: event.agentId,
                content: event.content,
                timestamp: event.timestamp.toISOString(),
                metadata: event.metadata
              };

              console.log(`📡 Event: ${event.type} from ${event.agentId}`);

              // Controller 상태 확인 후 안전하게 데이터 전송
              try {
                if (controller.desiredSize !== null) {
                  controller.enqueue(`data: ${JSON.stringify(message)}\n\n`);
                } else {
                  console.log('⚠️ Stream closed, skipping message transmission');
                }
              } catch (error) {
                console.log(`⚠️ Failed to send message: ${error.message}`);
              }

              // 특별한 이벤트 타입들 처리
              switch (event.type) {
                case 'pattern_detected':
                  console.log(`🎯 Pattern detected: ${event.metadata?.pattern?.type}`);
                  break;

                case 'agent_question':
                  console.log(`❓ Question from ${event.agentId} to ${event.metadata?.targetAgent}`);
                  break;

                case 'agent_answer':
                  console.log(`💬 Answer from ${event.agentId}`);
                  break;

                case 'user_intervention_needed':
                  console.log(`🙋 User intervention needed: ${event.metadata?.interventionType}`);
                  break;

                case 'vehicle_recommendations':
                  console.log(`🚗 Vehicle recommendations sent with ${event.metadata?.vehicles?.length || 0} vehicles`);
                  console.log('🏁 Vehicle recommendations delivered, ending collaboration');
                  // 메시지 전송 완료를 기다린 후 스트림 종료
                  break;

                case 'collaboration_complete':
                  console.log(`✅ Collaboration complete after ${event.metadata?.totalRounds} rounds`);
                  // vehicle_recommendations가 이미 전송된 경우에만 종료
                  break;

                case 'error':
                  console.error(`❌ Collaboration error: ${event.content}`);
                  streamClosed = true; // 오류 시에도 스트림 종료
                  break;
              }

              // vehicle_recommendations 완료 시 타이머로 지연 종료
              if (event.type === 'vehicle_recommendations') {
                console.log('🎯 Vehicle recommendations sent, preparing graceful shutdown');
                // 데이터 전송이 완료될 수 있도록 짧은 지연 후 종료
                setTimeout(() => {
                  console.log('⏰ Graceful shutdown timer triggered');
                  streamClosed = true;
                  try {
                    if (controller.desiredSize !== null) {
                      controller.close();
                      console.log('✅ Stream closed gracefully after vehicle recommendations');
                    }
                  } catch (closeError) {
                    console.log('⚠️ Stream was already closed:', closeError.message);
                  }
                }, 100); // 100ms 지연으로 데이터 전송 완료 보장
                break; // 루프에서는 즉시 탈출
              }
            } catch (controllerError) {
              console.error('💥 Controller Error:', controllerError);
              streamClosed = true;
              break;
            }
          }

          // 모든 이벤트 처리 완료 후 스트림 종료
          if (!streamClosed) {
            console.log('🎉 All events processed, closing stream gracefully');
            streamClosed = true;
          }

          console.log('✨ Dynamic A2A 협업 완료!');

        } catch (error) {
          console.error('💥 Dynamic Collaboration Error:', error);
          streamClosed = true;
          try {
            controller.enqueue(
              `data: ${JSON.stringify({
                type: 'error',
                agent: 'system',
                error: error instanceof Error ? error.message : 'Unknown error',
                timestamp: new Date().toISOString()
              })}\n\n`
            );
          } catch (enqueueError) {
            console.error('💥 Error sending error message:', enqueueError);
          }
        } finally {
          try {
            if (!streamClosed) {
              console.log('⚠️ Finally block - closing controller gracefully');
              controller.close();
            } else {
              console.log('✅ Stream already properly closed');
            }
          } catch (closeError) {
            // Controller might already be closed, which is expected
            console.log('ℹ️ Controller already closed (expected):', closeError.message);
          }
        }
      })();
    }
  });

  return new Response(stream, {
    headers: {
      'Content-Type': 'text/event-stream',
      'Cache-Control': 'no-cache',
      'Connection': 'keep-alive',
    },
  });
}

