import { NextRequest, NextResponse } from 'next/server';
import { DynamicCollaborationManager } from '@/lib/collaboration/DynamicCollaborationManager';
import { SharedContext } from '@/lib/collaboration/SharedContext';
import { searchVehicles } from '@/lib/database';

/**
 * 🚀 프로덕션 대시보드 랭킹 API
 * 실제 RDS 데이터와 TOPSIS 알고리즘 연동
 */
export async function GET(request: NextRequest) {
  const startTime = Date.now();

  try {
    console.log('🎯 프로덕션 대시보드 랭킹 시작...');

    // URL 파라미터 추출
    const { searchParams } = new URL(request.url);
    const query = searchParams.get('query') || '가족용 SUV 추천';
    const limit = parseInt(searchParams.get('limit') || '15');
    const budget_min = parseInt(searchParams.get('budget_min') || '2000');
    const budget_max = parseInt(searchParams.get('budget_max') || '8000');

    console.log(`🔍 쿼리: "${query}", 예산: ${budget_min}-${budget_max}만원, 제한: ${limit}대`);

    // 1단계: 실제 RDS에서 차량 데이터 검색
    const searchStartTime = Date.now();

    // 쿼리 분석하여 usage 패턴 결정
    let usage = '';
    if (query.includes('SUV') || query.includes('가족')) {
      usage = 'family';
    } else if (query.includes('첫차') || query.includes('신차구매')) {
      usage = 'first_car';
    } else if (query.includes('캠핑') || query.includes('차박')) {
      usage = 'camping';
    } else if (query.includes('연비') || query.includes('경제')) {
      usage = 'economy';
    } else if (query.includes('고급') || query.includes('프리미엄')) {
      usage = 'luxury';
    }

    const vehicles = await searchVehicles(
      { min: budget_min, max: budget_max },
      usage || undefined,
      undefined, // familyType
      undefined, // persona
      false // includeLease = false (자차구매만)
    );

    const searchTime = Date.now() - searchStartTime;
    console.log(`✅ RDS 검색 완료: ${vehicles.length}대 (${searchTime}ms)`);

    if (vehicles.length === 0) {
      return NextResponse.json({
        success: true,
        message: '검색 조건에 맞는 차량이 없습니다.',
        dashboardResults: {
          totalProcessed: 0,
          resultsCount: 0,
          topVehicles: [],
          cacheStatus: '🔍 검색결과 없음'
        },
        performance: { searchTime, totalTime: Date.now() - startTime }
      });
    }

    // 2단계: TOPSIS 고성능 랭킹 처리
    const topsisStartTime = Date.now();

    // SharedContext 초기화
    const sharedContext = new SharedContext(query, vehicles.slice(0, 100), {
      min: budget_min,
      max: budget_max,
      flexible: true,
      userConfirmed: true
    });

    const collaborationManager = new DynamicCollaborationManager(
      process.env.GEMINI_API_KEY || '',
      sharedContext
    );

    // 사용자 선호도 프로필 생성
    const userPreferences = {
      priceWeight: query.includes('가격') || query.includes('저렴') ? 0.4 : 0.25,
