import { NextRequest, NextResponse } from 'next/server';
import { query } from '@/lib/database';

export async function GET(request: NextRequest) {
  try {
    const { searchParams } = new URL(request.url);
    const manufacturer = searchParams.get('manufacturer');
    const model = searchParams.get('model');
    const limit = parseInt(searchParams.get('limit') || '20');

    console.log('📊 리뷰 데이터 조회 요청:', { manufacturer, model, limit });

    let sqlQuery = `
      SELECT
        manufacturer,
        model_group,
        rating_total,
        rating_design,
        rating_performance,
        rating_option,
        rating_maintenance,
        comment_total,
        comment_design,
        comment_performance,
        comment_option,
        comment_maintenance
      FROM getcha_reviews
    `;

    const params: any[] = [];
    const conditions: string[] = [];

    // 제조사 필터
    if (manufacturer) {
      conditions.push('manufacturer = $' + (params.length + 1));
      params.push(manufacturer);
    }

    // 모델 필터
    if (model) {
      conditions.push('model_group = $' + (params.length + 1));
      params.push(model);
    }

    // WHERE 조건 추가
    if (conditions.length > 0) {
      sqlQuery += ' WHERE ' + conditions.join(' AND ');
    }

    // 정렬 및 제한
    sqlQuery += ' ORDER BY rating_total DESC';
    sqlQuery += ' LIMIT $' + (params.length + 1);
    params.push(limit);

    console.log('🔍 실행 쿼리:', sqlQuery);
    console.log('📝 파라미터:', params);

    const result = await query(sqlQuery, params);

    console.log('✅ 리뷰 조회 완료:', result.rows.length, '개');

    // 통계 정보 계산
    const reviews = result.rows;
    let stats = null;

    if (reviews.length > 0) {
      const avgTotal = reviews.reduce((sum: number, r: any) => sum + r.rating_total, 0) / reviews.length;
      const avgDesign = reviews.reduce((sum: number, r: any) => sum + r.rating_design, 0) / reviews.length;
      const avgPerformance = reviews.reduce((sum: number, r: any) => sum + r.rating_performance, 0) / reviews.length;
      const avgMaintenance = reviews.reduce((sum: number, r: any) => sum + r.rating_maintenance, 0) / reviews.length;
      const avgOption = reviews.reduce((sum: number, r: any) => sum + r.rating_option, 0) / reviews.length;

      stats = {
        avgRatings: {
          total: Math.round(avgTotal * 10) / 10,
          design: Math.round(avgDesign * 10) / 10,
          performance: Math.round(avgPerformance * 10) / 10,
          maintenance: Math.round(avgMaintenance * 10) / 10,
          option: Math.round(avgOption * 10) / 10
        },
        reviewCount: reviews.length,
        highRatingCount: reviews.filter((r: any) => r.rating_total >= 4).length,
        recommendationRate: Math.round((reviews.filter((r: any) => r.rating_total >= 4).length / reviews.length) * 100)
      };
    }

    return NextResponse.json({
      success: true,
      reviews,
      stats,
      query: {
        manufacturer,
        model,
        limit,
        resultCount: reviews.length
      },
      message: `리뷰 데이터 조회 완료 - ${reviews.length}개 결과`
    });

  } catch (error) {
    console.error('❌ 리뷰 조회 실패:', error);
    return NextResponse.json({
      success: false,
      error: error.message,
      message: '리뷰 데이터 조회 중 오류가 발생했습니다.'
    }, { status: 500 });
  }
}

// POST 요청으로 특정 리뷰 분석 요청
export async function POST(request: NextRequest) {
  try {
    const body = await request.json();
    const { manufacturer, model_group, analysisType } = body;

    console.log('🔬 리뷰 분석 요청:', { manufacturer, model_group, analysisType });

    // 분석 타입별로 다른 쿼리 실행
    let result;

    switch (analysisType) {
      case 'sentiment':
        // 감정 분석용 코멘트 데이터
        result = await query(`
          SELECT
            comment_total,
            comment_design,
            comment_performance,
            comment_maintenance,
            rating_total,
            manufacturer,
            model_group
          FROM getcha_reviews
          WHERE manufacturer = $1 AND model_group = $2
            AND (comment_total IS NOT NULL OR comment_design IS NOT NULL)
          ORDER BY rating_total DESC
          LIMIT 50
        `, [manufacturer, model_group]);
        break;

      case 'statistics':
        // 통계 분석용 평점 데이터
        result = await query(`
          SELECT
            rating_total,
            rating_design,
            rating_performance,
            rating_option,
            rating_maintenance,
            manufacturer,
            model_group
          FROM getcha_reviews
          WHERE manufacturer = $1 AND model_group = $2
        `, [manufacturer, model_group]);
        break;

      default:
        // 기본 조회
        result = await query(`
          SELECT * FROM getcha_reviews
          WHERE manufacturer = $1 AND model_group = $2
          LIMIT 20
        `, [manufacturer, model_group]);
    }

    return NextResponse.json({
      success: true,
      data: result.rows,
      analysisType,
      resultCount: result.rows.length,
      message: `${analysisType} 분석용 데이터 조회 완료`
    });

  } catch (error) {
    console.error('❌ 리뷰 분석 실패:', error);
    return NextResponse.json({
      success: false,
      error: error.message,
      message: '리뷰 분석 중 오류가 발생했습니다.'
    }, { status: 500 });
  }
}

