    console.log(`✅ 테이블 조회 완료: ${tablesResult.rows.length}개 테이블`);

    // reviews 관련 테이블이 있는지 확인
    const reviewTables = tablesResult.rows.filter(table =>
      table.table_name.toLowerCase().includes('review')
    );

    if (reviewTables.length > 0) {
      console.log('📝 리뷰 관련 테이블 발견:', reviewTables);

      // 리뷰 테이블의 스키마 조회
      for (const table of reviewTables) {
        const schemaResult = await query(`
          SELECT column_name, data_type, is_nullable, column_default
          FROM information_schema.columns
          WHERE table_name = $1 AND table_schema = 'public'
          ORDER BY ordinal_position;
        `, [table.table_name]);

        console.log(`📋 ${table.table_name} 스키마:`, schemaResult.rows);
      }
    }

    return NextResponse.json({
      success: true,
      allTables: tablesResult.rows,
      reviewTables: reviewTables,
      message: `데이터베이스에서 ${tablesResult.rows.length}개 테이블 발견, 리뷰 테이블 ${reviewTables.length}개`
    });

  } catch (error) {
    console.error('❌ 테이블 조회 실패:', error);
    return NextResponse.json({
      success: false,
      error: 'Database table lookup failed',
      message: '데이터베이스 테이블 조회 중 오류가 발생했습니다.'
    }, { status: 500 });
  }
}

