import { NextRequest, NextResponse } from 'next/server';
import { Pool } from 'pg';

// PostgreSQL 연결 설정
const pool = new Pool({
  connectionString: process.env.DATABASE_URL,
  ssl: process.env.NODE_ENV === 'production' ? { rejectUnauthorized: false } : false,
});

/**
 * 🧠 실시간 사용자 피드백 수집 API
 * 사용자 행동 데이터로 추천 시스템이 학습합니다.
 *
 * 피드백 유형:
 * - 'like': 좋아요/관심 표시
 * - 'view': 차량 상세 조회
 * - 'contact': 연락하기 클릭 (높은 관심도)
 */
export async function POST(request: NextRequest) {
  const feedbackStartTime = Date.now();

  try {
    const body = await request.json();
    const { userId, vehicleId, actionType } = body;

    // 입력 검증
    if (!userId || !vehicleId || !actionType) {
      return NextResponse.json({
        success: false,
        error: '필수 파라미터가 누락되었습니다.',
        required: ['userId', 'vehicleId', 'actionType']
      }, { status: 400 });
    }

    if (!['like', 'view', 'contact'].includes(actionType)) {
      return NextResponse.json({
        success: false,
        error: '지원하지 않는 액션 타입입니다.',
        supportedTypes: ['like', 'view', 'contact']
      }, { status: 400 });
    }

    console.log(`📊 피드백 수집: ${userId} → ${vehicleId} (${actionType})`);

    // 1. 피드백 데이터 저장
    const feedbackResult = await pool.query(`
      INSERT INTO user_feedback (user_id, vehicle_id, action_type, timestamp, session_id, ip_address)
      VALUES ($1, $2, $3, NOW(), $4, $5)
      RETURNING id, timestamp
    `, [
      userId,
      vehicleId,
      actionType,
      `session_${Date.now()}`, // 세션 ID (실제로는 세션 관리 시스템에서)
      request.headers.get('x-forwarded-for') || 'unknown'
    ]);

    // 2. 현재 사용자의 학습된 가중치 조회
    const currentWeights = await getUserWeights(userId);

    // 3. 액션 타입에 따른 가중치 업데이트
    const updatedWeights = updateWeights(currentWeights, actionType, vehicleId);

    // 4. 업데이트된 가중치 저장
    await saveUserWeights(userId, updatedWeights);

    // 5. 피드백 통계 계산
    const feedbackStats = await calculateFeedbackStats(userId, vehicleId);

    const processingTime = Date.now() - feedbackStartTime;

    console.log(`✅ 피드백 처리 완료: ${processingTime}ms`);

    return NextResponse.json({
      success: true,
      feedback: {
        id: feedbackResult.rows[0].id,
        timestamp: feedbackResult.rows[0].timestamp,
        actionType,
        processingTime
      },
      learningUpdate: {
        previousWeights: currentWeights,
        updatedWeights,
        weightChangeScore: calculateWeightChange(currentWeights, updatedWeights)
      },
      userStats: {
        totalFeedbacks: feedbackStats.totalFeedbacks,
        likeCount: feedbackStats.likeCount,
        viewCount: feedbackStats.viewCount,
        contactCount: feedbackStats.contactCount,
        learningProgress: Math.min(feedbackStats.totalFeedbacks * 2, 100) // 50회 피드백 = 100% 학습
      },
      vehicleStats: {
        vehicleId,
        totalViews: feedbackStats.vehicleViews,
        totalLikes: feedbackStats.vehicleLikes,
        totalContacts: feedbackStats.vehicleContacts,
        popularityScore: calculatePopularityScore(feedbackStats)
      },
      metadata: {
        timestamp: new Date().toISOString(),
        processingTime,
        systemStatus: processingTime < 100 ? '🟢 최적' : processingTime < 500 ? '🟡 양호' : '🔴 개선필요'
      }
    });

  } catch (error) {
    console.error('❌ 피드백 처리 에러:', error);

    const processingTime = Date.now() - feedbackStartTime;

    return NextResponse.json({
      success: false,
      error: error instanceof Error ? error.message : '알 수 없는 오류',
      timestamp: new Date().toISOString(),
      processingTime,
      troubleshooting: {
        database: '데이터베이스 연결을 확인하세요',
        schema: 'user_feedback, learned_weights 테이블이 존재하는지 확인하세요',
        permissions: '데이터베이스 쓰기 권한을 확인하세요'
      }
    }, { status: 500 });
  }
}

/**
 * 사용자 가중치 조회
 */
async function getUserWeights(userId: string) {
  try {
    const result = await pool.query(`
      SELECT price_weight, safety_weight, brand_weight, efficiency_weight, year_weight, mileage_weight
      FROM learned_weights
      WHERE user_id = $1
    `, [userId]);

    if (result.rows.length === 0) {
      // 기본 가중치 반환
      return {
        price_weight: 0.25,
        safety_weight: 0.20,
        brand_weight: 0.20,
        efficiency_weight: 0.15,
        year_weight: 0.10,
        mileage_weight: 0.10
      };
    }

    return result.rows[0];
  } catch (error) {
    console.warn('⚠️ 가중치 조회 실패, 기본값 사용:', error);
    return {
      price_weight: 0.25,
      safety_weight: 0.20,
      brand_weight: 0.20,
      efficiency_weight: 0.15,
      year_weight: 0.10,
      mileage_weight: 0.10
    };
  }
}

/**
 * 액션 타입에 따른 가중치 업데이트 로직
 */
function updateWeights(currentWeights: any, actionType: string, vehicleId: string) {
  const learningRate = 0.05; // 학습률 (5%)
  const updatedWeights = { ...currentWeights };

  switch (actionType) {
    case 'like':
      // 좋아요는 전체적인 선호도를 높임 (특히 브랜드, 가격)
      updatedWeights.brand_weight = Math.min(1.0, updatedWeights.brand_weight + learningRate * 0.8);
      updatedWeights.price_weight = Math.min(1.0, updatedWeights.price_weight + learningRate * 0.6);
      break;

    case 'contact':
      // 연락하기는 가격에 대한 관심이 높음을 의미
      updatedWeights.price_weight = Math.min(1.0, updatedWeights.price_weight + learningRate * 1.2);
      updatedWeights.safety_weight = Math.min(1.0, updatedWeights.safety_weight + learningRate * 0.8);
      break;

    case 'view':
      // 조회는 가벼운 관심 표시
      updatedWeights.brand_weight = Math.min(1.0, updatedWeights.brand_weight + learningRate * 0.3);
      break;
  }

  // 가중치 합계가 1.0을 유지하도록 정규화
  const totalWeight = Object.values(updatedWeights).reduce((sum: number, weight: any) => sum + weight, 0);
  if (totalWeight > 0) {
    Object.keys(updatedWeights).forEach(key => {
      updatedWeights[key] = updatedWeights[key] / totalWeight;
    });
  }

  return updatedWeights;
}

/**
 * 업데이트된 가중치 저장
 */
async function saveUserWeights(userId: string, weights: any) {
  try {
    await pool.query(`
      INSERT INTO learned_weights (
        user_id, price_weight, safety_weight, brand_weight,
        efficiency_weight, year_weight, mileage_weight, updated_at
      )
      VALUES ($1, $2, $3, $4, $5, $6, $7, NOW())
      ON CONFLICT (user_id)
      DO UPDATE SET
        price_weight = $2,
        safety_weight = $3,
        brand_weight = $4,
        efficiency_weight = $5,
        year_weight = $6,
        mileage_weight = $7,
        updated_at = NOW()
    `, [
      userId,
      weights.price_weight,
      weights.safety_weight,
      weights.brand_weight,
      weights.efficiency_weight,
      weights.year_weight,
      weights.mileage_weight
    ]);
  } catch (error) {
    console.error('❌ 가중치 저장 실패:', error);
    throw error;
  }
}

/**
 * 피드백 통계 계산
 */
async function calculateFeedbackStats(userId: string, vehicleId: string) {
  try {
    // 사용자 전체 피드백 통계
    const userStats = await pool.query(`
      SELECT
        COUNT(*) as total_feedbacks,
        COUNT(CASE WHEN action_type = 'like' THEN 1 END) as like_count,
        COUNT(CASE WHEN action_type = 'view' THEN 1 END) as view_count,
        COUNT(CASE WHEN action_type = 'contact' THEN 1 END) as contact_count
      FROM user_feedback
      WHERE user_id = $1
    `, [userId]);

    // 차량별 피드백 통계
    const vehicleStats = await pool.query(`
      SELECT
        COUNT(CASE WHEN action_type = 'view' THEN 1 END) as vehicle_views,
        COUNT(CASE WHEN action_type = 'like' THEN 1 END) as vehicle_likes,
        COUNT(CASE WHEN action_type = 'contact' THEN 1 END) as vehicle_contacts
      FROM user_feedback
      WHERE vehicle_id = $1
    `, [vehicleId]);

    const userRow = userStats.rows[0];
    const vehicleRow = vehicleStats.rows[0];

    return {
      totalFeedbacks: parseInt(userRow.total_feedbacks),
      likeCount: parseInt(userRow.like_count),
      viewCount: parseInt(userRow.view_count),
      contactCount: parseInt(userRow.contact_count),
      vehicleViews: parseInt(vehicleRow.vehicle_views),
      vehicleLikes: parseInt(vehicleRow.vehicle_likes),
      vehicleContacts: parseInt(vehicleRow.vehicle_contacts)
    };

  } catch (error) {
    console.warn('⚠️ 통계 계산 실패:', error);
    return {
      totalFeedbacks: 0,
      likeCount: 0,
      viewCount: 0,
      contactCount: 0,
      vehicleViews: 0,
      vehicleLikes: 0,
      vehicleContacts: 0
    };
  }
}

/**
 * 가중치 변화량 계산
 */
function calculateWeightChange(previous: any, updated: any) {
  let totalChange = 0;
  Object.keys(previous).forEach(key => {
    totalChange += Math.abs(updated[key] - previous[key]);
  });
  return Math.round(totalChange * 100); // 0-100 스케일
}

/**
 * 차량 인기도 점수 계산
 */
function calculatePopularityScore(stats: any) {
  const { vehicleViews, vehicleLikes, vehicleContacts } = stats;

  // 가중치: 연락하기(3점) > 좋아요(2점) > 조회(1점)
  const score = (vehicleContacts * 3) + (vehicleLikes * 2) + (vehicleViews * 1);

  // 0-100 스케일로 정규화 (50회 상호작용 = 100점)
  return Math.min(100, Math.round(score * 2));
}

import { NextRequest, NextResponse } from 'next/server';

export async function GET(request: NextRequest) {
  const { searchParams } = new URL(request.url);
  const detailUrl = searchParams.get('detailUrl');

  if (!detailUrl) {
    return NextResponse.json({ error: 'detailUrl is required' }, { status: 400 });
  }

  try {
    console.log('🔍 Fetching vehicle page:', detailUrl);

    // 엔카 매물 페이지 HTML 가져오기
    const response = await fetch(detailUrl, {
      headers: {
        'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/120.0.0.0 Safari/537.36',
        'Accept': 'text/html,application/xhtml+xml,application/xml;q=0.9,image/webp,image/apng,*/*;q=0.8',
        'Accept-Language': 'ko-KR,ko;q=0.9,en;q=0.8',
        'Accept-Encoding': 'gzip, deflate, br',
        'Referer': 'https://www.encar.com/',
        'Cache-Control': 'no-cache',
      },
    });

    if (!response.ok) {
      console.log('❌ Failed to fetch page:', response.status);
      return NextResponse.json({ error: 'Failed to fetch page' }, { status: response.status });
    }

    const html = await response.text();
    console.log('✅ Page fetched, length:', html.length);

    // 이미지 URL 추출을 위한 정규식 패턴들
    const imagePatterns = [
      // 엔카 carpicture 패턴 (가장 우선)
      /https:\/\/img1\.encar\.com\/carpicture[^"'\s]+\.jpg/gi,
      /https:\/\/img2\.encar\.com\/carpicture[^"'\s]+\.jpg/gi,
      /https:\/\/img3\.encar\.com\/carpicture[^"'\s]+\.jpg/gi,
      /https:\/\/img4\.encar\.com\/carpicture[^"'\s]+\.jpg/gi,
      /https:\/\/img\.encar\.com\/carpicture[^"'\s]+\.jpg/gi,
      // 기타 엔카 이미지 패턴
      /https:\/\/img1\.encar\.com\/[^"'\s]+\.jpg/gi,
      /https:\/\/img2\.encar\.com\/[^"'\s]+\.jpg/gi,
      /https:\/\/img3\.encar\.com\/[^"'\s]+\.jpg/gi,
      /https:\/\/img4\.encar\.com\/[^"'\s]+\.jpg/gi,
      // src 속성에서 직접 추출
      /src=["']([^"']*carpicture[^"']*\.jpg)["']/gi,
      /src=["']([^"']*img\d*\.encar\.com[^"']*\.jpg)["']/gi,
      // 일반적인 이미지 패턴
      /"(https:\/\/[^"]*carpicture[^"]*\.jpg)"/gi,
      /'(https:\/\/[^']*carpicture[^']*\.jpg)'/gi,
    ];

    const imageUrls: string[] = [];

    // 모든 패턴으로 이미지 URL 추출
    for (const pattern of imagePatterns) {
      const matches = html.match(pattern);
      if (matches) {
        imageUrls.push(...matches.map(url => url.replace(/['"]/g, '')));
      }
    }

    // 중복 제거 및 필터링
    const uniqueImages = [...new Set(imageUrls)]
      .filter(url => {
        // 차량 이미지일 가능성이 높은 URL만 선택 (우선순위 기준)
        if (url.includes('carpicture')) return true; // 가장 높은 우선순위
        if (url.includes('logo') || url.includes('brand_logo')) return false; // 로고 제외
        if (url.includes('icon') || url.includes('button')) return false; // 아이콘 제외
        if (url.includes('banner') || url.includes('popup')) return false; // 배너 제외
        if (url.includes('encar') && url.includes('.jpg')) return true; // 엔카 이미지
        return false;
      })
      .sort((a, b) => {
        // carpicture가 포함된 이미지를 우선순위로 정렬
        if (a.includes('carpicture') && !b.includes('carpicture')) return -1;
        if (!a.includes('carpicture') && b.includes('carpicture')) return 1;
        return 0;
      })
      .slice(0, 10); // 최대 10개만

    console.log('🖼️ Found images:', uniqueImages.length);
    uniqueImages.forEach((url, index) => {
      console.log(`  ${index + 1}. ${url}`);
    });

    if (uniqueImages.length === 0) {
      // 이미지를 찾지 못한 경우 HTML에서 다른 패턴 시도
      console.log('🔍 Trying alternative patterns...');

      // 모든 이미지 URL 추출해서 분석
      const allImageMatches = html.match(/src=["']([^"']*\.jpg[^"']*)["']/gi);
      if (allImageMatches) {
        console.log('📸 All found image sources:');
        allImageMatches.slice(0, 20).forEach((match, index) => {
          const url = match.replace(/src=["']|["']/g, '');
          console.log(`  ${index + 1}. ${url}`);
        });

        const srcImages = allImageMatches
          .map(match => match.replace(/src=["']|["']/g, ''))
          .filter(url => url.startsWith('http') && !url.includes('logo') && !url.includes('icon'))
          .slice(0, 5);
        uniqueImages.push(...srcImages);
      }

      // 추가로 백그라운드 이미지도 검색
      const bgImageMatches = html.match(/background-image:\s*url\(["']?([^"']*\.jpg[^"']*)["']?\)/gi);
      if (bgImageMatches) {
        console.log('🎨 Background images found:');
        bgImageMatches.forEach((match, index) => {
          console.log(`  ${index + 1}. ${match}`);
        });
      }
    }

    return NextResponse.json({
      success: true,
      detailUrl,
      images: uniqueImages,
      count: uniqueImages.length,
      primaryImage: uniqueImages[0] || null,
    });

  } catch (error) {
    console.error('🚨 Error fetching vehicle image:', error);
    return NextResponse.json({
      success: false,
      error: error instanceof Error ? error.message : 'Unknown error',
      detailUrl,
    }, { status: 500 });
  }
}

