/**
 * 🎯 Alibaba 개인화 추천 API
 * RecSys 2019 논문 기반 실시간 개인화 Re-ranking
 */

import { NextRequest, NextResponse } from 'next/server';
import UserProfileLearner from '@/lib/alibaba/UserProfileLearner';
import { VehicleTOPSISEvaluator } from '@/lib/topsis/TOPSISEngine';

export async function POST(request: NextRequest) {
  const startTime = Date.now();

  try {
    console.log('🎯 Alibaba 개인화 추천 시작');

    const { vehicles, userMessages, currentUserId } = await request.json();

    if (!vehicles || !Array.isArray(vehicles)) {
      return NextResponse.json({ error: 'Vehicles array required' }, { status: 400 });
    }

    // 1. 사용자 프로필 학습
    console.log('🧠 사용자 프로필 학습 시작');
    const profileLearner = new UserProfileLearner();

    let userProfile;
    if (userMessages && userMessages.length > 0) {
      // 대화 기반 프로필 학습
      userProfile = await profileLearner.learnFromConversation(
        userMessages.map((msg: any) => ({
          role: 'user',
          content: msg.content || msg,
          timestamp: new Date()
        }))
      );
      console.log('✅ 대화 기반 프로필 학습 완료');
    } else {
      // 기본 프로필 사용
      userProfile = {
        priceWeight: 0.25,
        performanceWeight: 0.15,
        brandWeight: 0.15,
        fuelEfficiencyWeight: 0.2,
        safetyWeight: 0.15,
        designWeight: 0.1
      };
      console.log('✅ 기본 프로필 사용');
    }

    // 2. TOPSIS 기반 개인화 랭킹
    console.log('📊 TOPSIS 개인화 랭킹 시작');
    const topsisEvaluator = new VehicleTOPSISEvaluator();

    // 최대 50대까지만 처리 (성능 최적화)
    const vehiclesToRank = vehicles.slice(0, 50);

    const topsisResult = await topsisEvaluator.evaluateVehicles(vehiclesToRank, userProfile);
    console.log('✅ TOPSIS 랭킹 완료');

    // 3. Alibaba 스타일 Re-ranking 적용
    const personalizedVehicles = topsisResult.ranking.map((item, index) => {
      const vehicle = item.alternative.metadata;

      // Alibaba 논문 스타일: 개인화 점수 계산
      const personalizationBoost = calculatePersonalizationBoost(vehicle, userProfile);
      const finalScore = item.score * (1 + personalizationBoost);

      return {
        ...vehicle,
        rank: index + 1,
        topsisScore: item.score,
        personalizedScore: finalScore,
        personalizationBoost,
        personalizedRank: index + 1, // 재정렬 후 업데이트됨
        personalizationReasons: getPersonalizationReasons(vehicle, userProfile)
      };
    });

    // 4. 개인화 점수 기준으로 재정렬
    personalizedVehicles.sort((a, b) => b.personalizedScore - a.personalizedScore);

    // 개인화된 순위 업데이트
    personalizedVehicles.forEach((vehicle, index) => {
      vehicle.personalizedRank = index + 1;
    });

    const processingTime = Date.now() - startTime;
    console.log(`🎯 개인화 추천 완료: ${processingTime}ms`);

    // 5. 개인화 효과 분석
    const personalizationImpact = analyzePersonalizationImpact(
      topsisResult.ranking,
      personalizedVehicles
    );

    return NextResponse.json({
      success: true,
      personalizedVehicles,
      userProfile,
      personalizationImpact,
      processingTime,
      message: `${vehicles.length}대 차량을 사용자 선호도에 맞춰 개인화했습니다`
    });

  } catch (error) {
    console.error('❌ 개인화 추천 실패:', error);

    return NextResponse.json({
      error: 'Personalization failed',
      message: '개인화 추천 중 문제가 발생했습니다',
      processingTime: Date.now() - startTime
    }, { status: 500 });
  }
}

/**
 * 🚀 개인화 부스트 계산 (Alibaba 논문 스타일)
 */
function calculatePersonalizationBoost(vehicle: any, userProfile: any): number {
  let boost = 0;

  // 가격 개인화
  if (userProfile.priceWeight > 0.3) {
    // 가격 중시 사용자 - 저렴한 차량에 부스트
    const priceScore = Math.max(0, 1 - (vehicle.price / 10000)); // 정규화
    boost += priceScore * 0.2;
  }

  // 브랜드 개인화
  if (userProfile.brandWeight > 0.2) {
    // 브랜드 중시 사용자 - 프리미엄 브랜드에 부스트
    const premiumBrands = ['벤츠', 'BMW', '아우디', 'Mercedes-Benz', 'Genesis'];
    const brand = vehicle.manufacturer || '';
    if (premiumBrands.some(b => brand.includes(b))) {
      boost += 0.15;
    }
  }

  // 연비 개인화
  if (userProfile.fuelEfficiencyWeight > 0.25) {
    // 연비 중시 사용자 - 하이브리드/전기차에 부스트
    const fuelType = vehicle.fuel_type || '';
    if (fuelType.includes('하이브리드') || fuelType.includes('전기')) {
      boost += 0.2;
    }
  }

  // 연식 개인화
  if (userProfile.safetyWeight > 0.2) {
    // 안전 중시 사용자 - 최신 차량에 부스트
    const year = vehicle.model_year || vehicle.year;
    if (year >= 2022) {
      boost += 0.1;
    }
  }

  return Math.min(boost, 0.5); // 최대 50% 부스트
}

/**
 * 📝 개인화 이유 설명
 */
function getPersonalizationReasons(vehicle: any, userProfile: any): string[] {
  const reasons: string[] = [];

  if (userProfile.priceWeight > 0.3 && vehicle.price < 5000) {
    reasons.push('가격 대비 가치');
  }

  if (userProfile.brandWeight > 0.2) {
    const premiumBrands = ['벤츠', 'BMW', '아우디', 'Mercedes-Benz', 'Genesis'];
    const brand = vehicle.manufacturer || '';
    if (premiumBrands.some(b => brand.includes(b))) {
      reasons.push('프리미엄 브랜드');
    }
  }

  if (userProfile.fuelEfficiencyWeight > 0.25) {
    const fuelType = vehicle.fuel_type || '';
    if (fuelType.includes('하이브리드') || fuelType.includes('전기')) {
      reasons.push('우수한 연비');
    }
  }

  if (userProfile.safetyWeight > 0.2) {
    const year = vehicle.model_year || vehicle.year;
    if (year >= 2022) {
      reasons.push('최신 안전 기술');
    }
  }

  return reasons.length > 0 ? reasons : ['기본 추천'];
}

/**
 * 📊 개인화 효과 분석
 */
function analyzePersonalizationImpact(originalRanking: any[], personalizedVehicles: any[]) {
  let significantChanges = 0;
  let totalRankChange = 0;

  originalRanking.forEach((original, index) => {
    const personalized = personalizedVehicles.find(p =>
      p.vehicle_id === original.alternative.metadata.vehicle_id
    );

    if (personalized) {
      const rankChange = Math.abs(index + 1 - personalized.personalizedRank);
      totalRankChange += rankChange;

      if (rankChange >= 3) {
        significantChanges++;
      }
    }
  });

  return {
    significantChanges,
    averageRankChange: totalRankChange / originalRanking.length,
    personalizationStrength: totalRankChange > 10 ? 'high' :
                            totalRankChange > 5 ? 'medium' : 'low'
  };
}

import { NextRequest, NextResponse } from 'next/server';

export async function GET(request: NextRequest) {
