          <!-- 차량 본체 -->
          <path d="M-80,-40 C-85,-45 -75,-50 -60,-45 L60,-45 C75,-50 85,-45 80,-40 L80,30 C80,35 75,40 70,40 L65,40 C58,40 52,35 52,30 L52,20 L-52,20 L-52,30 C-52,35 -58,40 -65,40 L-70,40 C-75,40 -80,35 -80,30 Z" fill="url(#carGradient)"/>

          <!-- 앞/뒤 범퍼 -->
          <rect x="-85" y="15" width="10" height="15" rx="5" fill="#1e40af"/>
