          <circle cx="-45" cy="35" r="12" fill="#1f2937"/>
          <circle cx="-45" cy="35" r="8" fill="#374151"/>
          <circle cx="45" cy="35" r="12" fill="#1f2937"/>
          <circle cx="45" cy="35" r="8" fill="#374151"/>

          <!-- 앞유리/뒷유리 -->
          <path d="M-60,-35 L-20,-40 L20,-40 L60,-35 L60,-25 L-60,-25 Z" fill="#bfdbfe" opacity="0.8"/>

          <!-- 사이드 창문 -->
          <rect x="-55" y="-35" width="35" height="20" rx="3" fill="#bfdbfe" opacity="0.7"/>
          <rect x="20" y="-35" width="35" height="20" rx="3" fill="#bfdbfe" opacity="0.7"/>

          <!-- 헤드라이트 -->
          <ellipse cx="-70" cy="-20" rx="8" ry="6" fill="#fbbf24"/>
          <ellipse cx="70" cy="-20" rx="8" ry="6" fill="#fbbf24"/>

          <!-- 그릴 -->
