      }
    } catch (error) {
      console.log(`⚠️ 캐시 테스트 중 오류: ${error.message}, 캐시 없이 계속 진행...`);
      isSystemReady = false;
      responseTime = 0;
    }

    // AWS Valkey vs 로컬 캐시 확인
    const isAWSValkey = await redis.testConnection();
    const cacheType = isAWSValkey ? 'AWS Valkey' : '로컬 고성능 캐시';
    console.log(`🏗️ 활성 캐시 시스템: ${cacheType}`);

    // 2. 기본 SET/GET 테스트
