    priceMax: user?.preferences?.budget?.max || 10000,
    manufacturer: '',
    carType: '',
    fuelType: '',
    yearMin: 2015,
    yearMax: 2024
  });
  const [sortBy, setSortBy] = useState<'topsisScore' | 'price' | 'year' | 'mileage'>('topsisScore');
  const [searchQuery, setSearchQuery] = useState('');
  const [fastMode, setFastMode] = useState(false);
  const [compareList, setCompareList] = useState<string[]>([]);
  const [showCompareModal, setShowCompareModal] = useState(false);

  // 사용자가 로그인하지 않았으면 게스트로 자동 로그인
  useEffect(() => {
    if (!isLoggedIn) {
      loginAsGuest();
    }
  }, [isLoggedIn, loginAsGuest]);

  // URL 파라미터에서 검색어와 모드 추출
  useEffect(() => {
    const urlParams = new URLSearchParams(window.location.search);
    const query = urlParams.get('query');
    const mode = urlParams.get('mode');

    if (query) {
      setSearchQuery(query);
      console.log(`🎯 스마트 라우팅으로 도착: "${query}"`);
    }

    if (mode === 'fast') {
      setFastMode(true);
      console.log('🚀 빠른 모드 활성화 - 즉시 TOPSIS 결과 표시');
    }
  }, []);

  // 검색어가 설정되면 자동으로 데이터 로드
  useEffect(() => {
    if (searchQuery) {
      loadDashboardData();
    }
  }, [searchQuery]);

  // 🎯 실시간 대시보드 데이터 로드
  const loadDashboardData = async () => {
    setLoading(true);
    try {
      // 동적 쿼리 사용 (URL 파라미터 기반)
      const query = searchQuery || '가족용 SUV';
      const response = await fetch(`/api/dashboard/ranking?query=${encodeURIComponent(query)}&limit=15&budget_min=2000&budget_max=8000`);
      const data = await response.json();

      if (data.success) {
        setDashboardData(data);
        setVehicles(data.dashboardResults?.topVehicles || []);
      } else {
        console.error('대시보드 데이터 로드 실패:', data.error);
      }
    } catch (error) {
      console.error('대시보드 API 호출 실패:', error);
    } finally {
      setLoading(false);
    }
  };

  // 🚀 사용자 피드백 제출 (실시간 학습용)
  const submitFeedback = async (vehicleId: string, actionType: 'like' | 'view' | 'contact') => {
    const feedback: UserFeedback = {
      vehicleId,
      actionType,
      timestamp: Date.now()
    };

    // 로컬 상태 업데이트 (즉시 반영)
    setUserFeedback(prev => [...prev, feedback]);

    try {
      await fetch('/api/feedback/submit', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          userId: 'dashboard_user', // 실제로는 세션에서 가져옴
          vehicleId,
          actionType
        })
      });

      // 피드백 후 추천 결과 업데이트
      await loadDashboardData();
    } catch (error) {
      console.error('피드백 제출 실패:', error);
    }
  };

  // 🔄 비교 리스트 관리
  const handleCompareToggle = (vehicleId: string, selected: boolean) => {
    setCompareList(prev => {
      if (selected) {
