        if (prev.length >= 3) {
          alert('최대 3개 차량까지만 비교할 수 있습니다.');
          return prev;
        }
        return [...prev, vehicleId];
      } else {
        return prev.filter(id => id !== vehicleId);
      }
    });
  };

  // 🔄 필터링된 차량 목록
  const filteredVehicles = vehicles.filter(vehicle => {
    const matchesSearch = searchQuery === '' ||
      vehicle.manufacturer.toLowerCase().includes(searchQuery.toLowerCase()) ||
      vehicle.model.toLowerCase().includes(searchQuery.toLowerCase());

    const matchesFilters =
      vehicle.price >= filters.priceMin &&
      vehicle.price <= filters.priceMax &&
      (filters.manufacturer === '' || vehicle.manufacturer === filters.manufacturer) &&
      (filters.carType === '' || vehicle.carType === filters.carType) &&
      (filters.fuelType === '' || vehicle.fuelType === filters.fuelType) &&
      vehicle.year >= filters.yearMin &&
      vehicle.year <= filters.yearMax;

    return matchesSearch && matchesFilters;
  }).sort((a, b) => {
    switch (sortBy) {
      case 'topsisScore':
        return b.topsisScore - a.topsisScore;
      case 'price':
        return a.price - b.price;
      case 'year':
        return b.year - a.year;
      case 'mileage':
        return a.mileage - b.mileage;
      default:
        return 0;
    }
  });

  useEffect(() => {
    loadDashboardData();
  }, []);

  if (loading) {
    return (
      <div className="min-h-screen bg-gradient-to-br from-blue-50 via-purple-50 to-pink-50 flex items-center justify-center">
        <div className="text-center">
          <div className="animate-spin rounded-full h-32 w-32 border-b-2 border-blue-600 mx-auto"></div>
          <p className="text-lg text-gray-600 mt-4">AI 추천 시스템 분석 중...</p>
          <p className="text-sm text-gray-500">논문 기반 TOPSIS 알고리즘 적용</p>
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gradient-to-br from-blue-50 via-purple-50 to-pink-50">
      {/* 헤더 */}
      <div className="bg-white shadow-sm border-b">
        <div className="max-w-7xl mx-auto px-6 py-4">
          <div className="flex items-center justify-between">
            <div>
              <h1 className="text-3xl font-bold text-gray-900">AI 차량 추천 대시보드</h1>
              <p className="text-gray-600">논문 기반 TOPSIS + Alibaba RecSys 알고리즘</p>
            </div>

            {/* 성능 메트릭 및 사용자 정보 */}
            <div className="flex items-center gap-4 text-sm">
              {dashboardData && (
                <>
                  <div className="bg-green-100 text-green-800 px-3 py-1 rounded-lg">
                    <div className="flex items-center gap-1">
                      <Zap className="w-4 h-4" />
                      {dashboardData.performance?.dashboardProcessingTime}ms
                    </div>
                  </div>
                  <div className="bg-blue-100 text-blue-800 px-3 py-1 rounded-lg">
                    <div className="flex items-center gap-1">
                      <TrendingUp className="w-4 h-4" />
                      {dashboardData.dashboardResults?.totalProcessed}대 분석
                    </div>
                  </div>
                  <div className="bg-purple-100 text-purple-800 px-3 py-1 rounded-lg">
                    <div className="flex items-center gap-1">
                      <Users className="w-4 h-4" />
                      실시간 학습: {userFeedback.length}회
                    </div>
                  </div>
                </>
              )}

              {/* 사용자 정보 */}
              {user && (
                <div className="bg-gray-100 text-gray-800 px-3 py-1 rounded-lg">
                  <div className="flex items-center gap-1">
                    <User className="w-4 h-4" />
                    {user.name} • 즐겨찾기 {user.favoriteVehicles.length}개
                  </div>
                </div>
              )}
            </div>
          </div>
        </div>
      </div>

      {/* 검색 및 필터 */}
      <div className="max-w-7xl mx-auto px-6 py-6">
        <div className="bg-white rounded-xl shadow-sm p-6 mb-6">
          <div className="flex items-center gap-4 mb-4">
            <div className="relative flex-1">
              <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 text-gray-400 w-5 h-5" />
              <input
                type="text"
                placeholder="차량 검색 (제조사, 모델명)"
                className="w-full pl-10 pr-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500 focus:border-transparent"
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
              />
            </div>

            <select
              className="px-4 py-2 border border-gray-300 rounded-lg focus:ring-2 focus:ring-blue-500"
              value={sortBy}
              onChange={(e) => setSortBy(e.target.value as any)}
            >
              <option value="topsisScore">TOPSIS 점수순</option>
              <option value="price">가격순</option>
              <option value="year">연식순</option>
              <option value="mileage">주행거리순</option>
            </select>
          </div>

          {/* 필터 컨트롤 */}
          <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">가격 범위 (만원)</label>
              <div className="flex gap-2">
                <input
                  type="number"
                  placeholder="최소"
                  className="w-full px-3 py-1 border border-gray-300 rounded text-sm"
                  value={filters.priceMin}
                  onChange={(e) => setFilters(prev => ({ ...prev, priceMin: Number(e.target.value) }))}
                />
                <input
                  type="number"
                  placeholder="최대"
                  className="w-full px-3 py-1 border border-gray-300 rounded text-sm"
                  value={filters.priceMax}
                  onChange={(e) => setFilters(prev => ({ ...prev, priceMax: Number(e.target.value) }))}
                />
              </div>
            </div>

            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">제조사</label>
              <select
                className="w-full px-3 py-1 border border-gray-300 rounded text-sm"
                value={filters.manufacturer}
                onChange={(e) => setFilters(prev => ({ ...prev, manufacturer: e.target.value }))}
              >
                <option value="">전체</option>
                <option value="현대">현대</option>
                <option value="기아">기아</option>
                <option value="BMW">BMW</option>
                <option value="벤츠">벤츠</option>
                <option value="토요타">토요타</option>
              </select>
            </div>

            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">차종</label>
              <select
                className="w-full px-3 py-1 border border-gray-300 rounded text-sm"
                value={filters.carType}
                onChange={(e) => setFilters(prev => ({ ...prev, carType: e.target.value }))}
              >
                <option value="">전체</option>
                <option value="SUV">SUV</option>
                <option value="세단">세단</option>
                <option value="해치백">해치백</option>
                <option value="쿠페">쿠페</option>
              </select>
            </div>

            <div>
              <label className="block text-sm font-medium text-gray-700 mb-1">연료</label>
              <select
                className="w-full px-3 py-1 border border-gray-300 rounded text-sm"
                value={filters.fuelType}
                onChange={(e) => setFilters(prev => ({ ...prev, fuelType: e.target.value }))}
              >
                <option value="">전체</option>
                <option value="gasoline">가솔린</option>
                <option value="hybrid">하이브리드</option>
                <option value="electric">전기</option>
                <option value="diesel">디젤</option>
              </select>
            </div>
          </div>
        </div>

        {/* 비교 기능 바 */}
        {compareList.length > 0 && (
          <div className="bg-green-50 border border-green-200 rounded-lg p-4 mb-6">
            <div className="flex items-center justify-between">
              <div className="flex items-center gap-2">
                <GitCompare className="w-5 h-5 text-green-600" />
                <span className="font-medium text-green-800">
                  비교할 차량 {compareList.length}개 선택됨
                </span>
              </div>
              <div className="flex gap-2">
                {compareList.length >= 2 && (
                  <button
                    onClick={() => setShowCompareModal(true)}
                    className="bg-green-600 text-white px-4 py-2 rounded-lg text-sm font-medium hover:bg-green-700 transition-colors"
                  >
                    비교하기
                  </button>
                )}
                <button
                  onClick={() => setCompareList([])}
                  className="bg-gray-100 text-gray-700 px-4 py-2 rounded-lg text-sm font-medium hover:bg-gray-200 transition-colors"
                >
                  모두 제거
                </button>
              </div>
            </div>
            <div className="flex gap-2 mt-2 flex-wrap">
              {compareList.map(vehicleId => {
                const vehicle = filteredVehicles.find(v => v.id === vehicleId);
                return vehicle ? (
                  <span
                    key={vehicleId}
                    className="bg-white border border-green-200 rounded px-3 py-1 text-sm text-green-800 flex items-center gap-1"
                  >
                    {vehicle.manufacturer} {vehicle.model}
                    <button
                      onClick={() => handleCompareToggle(vehicleId, false)}
                      className="text-green-600 hover:text-green-800 ml-1"
                    >
                      ×
                    </button>
                  </span>
                ) : null;
              })}
            </div>
          </div>
        )}

        {/* 차량 카드 목록 */}
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
          {filteredVehicles.map((vehicle, index) => (
            <VehicleCard
              key={`${vehicle.id}-${vehicle.rank}-${index}`}
              vehicle={vehicle}
              onFeedback={submitFeedback}
              userFeedback={userFeedback.filter(f => f.vehicleId === vehicle.id)}
              onCompareToggle={handleCompareToggle}
              isCompareSelected={compareList.includes(vehicle.id)}
            />
          ))}
        </div>

        {filteredVehicles.length === 0 && (
          <div className="text-center py-12">
            <p className="text-gray-500 text-lg">조건에 맞는 차량이 없습니다.</p>
            <p className="text-gray-400 text-sm">필터 조건을 조정해보세요.</p>
          </div>
        )}
      </div>
    </div>
  );
}

// 🚗 차량 카드 컴포넌트
interface VehicleCardProps {
  vehicle: DashboardVehicle;
  onFeedback: (vehicleId: string, actionType: 'like' | 'view' | 'contact') => void;
  userFeedback: UserFeedback[];
  onCompareToggle?: (vehicleId: string, selected: boolean) => void;
  isCompareSelected?: boolean;
}

function VehicleCard({ vehicle, onFeedback, userFeedback, onCompareToggle, isCompareSelected = false }: VehicleCardProps) {
  const { user, isLoggedIn, loginAsGuest, toggleFavorite, isFavorite } = useAuth();
  const hasLiked = userFeedback.some(f => f.actionType === 'like');
  const viewCount = userFeedback.filter(f => f.actionType === 'view').length;

  return (
    <div
      className="bg-white rounded-xl shadow-sm hover:shadow-md transition-shadow duration-200 overflow-hidden border"
      onClick={() => onFeedback(vehicle.id, 'view')}
    >
      {/* 랭킹 배지 */}
      <div className="relative">
        <div className="absolute top-3 left-3 z-10">
          <div className="bg-gradient-to-r from-blue-600 to-purple-600 text-white px-3 py-1 rounded-lg text-sm font-bold">
            #{vehicle.rank}
          </div>
        </div>
        <div className="absolute top-3 right-3 z-10">
          <div className="bg-black bg-opacity-50 text-white px-2 py-1 rounded text-xs">
            TOPSIS: {vehicle.topsisScore}
          </div>
        </div>

        {/* 차량 이미지 */}
        <div className="h-48 bg-gray-200 flex items-center justify-center">
          {vehicle.photo ? (
            <img
              src={`/api/proxy-image?url=${encodeURIComponent(vehicle.photo)}`}
              alt={`${vehicle.manufacturer} ${vehicle.model}`}
              className="w-full h-full object-cover"
              onError={(e) => {
                const target = e.target as HTMLImageElement;
                target.style.display = 'none';
                target.nextElementSibling?.setAttribute('style', 'display: flex');
              }}
            />
          ) : null}
          <div className="text-gray-400 text-center" style={{ display: vehicle.photo ? 'none' : 'flex' }}>
            <div className="flex flex-col items-center">
              <div className="text-4xl mb-2">🚗</div>
              <div className="text-sm">이미지 준비중</div>
            </div>
          </div>
        </div>
      </div>

      {/* 차량 정보 */}
      <div className="p-4">
        <div className="flex items-center justify-between mb-2">
          <h3 className="text-lg font-bold text-gray-900">
            {vehicle.manufacturer} {vehicle.model}
          </h3>
          <div className="text-sm text-gray-500">{vehicle.year}년</div>
        </div>

        <div className="text-2xl font-bold text-blue-600 mb-3">
          {vehicle.price.toLocaleString()}만원
        </div>

        <div className="grid grid-cols-2 gap-2 text-sm text-gray-600 mb-3">
          <div>주행: {vehicle.mileage?.toLocaleString() || '정보없음'}km</div>
          <div>연료: {vehicle.fuelType}</div>
          <div>차종: {vehicle.carType}</div>
          <div>지역: {vehicle.location}</div>
        </div>

        {/* 추천 이유 */}
        <div className="bg-gray-50 rounded-lg p-3 mb-3">
          <p className="text-sm text-gray-700 leading-relaxed">
            {vehicle.recommendationReason}
          </p>
        </div>

        {/* 점수 표시 */}
        <div className="flex justify-between text-xs text-gray-500 mb-3">
          <span>가치: {vehicle.valueScore}/100</span>
          <span>신뢰: {vehicle.reliabilityScore}/100</span>
          <span>브랜드: {vehicle.brandScore}/100</span>
        </div>

        {/* 액션 버튼 */}
        <div className="flex gap-2">
          <button
            onClick={(e) => {
              e.stopPropagation();
              if (!isLoggedIn) {
                loginAsGuest();
              }
              toggleFavorite(vehicle.id);
            }}
            className={`flex items-center justify-center gap-1 py-2 px-3 rounded-lg text-sm font-medium transition-colors ${
              isFavorite(vehicle.id)
                ? 'bg-red-100 text-red-700 border border-red-200'
                : 'bg-gray-100 text-gray-700 hover:bg-gray-200'
            }`}
            title={isFavorite(vehicle.id) ? '즐겨찾기 해제' : '즐겨찾기 추가'}
          >
            <Heart className={`w-4 h-4 ${isFavorite(vehicle.id) ? 'fill-current' : ''}`} />
          </button>

          <button
            onClick={(e) => {
              e.stopPropagation();
              onCompareToggle?.(vehicle.id, !isCompareSelected);
            }}
            className={`flex items-center justify-center gap-1 py-2 px-3 rounded-lg text-sm font-medium transition-colors ${
              isCompareSelected
                ? 'bg-green-100 text-green-700 border border-green-200'
                : 'bg-gray-100 text-gray-700 hover:bg-gray-200'
            }`}
            title={isCompareSelected ? '비교에서 제거' : '비교 추가'}
          >
            <GitCompare className={`w-4 h-4 ${isCompareSelected ? 'text-green-600' : ''}`} />
          </button>

          <button
            onClick={(e) => {
              e.stopPropagation();
              onFeedback(vehicle.id, 'contact');
            }}
            className="flex-1 flex items-center justify-center gap-2 py-2 px-4 bg-blue-600 text-white rounded-lg text-sm font-medium hover:bg-blue-700 transition-colors"
          >
            <Phone className="w-4 h-4" />
            연락하기
          </button>
        </div>

        {/* 피드백 카운터 */}
        {viewCount > 0 && (
          <div className="text-xs text-gray-400 text-center mt-2">
            조회 {viewCount}회
          </div>
        )}
      </div>
    </div>
  );
}

