            </h2>
            <p className="text-gray-600">
              아래 질문을 선택하거나 직접 질문을 입력해보세요
            </p>
          </div>

          {/* 질문 카테고리별 그리드 */}
          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            {suggestedQuestions.map((category, categoryIndex) => (
              <Card key={categoryIndex} className="hover:shadow-lg transition-shadow">
                <CardHeader className="pb-3">
                  <CardTitle className="flex items-center gap-2 text-lg">
                    {category.icon}
                    {category.category}
                  </CardTitle>
                </CardHeader>
                <CardContent className="space-y-3">
                  {category.questions.map((question, questionIndex) => (
                    <Button
                      key={questionIndex}
                      variant="outline"
                      onClick={() => handleQuestionSelect(question)}
                      className="w-full text-left justify-between h-auto p-4 hover:bg-blue-50 hover:border-blue-300"
                    >
                      <span className="text-sm">{question}</span>
                      <ArrowRight className="w-4 h-4 text-gray-400" />
                    </Button>
                  ))}
                </CardContent>
              </Card>
            ))}
          </div>

          {/* 직접 질문 입력 */}
          <Card className="border-2 border-blue-200 bg-gradient-to-r from-blue-50 to-purple-50">
            <CardContent className="p-6">
              <div className="text-center space-y-4">
                <h3 className="text-xl font-bold text-gray-900">
                  직접 질문하기
                </h3>
                <p className="text-gray-600">
                  원하는 차량 조건을 자유롭게 말씀해주세요
                </p>
                <div className="max-w-md mx-auto">
                  <input
                    type="text"
                    placeholder="예: 2500만원대 연비 좋은 소형차 추천해주세요"
                    className="w-full px-4 py-3 border border-gray-300 rounded-lg focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-transparent"
                    onKeyPress={(e) => {
                      if (e.key === 'Enter') {
                        const question = (e.target as HTMLInputElement).value;
                        if (question.trim()) {
                          handleQuestionSelect(question);
                        }
                      }
                    }}
                  />
                  <p className="text-xs text-gray-500 mt-2">
                    Enter 키를 누르면 분석이 시작됩니다
                  </p>
                </div>
              </div>
            </CardContent>
          </Card>

          {/* 시스템 성능 정보 */}
          <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
            <Card className="text-center">
              <CardContent className="p-4">
                <div className="text-2xl font-bold text-blue-600 mb-1">127,378</div>
                <div className="text-sm text-gray-600">실제 차량 매물</div>
              </CardContent>
            </Card>
            <Card className="text-center">
              <CardContent className="p-4">
                <div className="text-2xl font-bold text-green-600 mb-1">&lt;3초</div>
                <div className="text-sm text-gray-600">평균 분석 시간</div>
              </CardContent>
            </Card>
            <Card className="text-center">
              <CardContent className="p-4">
                <div className="text-2xl font-bold text-purple-600 mb-1">95%</div>
                <div className="text-sm text-gray-600">추천 정확도</div>
              </CardContent>
            </Card>
          </div>
        </div>
      </div>
    </div>
  );
}

