export const metadata = {
  title: 'CarFin AI 성능 모니터링',
  description: '논문 3개 기반 CarFin AI 시스템의 실시간 성능 모니터링 대시보드'
};

'use client';

import { useState, useEffect, useCallback, useRef } from 'react';
import Link from 'next/link';
import { Send, Database, CheckCircle, Zap, Star, Shield, Search, TrendingUp, Users, Heart, BookOpen, Brain, ArrowRight, Keyboard, HelpCircle } from 'lucide-react';
import ChatRoom from '@/components/chat/ChatRoom';
import ErrorBoundary from '@/components/ui/ErrorBoundary';

interface DatabaseStatus {
  isConnected: boolean;
  totalVehicles: number;
  availableVehicles: number;
}

export default function Home() {
  const [question, setQuestion] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [showChatRoom, setShowChatRoom] = useState(false);
  const [initialQuestion, setInitialQuestion] = useState('');
  const [error, setError] = useState<Error | null>(null);
  const [showKeyboardShortcuts, setShowKeyboardShortcuts] = useState(false);
  const [dbStatus, setDbStatus] = useState<DatabaseStatus>({
    isConnected: false,
    totalVehicles: 0,
    availableVehicles: 0,
  });

  // Refs for accessibility
  const textareaRef = useRef<HTMLTextAreaElement>(null);
  const submitButtonRef = useRef<HTMLButtonElement>(null);

  // 키보드 단축키 지원
  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      // Ctrl/Cmd + Enter: 검색 실행
      if ((e.ctrlKey || e.metaKey) && e.key === 'Enter' && !isLoading && question.trim()) {
        e.preventDefault();
        handleSubmit();
      }

      // Alt + S: 검색창 포커스
      if (e.altKey && e.key === 's') {
        e.preventDefault();
        textareaRef.current?.focus();
      }

      // Ctrl/Cmd + /: 키보드 단축키 도움말 토글
      if ((e.ctrlKey || e.metaKey) && e.key === '/') {
        e.preventDefault();
        setShowKeyboardShortcuts(prev => !prev);
      }

      // Escape: 모달 닫기
      if (e.key === 'Escape') {
        setShowKeyboardShortcuts(false);
        setError(null);
      }
    };

    document.addEventListener('keydown', handleKeyDown);
    return () => document.removeEventListener('keydown', handleKeyDown);
  }, [isLoading, question]);

  // 데이터베이스 상태 실시간 체크 (향상된 오류 처리)
  useEffect(() => {
    const checkDatabase = async () => {
      try {
        const response = await fetch('/api/database/status');
        if (!response.ok) {
          throw new Error(`Database status check failed: ${response.status}`);
        }
        const data = await response.json();
        setDbStatus(data);
        setError(null); // 성공 시 에러 초기화
      } catch (error) {
        console.error('DB 상태 체크 실패:', error);
        setError(error as Error);
      }
    };

    checkDatabase();
    const interval = setInterval(checkDatabase, 10000); // 10초마다 체크 (부하 감소)
    return () => clearInterval(interval);
  }, []);

  const handleSubmit = async () => {
    if (!question.trim() || isLoading) return;

    setIsLoading(true);
    setError(null);

    try {
      console.log('🚀 Starting 3-paper based AI analysis system...');

      // 입력 검증
      if (question.length < 5) {
        throw new Error('좀 더 구체적으로 말씀해 주세요. 최소 5글자 이상 입력해 주세요.');
      }

      if (question.length > 1000) {
        throw new Error('입력이 너무 깁니다. 1000자 이하로 입력해 주세요.');
      }

      // 3논문 기반 고급 AI 채팅방으로 이동
      setInitialQuestion(question);
      setShowChatRoom(true);

    } catch (error) {
      console.error('Error starting chatroom:', error);
      setError(error as Error);
    } finally {
      setIsLoading(false);
    }
  };

  const handleRetry = () => {
    setError(null);
    if (question.trim()) {
      handleSubmit();
    }
  };



  const handleKeyPress = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && !isLoading) {
      handleSubmit();
    }
  };

  const handleBack = useCallback(() => {
    setShowChatRoom(false);
  }, []);


  // 키보드 단축키 도움말 컴포넌트
  const KeyboardShortcutsModal = () => {
    if (!showKeyboardShortcuts) return null;

    return (
      <div className="fixed inset-0 bg-black/50 backdrop-blur-sm z-50 flex items-center justify-center p-4">
        <div className="bg-white rounded-2xl shadow-2xl max-w-md w-full p-6">
          <div className="flex items-center justify-between mb-6">
            <h3 className="text-lg font-bold text-gray-900 flex items-center space-x-2">
              <Keyboard className="w-5 h-5" />
              <span>키보드 단축키</span>
            </h3>
            <button
              onClick={() => setShowKeyboardShortcuts(false)}
              className="p-1 hover:bg-gray-100 rounded transition-colors"
              aria-label="키보드 단축키 도움말 닫기"
            >
              <ArrowRight className="w-5 h-5 rotate-45" />
            </button>
          </div>

          <div className="space-y-3">
            <div className="flex justify-between items-center">
              <span className="text-gray-700">검색 실행</span>
              <kbd className="px-2 py-1 bg-gray-100 rounded text-sm font-mono">Ctrl + Enter</kbd>
            </div>
            <div className="flex justify-between items-center">
              <span className="text-gray-700">검색창 포커스</span>
              <kbd className="px-2 py-1 bg-gray-100 rounded text-sm font-mono">Alt + S</kbd>
            </div>
            <div className="flex justify-between items-center">
              <span className="text-gray-700">이 도움말 열기</span>
              <kbd className="px-2 py-1 bg-gray-100 rounded text-sm font-mono">Ctrl + /</kbd>
            </div>
            <div className="flex justify-between items-center">
              <span className="text-gray-700">모달 닫기</span>
              <kbd className="px-2 py-1 bg-gray-100 rounded text-sm font-mono">Esc</kbd>
            </div>
          </div>

          <div className="mt-6 p-4 bg-blue-50 rounded-lg">
            <p className="text-sm text-blue-700">
              💡 <strong>팁:</strong> 자연스럽게 대화하듯 입력하면 AI가 더 정확하게 이해해요!
            </p>
          </div>
        </div>
      </div>
    );
  };

  if (showChatRoom) {
    return (
      <ChatRoom
        initialQuestion={initialQuestion}
        onBack={handleBack}
      />
    );
  }

  // 오류 상태일 때 ErrorBoundary 표시
  if (error) {
    return (
      <div className="min-h-screen bg-gradient-to-br from-slate-50 via-white to-blue-50">
        <div className="container mx-auto px-6 py-16">
          <ErrorBoundary
            error={error}
            onRetry={handleRetry}
            onGoHome={() => {
              setError(null);
              setQuestion('');
            }}
          />
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gradient-to-br from-slate-50 via-white to-blue-50">

      {/* 실시간 데이터 상태 표시 */}
      <div className="fixed top-4 right-4 z-50">
        <div className={`px-4 py-2 rounded-full shadow-lg text-xs font-medium flex items-center space-x-2 ${
          dbStatus.isConnected
            ? 'bg-gradient-to-r from-green-500 to-emerald-500 text-white'
            : 'bg-red-500 text-white'
        }`}>
          <div className="w-2 h-2 bg-white rounded-full animate-pulse"></div>
          <span>{dbStatus.isConnected ? `${Math.round(dbStatus.totalVehicles / 1000)}K+ 실시간` : '연결 중...'}</span>
        </div>
      </div>

      <div className="container mx-auto px-6 py-16">
        {/* 히어로 섹션 */}
        <div className="text-center mb-20">
          <div className="inline-flex items-center space-x-2 bg-blue-100 text-blue-700 px-4 py-2 rounded-full text-sm font-medium mb-6">
            <Zap className="w-4 h-4" />
            <span>지능형 차량 매칭 시스템</span>
          </div>

          <h1 className="text-5xl md:text-6xl font-bold text-gray-900 mb-6 leading-tight">
            <span className="block mb-2">니 취향만 말해줘</span>
            <span className="bg-gradient-to-r from-blue-600 via-purple-600 to-emerald-600 bg-clip-text text-transparent">
              나머지는 내가 다 해줄게
            </span>
          </h1>

          <p className="text-xl text-gray-600 mb-8 max-w-3xl mx-auto leading-relaxed">
            {Math.round(dbStatus.totalVehicles / 1000)}만+ 실제 매물에서 자연스럽게 대화만 하면
            <br />
            <span className="text-blue-600 font-semibold">AI가 딱 맞는 차량을 찾아드려요</span>
          </p>

          {/* 핵심 가치 제안 */}
          <div className="grid grid-cols-1 md:grid-cols-3 gap-6 max-w-5xl mx-auto mb-12">
            <div className="bg-white/70 backdrop-blur-sm rounded-2xl p-6 border border-white/50 shadow-lg hover:shadow-xl transition-all duration-300">
              <div className="w-12 h-12 bg-blue-100 rounded-xl flex items-center justify-center mb-4 mx-auto">
                <Star className="w-6 h-6 text-blue-600" />
              </div>
              <h3 className="text-lg font-bold text-gray-900 mb-2">TOPSIS 분석</h3>
              <p className="text-gray-600 text-sm">다기준 의사결정 논문으로 최적 차량 선별</p>
            </div>

            <div className="bg-white/70 backdrop-blur-sm rounded-2xl p-6 border border-white/50 shadow-lg hover:shadow-xl transition-all duration-300">
              <div className="w-12 h-12 bg-emerald-100 rounded-xl flex items-center justify-center mb-4 mx-auto">
                <Shield className="w-6 h-6 text-emerald-600" />
              </div>
              <h3 className="text-lg font-bold text-gray-900 mb-2">Alibaba Re-ranking</h3>
              <p className="text-gray-600 text-sm">개인화 재순위 논문으로 사용자 맞춤 정렬</p>
            </div>

            <div className="bg-white/70 backdrop-blur-sm rounded-2xl p-6 border border-white/50 shadow-lg hover:shadow-xl transition-all duration-300">
              <div className="w-12 h-12 bg-purple-100 rounded-xl flex items-center justify-center mb-4 mx-auto">
                <TrendingUp className="w-6 h-6 text-purple-600" />
              </div>
              <h3 className="text-lg font-bold text-gray-900 mb-2">MACRec 협업</h3>
              <p className="text-gray-600 text-sm">멀티에이전트 협업 논문으로 종합 분석</p>
            </div>
          </div>

          {/* 신뢰 지표 - 강화된 디자인 */}
          <div className="bg-white rounded-xl shadow-lg border border-gray-100 p-6 mb-12 max-w-4xl mx-auto">
            <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
              <div className="text-center">
                <div className="flex items-center justify-center space-x-3 mb-2">
                  <div className="w-3 h-3 bg-green-500 rounded-full animate-pulse"></div>
                  <span className="text-2xl font-bold text-green-700">
                    {dbStatus.totalVehicles.toLocaleString()}+
                  </span>
                </div>
                <p className="text-gray-600 font-medium">실제 매물 데이터</p>
                <p className="text-xs text-gray-500">PostgreSQL 실시간 연동</p>
              </div>

              <div className="text-center">
                <div className="flex items-center justify-center space-x-3 mb-2">
                  <CheckCircle className="w-6 h-6 text-red-500" />
                  <span className="text-xl font-bold text-gray-700">0%</span>
                </div>
                <p className="text-gray-600 font-medium">Mock 데이터</p>
                <p className="text-xs text-gray-500">100% 실제 매물만 사용</p>
              </div>

              <div className="text-center">
                <div className="flex items-center justify-center space-x-3 mb-2">
                  <CheckCircle className="w-6 h-6 text-blue-500" />
                  <span className="text-xl font-bold text-gray-700">100%</span>
                </div>
                <p className="text-gray-600 font-medium">완전 무료</p>
                <p className="text-xs text-gray-500">숨은 비용 없음</p>
              </div>
            </div>

            <div className="mt-4 pt-4 border-t border-gray-100">
              <p className="text-center text-sm text-gray-600">
                <span className="inline-flex items-center space-x-1">
                  <span>🔍</span>
                  <span className="font-medium">Gemini 2.5 Flash</span>
                  <span>+</span>
                  <span className="font-medium">A2A Protocol</span>
                  <span>+</span>
                  <span className="font-medium">실시간 DB</span>
                </span>
              </p>
            </div>
          </div>
        </div>

        {/* 메인 검색 입력 */}
        <div className="max-w-4xl mx-auto mb-16">
          <div className="bg-white/80 backdrop-blur-lg rounded-3xl shadow-2xl border border-white/50 p-8">
            <div className="text-center mb-8">
              <h2 className="text-3xl font-bold text-gray-900 mb-3">
                어떤 차를 찾고 있어요?
              </h2>
              <p className="text-gray-600 text-lg">
                마치 친구랑 얘기하듯 편하게 말씀해 주세요
              </p>
            </div>

            <div className="relative">
              <div className="flex flex-col space-y-4">
                <div className="relative">
                  <Search className="absolute left-6 top-1/2 transform -translate-y-1/2 text-gray-400 w-6 h-6" />
                  <textarea
                    value={question}
                    onChange={(e) => setQuestion(e.target.value)}
                    onKeyPress={handleKeyPress}
                    placeholder='예: "회사 출퇴근용으로 쓰면서 주말에는 가족과 캠핑도 다니고 싶습니다. 연비가 좋으면서 안전성도 높은 차량으로 추천해 주세요"'
                    className="w-full text-lg pl-16 pr-6 py-6 border-2 border-gray-200 rounded-2xl focus:ring-2 focus:ring-blue-500 focus:border-blue-500 outline-none transition-all duration-200 bg-white/90 resize-none"
                    disabled={isLoading}
                    rows={3}
                  />
                </div>
                <button
                  onClick={handleSubmit}
                  disabled={isLoading || !question.trim()}
                  className="w-full px-8 py-5 bg-gradient-to-r from-blue-600 to-purple-600 text-white text-lg font-bold rounded-2xl hover:from-blue-700 hover:to-purple-700 hover:shadow-xl disabled:bg-gray-400 disabled:cursor-not-allowed transition-all duration-200 flex items-center space-x-2 justify-center"
                >
                  {isLoading ? (
                    <div className="w-5 h-5 border-2 border-white border-t-transparent rounded-full animate-spin"></div>
                  ) : (
                    <>
                      <Search className="w-5 h-5" />
                      <span>AI한테 물어보기</span>
                    </>
                  )}
                </button>
              </div>
            </div>

