## 📚 논문 1: MACRec (SIGIR 2024) 기반 크롤링 데이터 통합

### 🔍 MACRec의 Multi-Agent Framework를 외부 데이터 수집에 적용

```typescript
// lib/external-data/MACRecDataCollector.ts

interface ExternalDataAgent {
  id: string;
  specialty: string;
  dataSources: string[];
  reliability: number;
}

class ExternalDataMACRec {

  // MACRec의 Manager Agent → Data Collection Manager
  private managers = {
    vehicleInspection: new VehicleInspectionManager(),
    insuranceHistory: new InsuranceHistoryManager(),
    realPurchaseData: new RealPurchaseDataManager(),
    marketTrends: new MarketTrendManager()
  };

  // MACRec의 Agent Collaboration Protocol 적용
  async collectComprehensiveVehicleData(vehicleId: string): Promise<EnhancedVehicleData> {

    // Step 1: Manager가 데이터 수집 태스크 분해
    const dataCollectionTasks = [
      { type: 'inspection', priority: 'HIGH', timeout: 30000 },
      { type: 'insurance', priority: 'HIGH', timeout: 15000 },
      { type: 'purchase_history', priority: 'MEDIUM', timeout: 20000 },
      { type: 'market_comparison', priority: 'LOW', timeout: 10000 }
    ];

    // Step 2: 각 Agent에게 병렬 할당 (MACRec 프로토콜)
    const collectionPromises = dataCollectionTasks.map(task =>
      this.executeDataCollection(task, vehicleId)
    );

    // Step 3: 병렬 실행 및 결과 수집
    const results = await Promise.allSettled(collectionPromises);

    // Step 4: MACRec Reflector Agent가 데이터 품질 검증
    const validatedData = await this.validateDataQuality(results);

    return validatedData;
  }

  // 각 데이터 소스별 전문 Agent
  private async executeDataCollection(task: DataTask, vehicleId: string) {
    switch(task.type) {
      case 'inspection':
        return await this.collectInspectionData(vehicleId);
      case 'insurance':
        return await this.collectInsuranceData(vehicleId);
      case 'purchase_history':
        return await this.collectPurchaseHistory(vehicleId);
      case 'market_comparison':
        return await this.collectMarketData(vehicleId);
    }
  }
}
```

### 🚗 성능점검표 데이터 수집 Agent

```typescript
// MACRec의 Searcher Agent → 성능점검표 전문 Agent
class VehicleInspectionAgent {

  async collectInspectionData(vehicleId: string): Promise<InspectionData> {

    // 크롤링 소스별 병렬 수집
    const sources = await Promise.allSettled([
      this.crawlKCarInspection(vehicleId),      // K-Car 성능점검
      this.crawlSKEncarInspection(vehicleId),   // SK엔카 검수 데이터
      this.crawlHyundaiInspection(vehicleId),   // 현대 블루핸즈 점검
      this.crawlKiaInspection(vehicleId)        // 기아 서비스 이력
    ]);

    // MACRec 방식의 결과 통합
    return this.aggregateInspectionResults(sources);
  }

  private async aggregateInspectionResults(sources: any[]): Promise<InspectionData> {
    const validSources = sources
      .filter(s => s.status === 'fulfilled')
      .map(s => s.value);

    // 다중 소스 검증으로 신뢰성 향상
    return {
      engine: this.consensusScore(validSources.map(s => s.engine_condition)),
      transmission: this.consensusScore(validSources.map(s => s.transmission)),
      suspension: this.consensusScore(validSources.map(s => s.suspension)),
      brakes: this.consensusScore(validSources.map(s => s.brakes)),
      electrical: this.consensusScore(validSources.map(s => s.electrical)),
      body: this.consensusScore(validSources.map(s => s.body_condition)),

      // 신뢰성 지표
      sourceCount: validSources.length,
      reliability: validSources.length >= 2 ? 'HIGH' : 'MEDIUM',
      lastUpdated: new Date(),

      // 원본 데이터 보존 (논문 기반 추적성)
      rawSources: validSources
    };
  }

  // 다중 소스 합의 알고리즘 (MACRec의 협업 방식)
  private consensusScore(scores: number[]): {
    value: number;
    confidence: number;
    variance: number;
  } {
    const cleanScores = scores.filter(s => s !== null && s !== undefined);

    if (cleanScores.length === 0) return { value: 0, confidence: 0, variance: 1 };

    const avg = cleanScores.reduce((a, b) => a + b, 0) / cleanScores.length;
    const variance = cleanScores.reduce((sum, score) =>
      sum + Math.pow(score - avg, 2), 0) / cleanScores.length;

    const confidence = Math.min(cleanScores.length / 3, 1) * (1 - Math.sqrt(variance) / 10);

    return {
      value: Math.round(avg * 10) / 10,
      confidence: Math.round(confidence * 100) / 100,
      variance: Math.round(variance * 100) / 100
    };
  }
}
```

### 🛡️ 보험이력 데이터 수집 Agent

```typescript
// 보험이력 전문 수집 Agent
class InsuranceHistoryAgent {

  async collectInsuranceData(vehicleId: string): Promise<InsuranceData> {

    // 보험사별 이력 병렬 크롤링
    const insurancePromises = [
      this.crawlSamsungInsurance(vehicleId),
      this.crawlHyundaiInsurance(vehicleId),
      this.crawlDBInsurance(vehicleId),
      this.crawlMeritzInsurance(vehicleId),
      this.crawlLIGInsurance(vehicleId)
    ];

    const results = await Promise.allSettled(insurancePromises);

    return this.consolidateInsuranceHistory(results);
  }

  private async consolidateInsuranceHistory(results: any[]): Promise<InsuranceData> {
    const validResults = results
      .filter(r => r.status === 'fulfilled')
      .map(r => r.value)
      .filter(v => v !== null);

    // 사고이력 통합 (중복 제거)
    const allAccidents = validResults.flatMap(r => r.accidents || []);
    const uniqueAccidents = this.deduplicateAccidents(allAccidents);

    // 정비이력 통합
    const allMaintenance = validResults.flatMap(r => r.maintenance || []);
    const consolidatedMaintenance = this.consolidateMaintenance(allMaintenance);

    return {
      totalClaims: uniqueAccidents.length,
      accidentHistory: uniqueAccidents.map(acc => ({
        date: acc.date,
        damageAmount: acc.damageAmount,
        severity: this.calculateSeverity(acc.damageAmount),
        type: acc.type, // 접촉사고, 단독사고, 침수 등
        repairCost: acc.repairCost,
        reliability: acc.sourceCount >= 2 ? 'VERIFIED' : 'SINGLE_SOURCE'
      })),

      maintenanceHistory: consolidatedMaintenance,

      riskScore: this.calculateInsuranceRiskScore(uniqueAccidents),

      // 보험료 예측 (과거 데이터 기반)
      predictedAnnualPremium: this.predictInsurancePremium(uniqueAccidents, consolidatedMaintenance),

      dataQuality: {
        sourcesCovered: validResults.length,
        completeness: validResults.length >= 3 ? 'HIGH' : 'MEDIUM',
        lastUpdated: new Date()
      }
    };
  }

  private calculateSeverity(damageAmount: number): 'MINOR' | 'MODERATE' | 'MAJOR' | 'TOTAL' {
    if (damageAmount < 500000) return 'MINOR';
    if (damageAmount < 2000000) return 'MODERATE';
    if (damageAmount < 10000000) return 'MAJOR';
    return 'TOTAL';
  }
}
```

