// 사용자 피드백에 따른 실시간 외부 데이터 재가중치
class RealTimeReRanking {

  async handleUserFeedback(
    feedback: UserFeedback,
    currentRecommendations: EnhancedVehicle[]
  ): Promise<EnhancedVehicle[]> {

    // 피드백 분석으로 외부 데이터 중요도 조정
    const adjustedWeights = this.adjustExternalDataWeights(feedback);

    // 실시간 재점수 계산 (외부 데이터 반영)
    const reScored = await Promise.all(
      currentRecommendations.map(async vehicle => {

        // 외부 데이터 재가중치 적용
        const newScore = await this.recalculateWithAdjustedWeights(
          vehicle,
          adjustedWeights
        );

        return { ...vehicle, personalizedScore: newScore };
      })
    );

    // Alibaba 방식 재정렬
    return reScored.sort((a, b) =>
      b.personalizedScore.overallScore - a.personalizedScore.overallScore
    );
  }

  private adjustExternalDataWeights(feedback: UserFeedback): ExternalDataWeights {

    const adjustments: ExternalDataWeights = {
      inspection_importance: 0.25,
      insurance_importance: 0.20,
      market_importance: 0.15,
      purchase_history_importance: 0.10
    };

    // 피드백별 가중치 조정
    switch(feedback.type) {
      case 'SAFETY_CONCERN':
        adjustments.inspection_importance += 0.15;
        adjustments.insurance_importance += 0.10;
        break;

      case 'PRICE_SENSITIVITY':
        adjustments.market_importance += 0.20;
        adjustments.purchase_history_importance += 0.15;
        break;

      case 'RELIABILITY_FOCUS':
        adjustments.inspection_importance += 0.20;
        adjustments.insurance_importance += 0.15;
        break;
    }

    return adjustments;
  }
}
```

