## 📈 논문 3: AHP-TOPSIS를 성능점검표/보험이력 평가에 적용

### 🎯 외부 데이터 기반 정밀 평가 시스템

```typescript
// lib/evaluation/ExternalDataTOPSIS.ts

class ExternalDataEnhancedTOPSIS {

  // AHP로 외부 데이터 기준별 가중치 결정
  private readonly EXTERNAL_DATA_CRITERIA = {
    // 성능점검표 기준들
    engine_condition: { weight: 0.20, type: 'benefit' },
    transmission_condition: { weight: 0.15, type: 'benefit' },
    brake_condition: { weight: 0.15, type: 'benefit' },
    suspension_condition: { weight: 0.10, type: 'benefit' },
    electrical_condition: { weight: 0.10, type: 'benefit' },

    // 보험이력 기준들
    accident_history: { weight: 0.15, type: 'cost' },
    claim_frequency: { weight: 0.10, type: 'cost' },
    damage_severity: { weight: 0.05, type: 'cost' }
  };

  async evaluateVehicleWithExternalData(
    vehicle: Vehicle,
    externalData: ExternalDataSet,
    peerGroup: Vehicle[]
  ): Promise<EnhancedTOPSISResult> {

    // Step 1: 외부 데이터를 TOPSIS 매트릭스로 변환
    const decisionMatrix = this.buildExternalDataMatrix(vehicle, externalData, peerGroup);

    // Step 2: 정규화 (TOPSIS 표준 방식)
    const normalizedMatrix = this.normalizeMatrix(decisionMatrix);

    // Step 3: 가중치 적용
    const weightedMatrix = this.applyWeights(normalizedMatrix, this.EXTERNAL_DATA_CRITERIA);

    // Step 4: 이상적 해와 부정적 이상적 해 계산
    const idealSolutions = this.calculateIdealSolutions(weightedMatrix);

    // Step 5: 각 대안의 거리 계산
    const distances = this.calculateDistances(weightedMatrix, idealSolutions);

    // Step 6: TOPSIS 점수 계산
    const topsisScore = this.calculateTOPSISScore(distances);

    // Step 7: 세부 분석
    const detailedAnalysis = this.generateDetailedAnalysis(
      vehicle,
      externalData,
      topsisScore,
      this.EXTERNAL_DATA_CRITERIA
    );

    return {
      overallScore: topsisScore,
      ...detailedAnalysis,

      // 외부 데이터 신뢰성
      dataReliability: this.assessDataReliability(externalData),

      // 숨겨진 리스크 탐지
      hiddenRisks: this.detectHiddenRisks(externalData),

      // 구매 추천도
      purchaseRecommendation: this.generatePurchaseRecommendation(topsisScore, externalData)
    };
  }

  private generateDetailedAnalysis(
    vehicle: Vehicle,
    externalData: ExternalDataSet,
    topsisScore: number,
    criteria: any
  ): DetailedAnalysis {

    return {
      // 성능점검표 기반 분석
      mechanicalCondition: {
        engineScore: this.evaluateEngineCondition(externalData.inspection),
        transmissionScore: this.evaluateTransmissionCondition(externalData.inspection),
        brakeScore: this.evaluateBrakeCondition(externalData.inspection),
        suspensionScore: this.evaluateSuspensionCondition(externalData.inspection),
        electricalScore: this.evaluateElectricalCondition(externalData.inspection),

        overallMechanicalScore: this.calculateOverallMechanical(externalData.inspection),
        predictedMaintenanceCost: this.predictMaintenanceCost(externalData.inspection, vehicle.year),

        strengths: this.identifyMechanicalStrengths(externalData.inspection),
        weaknesses: this.identifyMechanicalWeaknesses(externalData.inspection)
      },

      // 보험이력 기반 분석
      riskProfile: {
        accidentRiskScore: this.calculateAccidentRisk(externalData.insurance),
        claimFrequencyScore: this.calculateClaimFrequency(externalData.insurance),
        damageSeverityScore: this.calculateDamageSeverity(externalData.insurance),

        futureInsurancePremium: this.predictInsurancePremium(externalData.insurance, vehicle),
        resaleValueImpact: this.calculateResaleImpact(externalData.insurance),

        riskFactors: this.identifyRiskFactors(externalData.insurance),
        safeguards: this.identifySafeguards(externalData.insurance)
      },

      // 종합 평가
      comprehensiveAssessment: {
        buyRecommendation: this.generateBuyRecommendation(topsisScore, externalData),
        priceNegotiationPoints: this.identifyNegotiationPoints(externalData),
        maintenancePlan: this.generateMaintenancePlan(externalData.inspection),
        insuranceStrategy: this.generateInsuranceStrategy(externalData.insurance),

        competitorComparison: this.compareWithPeers(vehicle, externalData, peerGroup),
        valueProposition: this.generateValueProposition(topsisScore, externalData)
      }
    };
  }

  // 숨겨진 리스크 탐지 시스템
  private detectHiddenRisks(externalData: ExternalDataSet): HiddenRisk[] {
    const risks: HiddenRisk[] = [];

    // 성능점검표에서 패턴 분석
    const inspectionPatterns = this.analyzeInspectionPatterns(externalData.inspection);
    if (inspectionPatterns.suspiciousPatterns.length > 0) {
      risks.push({
        type: 'INSPECTION_INCONSISTENCY',
        severity: 'MEDIUM',
        description: '성능점검표에서 일관성 없는 패턴 발견',
        details: inspectionPatterns.suspiciousPatterns,
        likelihood: 0.7
      });
    }

    // 보험이력에서 숨겨진 사고 패턴
    const insurancePatterns = this.analyzeInsurancePatterns(externalData.insurance);
    if (insurancePatterns.hasFrequentSmallClaims) {
      risks.push({
        type: 'FREQUENT_MINOR_DAMAGE',
        severity: 'HIGH',
        description: '빈번한 소액 사고 이력으로 인한 잠재적 구조적 손상',
        details: insurancePatterns.claimPattern,
        likelihood: 0.8
      });
    }

    // 시장 데이터와 불일치
    const marketInconsistencies = this.detectMarketInconsistencies(
      externalData.market,
      externalData.purchaseHistory
    );
    if (marketInconsistencies.length > 0) {
      risks.push({
        type: 'MARKET_PRICE_ANOMALY',
        severity: 'MEDIUM',
        description: '시장가 대비 비정상적 가격 책정',
        details: marketInconsistencies,
        likelihood: 0.6
      });
    }

    return risks;
  }
}
```

