#### **Day 1-2: JSON 파싱 & WebSocket 안정화**
```typescript
// 1. Gemini API 응답 파싱 개선
const robustJSONParser = (response: string) => {
  const cleanResponse = response
    .replace(/```json\n/g, '')
    .replace(/```/g, '')
    .replace(/`/g, '')
    .trim();

  try {
    return JSON.parse(cleanResponse);
  } catch (error) {
    // 정규식으로 JSON 부분만 추출
    const jsonMatch = cleanResponse.match(/\{[\s\S]*\}/);
    if (jsonMatch) {
      return JSON.parse(jsonMatch[0]);
    }
    throw new Error('JSON parsing failed');
  }
};

// 2. WebSocket 스트리밍 안정화
class SafeStreamController {
  private isClosed = false;

  enqueue(data: any) {
    if (!this.isClosed) {
      try {
        this.controller.enqueue(`data: ${JSON.stringify(data)}\n\n`);
      } catch (error) {
        this.isClosed = true;
        console.log('Stream closed safely:', error);
      }
    }
  }
}
```

