class SafeTCOCalculator {
  static calculateTCO(vehicle: any, drivingKmPerYear: number = 15000): TCOBreakdown {
    // 안전한 기본값 처리
    const safeVehicle = {
      price: Math.max(Number(vehicle?.price) || 1500, 1000),
      modelyear: Math.max(Number(vehicle?.modelyear) || 2015, 2010),
      distance: Math.max(Number(vehicle?.distance) || 50000, 0),
      manufacturer: vehicle?.manufacturer || 'Unknown'
    };

    // NaN 방지 계산 로직
    const currentYear = new Date().getFullYear();
    const carAge = Math.max(currentYear - safeVehicle.modelyear, 0);
    const depreciationRate = Math.min(carAge * 0.12, 0.6); // 최대 60% 감가상각

    const depreciationCost = safeVehicle.price * depreciationRate;
    const maintenanceCost = Math.max(safeVehicle.distance * 0.015, 80000); // 최소 8만원
    const fuelCost = drivingKmPerYear * 150; // km당 150원
    const insuranceCost = Math.max(safeVehicle.price * 0.05, 50000); // 최소 5만원

    const totalTCO = depreciationCost + maintenanceCost + fuelCost + insuranceCost;

    return {
      initialCost: safeVehicle.price * 10000,
      depreciationCost: Math.round(depreciationCost),
      maintenanceCost: Math.round(maintenanceCost),
      fuelCost: Math.round(fuelCost),
      insuranceCost: Math.round(insuranceCost),
      totalTCO: Math.round(totalTCO),
      monthlyAverage: Math.round(totalTCO / 60), // 5년 기준
      costPerKm: Math.round(totalTCO / (drivingKmPerYear * 5))
    };
  }
}
```

