### **Phase 2: 논문 기반 알고리즘 구현 (2주)**

#### **2.1 MACRec 프로토콜**
```typescript
// /lib/macrec/macrec-protocol.ts
export class MACRecProtocol {
  async executeCollaboration(userMessage: string) {
    // 1. Manager: 태스크 분해
    const tasks = await this.manager.decomposeTask(userMessage);

    // 2. 에이전트 할당
    const assignments = this.assignAgents(tasks);

    // 3. 병렬 실행
    const results = await Promise.all(
      assignments.map(a => a.agent.execute(a.task))
    );

    // 4. 결과 통합
    return await this.manager.aggregateResults(results);
  }
}
```

#### **2.2 Alibaba Re-ranking**
```typescript
// /lib/alibaba/personalized-reranking.ts
export class PersonalizedReranking {
  calculatePersonalizationScore(vehicle: Vehicle, userProfile: UserProfile) {
    const features = this.extractFeatures(vehicle, userProfile);
    const weights = this.getFeatureWeights(userProfile);

    return this.weightedSum(features, weights);
  }

  rerank(vehicles: Vehicle[], userProfile: UserProfile) {
    return vehicles
      .map(v => ({ ...v, personalizedScore: this.calculatePersonalizationScore(v, userProfile) }))
      .sort((a, b) => b.personalizedScore - a.personalizedScore);
  }
}
```

#### **2.3 Enhanced TOPSIS**
```typescript
// /lib/topsis/enhanced-topsis.ts
export class EnhancedTOPSIS {
  async calculateScore(vehicle: Vehicle, allVehicles: Vehicle[]) {
    // 1. 동질집단 검색
    const peerGroup = this.findPeerGroup(vehicle, allVehicles);

    // 2. 기준 정규화
    const normalizedMatrix = this.normalizeMatrix(peerGroup);

    // 3. TOPSIS 점수 계산
    return this.calculateTOPSISScore(vehicle, normalizedMatrix);
  }
}
```

