// /api/chat/ws/route.ts - 개선
export async function GET(request: NextRequest) {
  const stream = new ReadableStream({
    start(controller) {
      (async () => {
        // 1. 니즈 추출
        const userNeeds = await extractUserNeeds(question);

        // 2. 리뷰 분석
        const reviewInsights = await analyzeReviewsFromRDS(userNeeds);

        // 3. 멀티 소스 검색
        const vehicles = await searchMultiSourceVehicles(
          reviewInsights.recommendedModels, userNeeds
        );

        // 4. MACRec 프로토콜 실행
        const macrecProtocol = new MACRecProtocol();
        for await (const event of macrecProtocol.executeWithStreaming(question, vehicles)) {
          controller.enqueue(`data: ${JSON.stringify(event)}\n\n`);
        }
      })();
    }
  });
}
