### 4논문 통합 리뷰 활용 시스템

```typescript
// lib/review/ReviewEnhancedRecommendation.ts

interface ReviewEnhancedSystem {
  // 1. MACRec + 리뷰 데이터
  macrecWithReviews: {
    // Needs Analyst가 리뷰 기반 사용자 프로필 생성
    extractUserPreferencesFromReviews(userQuery: string): UserProfile;

    // Data Analyst가 리뷰 점수 높은 차량 우선 검색
    searchVehiclesWithReviewScore(criteria: SearchCriteria): Vehicle[];

    // Manager가 리뷰 신뢰도 고려한 추천 생성
    generateReviewAwareRecommendations(vehicles: Vehicle[]): Recommendation[];
  };

  // 2. Personalized Re-ranking + 리뷰 감정
  rerankingWithSentiment: {
    // 리뷰 감정 점수를 Re-ranking 요소로 추가
    calculateSentimentScore(vehicle: Vehicle): number;

    // 사용자 선호도 + 리뷰 만족도 종합 점수
    hybridRankingScore(vehicle: Vehicle, userProfile: UserProfile): number;

    // 부정 리뷰 높은 차량 자동 제외
    filterLowSatisfactionVehicles(vehicles: Vehicle[]): Vehicle[];
  };

  // 3. TOPSIS + 리뷰 신뢰도
  topsisWithReviews: {
    // TOPSIS 평가에 실제 소유자 만족도 반영
    enhancedTOPSISScore(vehicle: Vehicle, reviews: Review[]): number;

    // 리뷰 기반 실제 TCO 예측 (예상 vs 실제)
    reviewBasedTCOPrediction(vehicle: Vehicle): TCOPrediction;

    // 소유자 경험 기반 리스크 조정
    adjustRiskWithOwnerExperience(riskScore: number, reviews: Review[]): number;
  };

  // 4. 리뷰 감정 분석 (새로 추가)
  reviewSentimentAnalysis: {
    // 6,839개 리뷰 감정 점수 계산
    analyzeSentimentBatch(reviews: Review[]): SentimentResult[];

    // 브랜드별 신뢰도 점수
    calculateBrandTrustScore(manufacturer: string): TrustScore;

    // 모델별 실제 소유자 만족도
    calculateModelSatisfaction(model: string): SatisfactionScore;

    // 구매 결정 도움 인사이트
    generateOwnerInsights(vehicle: Vehicle): OwnerInsight[];
  };
}
