## 🧠 세션 메모리 시스템

### GPT/Gemini 수준의 대화 기억

```typescript
// lib/memory/ConversationMemorySystem.ts

interface ConversationMemorySystem {
  // 전체 대화 히스토리 저장
  sessionHistory: Map<string, ConversationSession>;

  // 사용자 프로필 지속적 업데이트
  userProfiles: Map<string, EvolvingUserProfile>;

  // 컨텍스트 유지 관리
  contextManager: ContextManager;
}

class ConversationSession {
  sessionId: string;
  userId: string;
  messages: Message[];
  userProfile: EvolvingUserProfile;
  preferences: UserPreferences;
  lastActivity: Date;

  // 핵심: 대화 컨텍스트 누적
  addMessage(message: Message) {
    this.messages.push(message);

    // 사용자 메시지면 프로필 업데이트
    if (message.agent === 'user') {
      this.updateProfileFromMessage(message.content);
    }

    // 세션 저장 (Redis + DB)
    this.saveToMemory();
  }

  // 대화에서 선호도 지속적 학습
  updateProfileFromMessage(content: string) {
    const extractedPrefs = extractPreferencesFromText(content);

    // 기존 프로필과 병합
    this.userProfile = mergePreferences(this.userProfile, extractedPrefs);
  }

  // 이전 대화 컨텍스트 활용
  getRelevantContext(currentMessage: string): ContextualInfo {
    return {
      previousQuestions: this.getPreviousQuestions(),
      establishedPreferences: this.userProfile,
      pastRecommendations: this.getPastRecommendations(),
      feedbackHistory: this.getFeedbackHistory()
    };
  }
}

// 세션 메모리 사용 예시
async function handleUserMessage(sessionId: string, message: string) {

  // 1. 세션 복원 (Redis에서 빠르게)
  const session = await memorySystem.getSession(sessionId);

  // 2. 컨텍스트 확인
  const context = session.getRelevantContext(message);

  // 3. 컨텍스트 기반 응답
  const response = await generateContextualResponse(message, context);

  예시:
  사용자: "SUV 추천해줘" (첫 대화)
  AI: "어떤 용도로 사용하실 계획인가요?"

  사용자: "가족용이야"
