                  </Badge>
                  <div className="text-xs font-semibold text-blue-700">
                    {result.smartOrchestrator.sequential_analysis?.thinking_steps?.length || result.agents.length * 3}단계 심층 분석 수행
                  </div>
                </div>
              </div>
            )}
            <div className="flex justify-center items-center space-x-6">
              <div className="text-center">
                <div className={`text-3xl font-bold text-white px-4 py-2 rounded-lg shadow-lg ${getScoreGradient(result.consensus?.confidence_score || 85)}`}>
                  {result.consensus?.confidence_score || 85}%
                </div>
                <div className="text-sm text-slate-600 mt-2">종합 신뢰도</div>
              </div>
              <div className="text-center">
                <div className="text-3xl font-bold text-white px-4 py-2 rounded-lg shadow-lg bg-gradient-to-r from-blue-500 to-indigo-500">
                  {result.top_vehicles?.length || 0}
                </div>
                <div className="text-sm text-slate-600 mt-2">추천 차량</div>
              </div>
              <div className="text-center">
                <div className="text-3xl font-bold text-white px-4 py-2 rounded-lg shadow-lg bg-gradient-to-r from-green-500 to-emerald-500">
                  {result.consensus?.agreed_points?.length || 0}
                </div>
                <div className="text-sm text-slate-600 mt-2">합의 포인트</div>
              </div>
            </div>
          </div>
        </div>

        {/* TOP 추천 차량들 */}
        <Card className="bg-white/80 backdrop-blur-md shadow-xl">
          <CardHeader>
            <CardTitle className="flex items-center gap-2 text-slate-800">
              <Trophy className="w-6 h-6 text-yellow-500" />
              🏆 당신을 위한 베스트 추천
            </CardTitle>
            <p className="text-slate-600">전문가 3명이 합의한 가장 좋은 선택입니다. 믿고 골라도 돼요!</p>
          </CardHeader>
          <CardContent className="p-6">
            <div className="grid md:grid-cols-3 gap-6">
              {(result.top_vehicles || []).slice(0, 3).map((vehicle, index) => (
                <Card
                  key={vehicle.vehicleid}
                  className={`cursor-pointer transition-all duration-300 hover:scale-105 ${
                    selectedVehicle === vehicle.vehicleid
                      ? 'ring-4 ring-green-400 bg-green-50'
                      : 'hover:shadow-lg'
                  }`}
                  onClick={() => setSelectedVehicle(
                    selectedVehicle === vehicle.vehicleid ? null : vehicle.vehicleid
                  )}
                >
                  <CardContent className="p-6">
                    {/* 순위 배지 */}
                    <div className="flex justify-between items-start mb-4">
                      <Badge
                        className={`text-white font-bold border-0 px-3 py-1 shadow-lg ${
                          index === 0 ? 'bg-gradient-to-r from-yellow-500 to-amber-500' :
                          index === 1 ? 'bg-gradient-to-r from-blue-500 to-indigo-500' :
                          'bg-gradient-to-r from-green-500 to-emerald-500'
                        }`}
                      >
                        #{index + 1}
                      </Badge>
                      <div className="text-right">
                        <div className="text-2xl font-bold text-white px-3 py-1 rounded-lg shadow-lg bg-gradient-to-r from-green-500 to-emerald-500">
                          {vehicle.final_score}/3
                        </div>
                        <div className="text-xs text-slate-600 mt-1">전문가 점수</div>
                      </div>
                    </div>

                    {/* 차량 정보 */}
                    <div className="text-center space-y-3">
                      <div className="w-full h-32 bg-gradient-to-br from-gray-100 to-gray-200 rounded-xl flex items-center justify-center">
                        <span className="text-gray-500 text-sm text-center">
                          {vehicle.manufacturer}<br />
                          {vehicle.model}
                        </span>
                      </div>
                      <h3 className="text-xl font-bold text-slate-800">
                        {vehicle.manufacturer} {vehicle.model} {vehicle.trim ? `(${vehicle.trim})` : ''}
                      </h3>
                      <div className="text-2xl font-bold text-blue-600">
                        {formatPrice(vehicle.price)}
                      </div>

                      {/* 상세 스펙 정보 */}
                      <div className="grid grid-cols-2 gap-2 text-xs bg-slate-50 rounded-lg p-3">
                        <div className="flex flex-col">
                          <span className="text-slate-500">연식</span>
                          <span className="font-semibold">{vehicle.modelyear || 'N/A'}년</span>
                        </div>
                        <div className="flex flex-col">
                          <span className="text-slate-500">주행거리</span>
                          <span className="font-semibold">
                            {vehicle.distance ? `${Math.round(vehicle.distance/10000)}만km` : 'N/A'}
                          </span>
                        </div>
                        <div className="flex flex-col">
                          <span className="text-slate-500">연료</span>
                          <span className="font-semibold">{vehicle.fueltype || 'N/A'}</span>
                        </div>
                        <div className="flex flex-col">
                          <span className="text-slate-500">차종</span>
                          <span className="font-semibold">{vehicle.cartype || 'N/A'}</span>
                        </div>
                      </div>

                      {/* 추가 상세 정보 */}
                      <div className="text-xs space-y-1">
                        <div className="flex justify-between">
                          <span className="text-slate-500">변속기:</span>
                          <span className="font-medium">{vehicle.transmission || 'N/A'}</span>
                        </div>
                        <div className="flex justify-between">
                          <span className="text-slate-500">색상:</span>
                          <span className="font-medium">{vehicle.colorname || 'N/A'}</span>
                        </div>
                        <div className="flex justify-between">
                          <span className="text-slate-500">지역:</span>
                          <span className="font-medium">{vehicle.location || 'N/A'}</span>
                        </div>
                      </div>

                      {/* 전문가 투표 */}
                      <div className="flex justify-center space-x-1">
                        {vehicle.agent_votes.map((emoji, idx) => (
                          <span key={idx} className="text-2xl">{emoji}</span>
                        ))}
                      </div>

                      <p className="text-sm text-slate-600 line-clamp-2">
                        {vehicle.reasoning}
                      </p>

                      {selectedVehicle === vehicle.vehicleid && (
                        <div className="mt-4 space-y-3">
                          {/* 전문가별 상세 분석 */}
                          {vehicle.expert_analyses && vehicle.expert_analyses.length > 0 && (
                            <div className="bg-white rounded-lg p-4 border-2 border-green-200">
                              <h4 className="font-bold text-slate-800 mb-3 flex items-center">
                                <Users className="w-4 h-4 mr-2" />
                                전문가별 분석
                              </h4>
                              <div className="space-y-3">
                                {vehicle.expert_analyses.map((analysis, idx) => (
                                  <div key={idx} className="border-l-4 border-gray-200 pl-3">
                                    <div className="flex items-center mb-2">
                                      <span className="text-lg mr-2">{analysis.agent_emoji}</span>
                                      <div>
                                        <span className="font-semibold text-sm">{analysis.agent_name}</span>
                                        <div className="text-xs text-slate-500">{analysis.agent_role}</div>
                                      </div>
                                      <Badge className="ml-auto text-xs px-2 py-1 bg-green-100 text-green-800 border-0">
                                        신뢰도 {analysis.confidence}%
                                      </Badge>
                                    </div>
                                    <p className="text-sm text-slate-700 mb-2">{analysis.reasoning}</p>
                                    <div className="grid grid-cols-2 gap-2 text-xs">
                                      <div>
                                        <span className="font-medium text-green-600">👍 장점:</span>
                                        <ul className="mt-1 space-y-1">
                                          {analysis.pros.map((pro, proIdx) => (
                                            <li key={proIdx} className="text-slate-600">• {pro}</li>
                                          ))}
                                        </ul>
                                      </div>
                                      <div>
                                        <span className="font-medium text-orange-600">👎 단점:</span>
                                        <ul className="mt-1 space-y-1">
                                          {analysis.cons.map((con, conIdx) => (
                                            <li key={conIdx} className="text-slate-600">• {con}</li>
                                          ))}
                                        </ul>
                                      </div>
                                    </div>
                                  </div>
                                ))}
                              </div>
                            </div>
                          )}

                          <Button
                            size="sm"
                            className="w-full bg-gradient-to-r from-blue-500 to-indigo-500 text-white font-bold py-2 shadow-lg hover:scale-105 transition-all duration-300 border-0"
                            onClick={(e) => {
                              e.stopPropagation();
                              router.push(`/vehicle/${vehicle.vehicleid}`);
                            }}
                          >
                            <ExternalLink className="w-4 h-4 mr-2" />
                            상세 정보 보기
                          </Button>
                        </div>
                      )}
                    </div>
                  </CardContent>
                </Card>
              ))}
            </div>
          </CardContent>
        </Card>

        <div className="grid lg:grid-cols-2 gap-6">
          {/* 전문가 의견 요약 */}
          <Card className="bg-white/80 backdrop-blur-md shadow-xl">
            <CardHeader>
              <CardTitle className="flex items-center gap-2 text-slate-800">
                <Users className="w-5 h-5" />
                🧑‍💼 전문가 의견 요약
              </CardTitle>
            </CardHeader>
            <CardContent className="p-6 space-y-4">
              {(result.agents || []).map((agent) => (
                <div key={agent.agent_id} className="border-l-4 border-gray-200 pl-4">
                  <div className="flex items-center mb-2">
                    <span className="text-2xl mr-2">{agent.agent_emoji}</span>
                    <span className="font-semibold text-slate-800">{agent.agent_name}</span>
                    <Badge className={`ml-2 ${getAgentColor(agent.agent_id)}`}>
                      {agent.analysis.confidence_level}% 신뢰도
                    </Badge>
                  </div>
                  <p className="text-sm text-slate-600 mb-2">
                    {agent.analysis.summary}
                  </p>
                  <div className="text-xs text-slate-500">
                    <span className="font-medium">핵심:</span> {agent.analysis.key_findings.slice(0, 2).join(', ')}
                  </div>
                </div>
              ))}
            </CardContent>
          </Card>

          {/* 합의/불일치 사항 */}
          <Card className="bg-white/80 backdrop-blur-md shadow-xl">
            <CardHeader>
              <CardTitle className="flex items-center gap-2 text-slate-800">
                <Target className="w-5 h-5" />
                🎯 전문가 합의 분석
              </CardTitle>
            </CardHeader>
            <CardContent className="p-6 space-y-4">
              {/* 합의 사항 */}
              <div>
                <div className="flex items-center mb-3">
                  <ThumbsUp className="w-5 h-5 text-green-600 mr-2" />
                  <h4 className="font-semibold text-slate-800">✅ 공통 의견</h4>
                </div>
                <div className="space-y-2">
                  {(result.consensus?.agreed_points || []).map((point, index) => (
                    <div key={index} className="flex items-start space-x-2">
                      <CheckCircle className="w-4 h-4 text-green-600 mt-0.5 flex-shrink-0" />
                      <span className="text-sm text-slate-600">{point}</span>
                    </div>
                  ))}
                </div>
              </div>

              {/* 불일치 사항 */}
              {(result.consensus?.disagreed_points?.length || 0) > 0 && (
                <div>
                  <div className="flex items-center mb-3">
                    <AlertTriangle className="w-5 h-5 text-yellow-600 mr-2" />
                    <h4 className="font-semibold text-slate-800">⚡ 의견 차이</h4>
                  </div>
                  <div className="space-y-2">
                    {(result.consensus?.disagreed_points || []).map((point, index) => (
                      <div key={index} className="flex items-start space-x-2">
                        <AlertTriangle className="w-4 h-4 text-yellow-600 mt-0.5 flex-shrink-0" />
                        <span className="text-sm text-slate-600">{point}</span>
                      </div>
                    ))}
                  </div>
                </div>
              )}
            </CardContent>
          </Card>
        </div>

        {/* 개인 인사이트 & 액션 */}
        <div className="grid lg:grid-cols-3 gap-6">
          {/* 개인 페르소나 */}
          <Card className="bg-white/80 backdrop-blur-md shadow-xl">
            <CardHeader>
              <CardTitle className="flex items-center gap-2 text-slate-800">
                <Award className="w-5 h-5" />
                👤 당신의 프로필
              </CardTitle>
            </CardHeader>
            <CardContent className="p-6">
              <div className="text-center space-y-3">
                <div className="w-16 h-16 bg-blue-100 rounded-full mx-auto flex items-center justify-center">
                  <Users className="w-8 h-8 text-blue-600" />
                </div>
                <p className="text-sm text-slate-600">
                  {result.persona_summary || '개인 맞춤형 차량 구매자 프로필'}
                </p>
              </div>
            </CardContent>
          </Card>

          {/* 최종 추천 */}
          <Card className="bg-white/80 backdrop-blur-md shadow-xl">
            <CardHeader>
              <CardTitle className="flex items-center gap-2 text-slate-800">
                <Sparkles className="w-5 h-5" />
                💡 최종 조언
              </CardTitle>
            </CardHeader>
            <CardContent className="p-6">
              <div className="space-y-2">
                {(result.consensus?.final_recommendations || []).map((rec, index) => (
                  <div key={index} className="flex items-start space-x-2">
                    <ArrowRight className="w-4 h-4 text-blue-600 mt-0.5 flex-shrink-0" />
                    <span className="text-sm text-slate-600">{rec}</span>
                  </div>
                ))}
              </div>
            </CardContent>
          </Card>

          {/* 액션 버튼들 */}
          <Card className="bg-white/80 backdrop-blur-md shadow-xl">
            <CardHeader>
              <CardTitle className="flex items-center gap-2 text-slate-800">
                <TrendingUp className="w-5 h-5" />
                🚀 다음 단계
              </CardTitle>
            </CardHeader>
            <CardContent className="p-6 space-y-3">
              <Button className="w-full bg-gradient-to-r from-blue-500 to-indigo-500 text-white font-bold py-3 shadow-lg hover:scale-105 transition-all duration-300 border-0">
                <Car className="w-4 h-4 mr-2" />
                직접 타보러 가기
              </Button>
              <Button className="w-full bg-gradient-to-r from-green-500 to-emerald-500 text-white font-bold py-3 shadow-lg hover:scale-105 transition-all duration-300 border-0">
                <DollarSign className="w-4 h-4 mr-2" />
                가격 알아보기
              </Button>
              <Button
                onClick={onStartOver}
                className="w-full bg-gradient-to-r from-purple-500 to-pink-500 text-white font-bold py-3 shadow-lg hover:scale-105 transition-all duration-300 border-0"
              >
                <RefreshCcw className="w-4 h-4 mr-2" />
                다른 차도 찾아보기
              </Button>
            </CardContent>
          </Card>
        </div>

        {/* 푸터 */}
        <div className="text-center py-8">
          <p className="text-slate-600 mb-2">
            🎊 CarFin AI와 함께한 스마트한 차량 선택을 축하합니다!
          </p>
          <p className="text-sm text-slate-500">
            전문가 상담 ID: {result.consultation_id}
          </p>
        </div>
      </div>
    </div>
  );
}

'use client';

import { useState } from 'react';
import { ThumbsUp, ThumbsDown, MessageCircle, RefreshCw, Star, Heart, Frown, Lightbulb, Settings } from 'lucide-react';
import RecommendationRefinementModal from '@/components/ui/RecommendationRefinementModal';

interface SatisfactionFeedbackProps {
  recommendations: any[];
  onFeedback: (feedback: FeedbackData) => void;
  onRecommendationRequest: (refinement: string) => void;
  isVisible: boolean;
}

interface FeedbackData {
  satisfaction: 'satisfied' | 'neutral' | 'dissatisfied';
  reasons: string[];
  suggestions: string;
  specificIssues: string[];
  preferredAdjustments: string[];
}

export default function SatisfactionFeedback({
  recommendations,
  onFeedback,
  onRecommendationRequest,
  isVisible
}: SatisfactionFeedbackProps) {
  const [currentStep, setCurrentStep] = useState<'initial' | 'dissatisfied_detail' | 'refinement' | 'completed'>('initial');
  const [selectedSatisfaction, setSelectedSatisfaction] = useState<string | null>(null);
  const [selectedReasons, setSelectedReasons] = useState<string[]>([]);
  const [customSuggestion, setCustomSuggestion] = useState('');
  const [refinementRequests, setRefinementRequests] = useState<string[]>([]);
  const [showRefinementModal, setShowRefinementModal] = useState(false);

  const satisfactionOptions = [
    {
      id: 'satisfied',
      label: '만족해요!',
      icon: <Heart className="w-5 h-5" />,
      color: 'from-green-500 to-emerald-600',
      description: '추천해주신 차량들이 마음에 들어요',
      emoji: '😊'
    },
    {
      id: 'neutral',
      label: '괜찮은데...',
      icon: <Star className="w-5 h-5" />,
      color: 'from-yellow-500 to-orange-500',
      description: '나쁘지 않지만 더 좋은 옵션이 있을 것 같아요',
      emoji: '🤔'
    },
    {
      id: 'dissatisfied',
      label: '아쉬워요',
      icon: <Frown className="w-5 h-5" />,
      color: 'from-red-500 to-pink-600',
      description: '제 니즈와 조금 다른 것 같아요',
      emoji: '😅'
    }
  ];

  const dissatisfactionReasons = [
    { id: 'budget', label: '💰 예산이 맞지 않아요', detail: '추천 차량들이 예산보다 높거나 낮아요' },
    { id: 'brand', label: '🏷️ 브랜드 선호도', detail: '선호하는 브랜드가 다르거나 없어요' },
    { id: 'size', label: '📏 크기/공간', detail: '차량 크기가 제 용도에 맞지 않아요' },
    { id: 'fuel', label: '⛽ 연료/효율성', detail: '연비나 연료 타입이 고려되지 않았어요' },
    { id: 'age', label: '📅 연식/상태', detail: '너무 오래되었거나 주행거리가 많아요' },
    { id: 'features', label: '⚙️ 옵션/기능', detail: '필요한 기능이나 옵션이 부족해요' },
    { id: 'location', label: '📍 지역/접근성', detail: '차량 위치가 너무 멀거나 불편해요' },
    { id: 'variety', label: '🔄 다양성 부족', detail: '비슷한 차량들만 추천되었어요' }
  ];

  const refinementSuggestions = [
    '예산을 조금 더 유연하게 조정해서 추천해주세요',
    '다른 브랜드도 포함해서 폭넓게 찾아주세요',
    '더 큰(작은) 차량으로 옵션을 확장해주세요',
    '최신 연식 위주로 다시 찾아주세요',
    '연비가 더 좋은 차량들로 재검색해주세요',
    '프리미엄 옵션이 있는 차량들을 찾아주세요',
    '가까운 지역의 매물들로 다시 추천해주세요',
    '완전히 다른 관점에서 새롭게 추천해주세요'
  ];

  const handleSatisfactionSelect = (satisfaction: string) => {
    setSelectedSatisfaction(satisfaction);

    if (satisfaction === 'satisfied') {
      // 만족한 경우 바로 완료
      onFeedback({
        satisfaction: 'satisfied',
        reasons: [],
        suggestions: '',
        specificIssues: [],
        preferredAdjustments: []
      });
      setCurrentStep('completed');
    } else if (satisfaction === 'dissatisfied') {
      // 불만족한 경우 상세 이유 물어보기
      setCurrentStep('dissatisfied_detail');
    } else {
      // 중립적인 경우 바로 개선 제안
      setCurrentStep('refinement');
    }
  };

  const handleReasonToggle = (reasonId: string) => {
    setSelectedReasons(prev =>
      prev.includes(reasonId)
        ? prev.filter(id => id !== reasonId)
        : [...prev, reasonId]
    );
  };

  const handleRefinementRequest = (suggestion: string) => {
    onRecommendationRequest(suggestion);
    setCurrentStep('completed');
  };

  const handleAdvancedRefinement = (refinementOptions: any) => {
    // Convert refinement options to text request
    let requestText = '다음 조건으로 새로운 추천을 원합니다: ';

    const conditions = [];

    if (refinementOptions.budget?.max) {
      conditions.push(`예산 ${refinementOptions.budget.max}만원 이하`);
    }

    if (refinementOptions.sizeCategory && refinementOptions.sizeCategory !== 'any') {
      conditions.push(`차량 크기: ${refinementOptions.sizeCategory}`);
    }

    if (refinementOptions.fuelType && refinementOptions.fuelType !== 'any') {
      conditions.push(`연료 타입: ${refinementOptions.fuelType}`);
    }

    if (refinementOptions.agePreference?.minYear) {
      conditions.push(`${refinementOptions.agePreference.minYear}년 이후 모델`);
    }

    // Priority adjustments
    const priorities = refinementOptions.priorities;
    const highPriorities = Object.entries(priorities)
      .filter(([_, value]) => (value as number) >= 4)
      .map(([key, _]) => {
        const labels: Record<string, string> = {
          economy: '경제성',
          performance: '성능',
          safety: '안전성',
          comfort: '편의성',
          reliability: '신뢰성'
        };
        return labels[key];
      });

    if (highPriorities.length > 0) {
      conditions.push(`${highPriorities.join(', ')} 중시`);
    }

    if (refinementOptions.excludeOptions?.currentRecommendations) {
      conditions.push('현재 추천과 다른 차량들로');
    }

    if (refinementOptions.customRequest) {
      conditions.push(refinementOptions.customRequest);
    }

    requestText += conditions.join(', ');

    onRecommendationRequest(requestText);
    setCurrentStep('completed');
    setShowRefinementModal(false);
  };

  const proceedToRefinement = () => {
    setCurrentStep('refinement');

    // 피드백 데이터 전송
    onFeedback({
      satisfaction: selectedSatisfaction as any,
      reasons: selectedReasons,
      suggestions: customSuggestion,
      specificIssues: selectedReasons,
      preferredAdjustments: refinementRequests
    });
  };

  if (!isVisible) return null;

  return (
    <div className="bg-gradient-to-br from-blue-50 to-indigo-50 rounded-2xl p-6 border border-blue-200 shadow-lg mt-6">
      <div className="text-center mb-6">
        <div className="inline-flex items-center gap-3 bg-gradient-to-r from-blue-600 to-indigo-600 text-white px-6 py-3 rounded-xl mb-4">
          <MessageCircle className="w-6 h-6" />
          <h3 className="text-lg font-bold">추천 만족도 조사</h3>
        </div>
        <p className="text-gray-600 max-w-2xl mx-auto leading-relaxed">
          {currentStep === 'initial' && '추천받은 차량들이 마음에 드시나요? 솔직한 의견을 들려주세요!'}
          {currentStep === 'dissatisfied_detail' && '어떤 부분이 아쉬우셨는지 알려주시면, 더 나은 추천을 드릴게요.'}
          {currentStep === 'refinement' && '이런 방향으로 다시 추천해드릴까요?'}
          {currentStep === 'completed' && '소중한 피드백 감사합니다! 더 나은 추천을 위해 활용하겠습니다.'}
        </p>
      </div>

      {/* 초기 만족도 선택 */}
      {currentStep === 'initial' && (
        <div className="grid md:grid-cols-3 gap-4">
          {satisfactionOptions.map((option) => (
            <button
              key={option.id}
              onClick={() => handleSatisfactionSelect(option.id)}
              className="p-6 bg-white rounded-xl border border-gray-200 hover:shadow-lg hover:scale-105 transition-all duration-300 text-left group"
            >
              <div className={`bg-gradient-to-r ${option.color} text-white p-3 rounded-lg mb-4 w-fit`}>
                {option.icon}
              </div>
              <div className="flex items-center gap-2 mb-2">
                <span className="text-2xl">{option.emoji}</span>
                <h4 className="font-bold text-gray-800">{option.label}</h4>
              </div>
              <p className="text-sm text-gray-600">{option.description}</p>
            </button>
          ))}
        </div>
      )}

      {/* 불만족 상세 이유 */}
      {currentStep === 'dissatisfied_detail' && (
        <div className="space-y-6">
          <div className="grid md:grid-cols-2 gap-3">
            {dissatisfactionReasons.map((reason) => (
              <button
                key={reason.id}
                onClick={() => handleReasonToggle(reason.id)}
                className={`p-4 rounded-lg border text-left transition-all duration-200 ${
                  selectedReasons.includes(reason.id)
                    ? 'border-red-300 bg-red-50 shadow-md'
                    : 'border-gray-200 bg-white hover:bg-gray-50'
                }`}
              >
                <div className="font-medium text-sm mb-1">{reason.label}</div>
                <div className="text-xs text-gray-600">{reason.detail}</div>
              </button>
            ))}
          </div>

          <div className="space-y-3">
            <label className="block text-sm font-medium text-gray-700">
              💬 추가로 하고 싶은 말씀이 있으시면 자유롭게 적어주세요
            </label>
            <textarea
              value={customSuggestion}
              onChange={(e) => setCustomSuggestion(e.target.value)}
              placeholder="예: 골프백이 들어가는 차량이면 좋겠어요, 아이들과 여행 다니기 편한 차량 추천해주세요..."
              className="w-full p-3 border border-gray-300 rounded-lg resize-none h-20 text-sm"
            />
          </div>

          <div className="flex justify-center">
            <button
              onClick={proceedToRefinement}
              disabled={selectedReasons.length === 0}
              className="inline-flex items-center gap-2 px-6 py-3 bg-gradient-to-r from-blue-600 to-indigo-600 text-white rounded-xl hover:from-blue-700 hover:to-indigo-700 transition-colors disabled:opacity-50 disabled:cursor-not-allowed"
            >
              <Lightbulb className="w-5 h-5" />
              <span>개선된 추천 받기</span>
            </button>
          </div>
        </div>
      )}

      {/* 개선 제안 */}
      {currentStep === 'refinement' && (
        <div className="space-y-4">
          <div className="grid md:grid-cols-2 gap-3">
            {refinementSuggestions.map((suggestion, index) => (
              <button
                key={index}
                onClick={() => handleRefinementRequest(suggestion)}
                className="p-4 bg-white rounded-lg border border-gray-200 hover:shadow-md hover:border-blue-300 transition-all duration-200 text-left text-sm"
              >
                <div className="flex items-start gap-3">
                  <RefreshCw className="w-4 h-4 text-blue-600 mt-0.5 flex-shrink-0" />
                  <span>{suggestion}</span>
                </div>
              </button>
            ))}
          </div>

          <div className="text-center mt-6">
            <p className="text-sm text-gray-500 mb-4">
              또는 세부 조건을 직접 설정해보세요
            </p>
            <div className="flex gap-3 justify-center">
              <button
                onClick={() => setShowRefinementModal(true)}
                className="inline-flex items-center gap-2 px-6 py-3 bg-gradient-to-r from-purple-600 to-blue-600 text-white rounded-xl hover:from-purple-700 hover:to-blue-700 transition-all shadow-lg hover:shadow-xl"
              >
                <Settings className="w-5 h-5" />
                <span className="font-bold">상세 조건 설정</span>
              </button>
              <button
                onClick={() => {
                  const customRequest = prompt('어떤 방향으로 다시 추천해드릴까요?');
                  if (customRequest) {
                    handleRefinementRequest(customRequest);
                  }
                }}
                className="inline-flex items-center gap-2 px-4 py-2 border border-blue-300 text-blue-700 rounded-lg hover:bg-blue-50 transition-colors"
              >
                <MessageCircle className="w-4 h-4" />
                <span>직접 요청하기</span>
              </button>
            </div>
          </div>
        </div>
      )}

      {/* 완료 상태 */}
      {currentStep === 'completed' && (
        <div className="text-center py-6">
          <div className="w-16 h-16 bg-gradient-to-r from-green-500 to-emerald-600 rounded-full flex items-center justify-center mx-auto mb-4">
            <ThumbsUp className="w-8 h-8 text-white" />
          </div>
          <h4 className="text-lg font-bold text-gray-800 mb-2">피드백 완료!</h4>
          <p className="text-gray-600 text-sm">
            {selectedSatisfaction === 'satisfied'
              ? '만족스러운 추천이었다니 정말 기뻐요! 🎉'
              : '더 나은 추천을 위해 새로운 분석을 시작하겠습니다! 🚀'
            }
          </p>
        </div>
      )}

      {/* N번째 질문 환영 메시지 */}
      <div className="mt-6 text-center">
        <div className="inline-flex items-center gap-2 text-xs text-gray-500">
          <Star className="w-4 h-4" />
          <span>N번째 질문 환영! 완벽한 매칭까지 계속해서 도와드릴게요</span>
        </div>
      </div>

      {/* 상세 조건 설정 모달 */}
      <RecommendationRefinementModal
        isOpen={showRefinementModal}
        onClose={() => setShowRefinementModal(false)}
        onRefine={handleAdvancedRefinement}
        currentRecommendations={recommendations}
        currentPersona={recommendations[0]?.metadata?.persona}
      />
    </div>
  );
}

'use client';

import { useState, useEffect } from 'react';
import Link from 'next/link';
import { usePathname } from 'next/navigation';
import { Home, MessageSquare, BarChart3, Database, Zap, Menu, X } from 'lucide-react';

interface DatabaseStatus {
  isConnected: boolean;
  totalVehicles: number;
  availableVehicles: number;
}

export default function Header() {
  const pathname = usePathname();
  const [dbStatus, setDbStatus] = useState<DatabaseStatus>({
    isConnected: false,
    totalVehicles: 0,
    availableVehicles: 0,
  });
  const [isMobileMenuOpen, setIsMobileMenuOpen] = useState(false);

  // 실시간 데이터베이스 상태 모니터링
  useEffect(() => {
    const checkDatabase = async () => {
      try {
        const response = await fetch('/api/database/status');
        const data = await response.json();
        setDbStatus(data);
      } catch (error) {
        console.error('DB 상태 체크 실패:', error);
      }
    };

    checkDatabase();
    const interval = setInterval(checkDatabase, 10000); // 10초마다 체크
    return () => clearInterval(interval);
  }, []);

  const navigationItems = [
    {
      name: '홈',
      href: '/',
      icon: Home,
      description: '메인 검색'
    },
    {
      name: 'AI 채팅',
      href: '/chatroom',
      icon: MessageSquare,
      description: '실시간 상담'
    },
    {
      name: '대시보드',
      href: '/dashboard',
      icon: BarChart3,
      description: '랭킹 분석'
    }
  ];

  const isActive = (href: string) => {
    if (href === '/') return pathname === '/';
    return pathname.startsWith(href);
  };

  return (
    <header className="sticky top-0 z-50 bg-white/95 backdrop-blur-md border-b border-gray-200 shadow-sm">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        <div className="flex items-center justify-between h-16">

          {/* 로고 및 브랜드 */}
          <div className="flex items-center">
            <Link href="/" className="flex items-center space-x-3">
              <div className="w-8 h-8 bg-gradient-to-r from-blue-600 to-purple-600 rounded-lg flex items-center justify-center">
                <Zap className="w-5 h-5 text-white" />
              </div>
              <div className="hidden sm:block">
                <h1 className="text-xl font-bold text-gray-900">CarFin AI</h1>
                <p className="text-xs text-gray-500">논문 기반 추천 시스템</p>
              </div>
            </Link>
          </div>

          {/* 데스크톱 네비게이션 */}
          <nav className="hidden md:flex items-center space-x-8">
            {navigationItems.map((item) => {
              const IconComponent = item.icon;
              const active = isActive(item.href);

              return (
                <Link
                  key={item.name}
                  href={item.href}
                  className={`flex items-center space-x-2 px-3 py-2 rounded-lg text-sm font-medium transition-colors ${
                    active
                      ? 'bg-blue-100 text-blue-700'
                      : 'text-gray-600 hover:text-blue-600 hover:bg-gray-100'
                  }`}
                >
                  <IconComponent className="w-4 h-4" />
                  <span>{item.name}</span>
                </Link>
              );
            })}
          </nav>

          {/* 실시간 상태 표시 */}
          <div className="hidden lg:flex items-center space-x-4">
            {/* 데이터베이스 상태 */}
            <div className={`flex items-center space-x-2 px-3 py-1 rounded-full text-xs font-medium ${
              dbStatus.isConnected
                ? 'bg-green-100 text-green-700'
                : 'bg-red-100 text-red-700'
            }`}>
              <Database className="w-3 h-3" />
              <span>
                {dbStatus.isConnected
                  ? `${(dbStatus.availableVehicles / 1000).toFixed(0)}K 매물`
                  : '연결 중...'
                }
              </span>
            </div>

            {/* 시스템 상태 */}
            <div className="flex items-center space-x-2 px-3 py-1 bg-blue-100 text-blue-700 rounded-full text-xs font-medium">
              <div className="w-2 h-2 bg-blue-500 rounded-full animate-pulse"></div>
              <span>AI 활성</span>
            </div>
          </div>

          {/* 모바일 메뉴 버튼 */}
          <button
            onClick={() => setIsMobileMenuOpen(!isMobileMenuOpen)}
            className="md:hidden p-2 rounded-lg text-gray-600 hover:text-blue-600 hover:bg-gray-100"
          >
            {isMobileMenuOpen ? (
              <X className="w-6 h-6" />
            ) : (
              <Menu className="w-6 h-6" />
            )}
          </button>
        </div>

        {/* 모바일 메뉴 */}
        {isMobileMenuOpen && (
          <div className="md:hidden border-t border-gray-200 py-4">
            <nav className="space-y-2">
              {navigationItems.map((item) => {
                const IconComponent = item.icon;
                const active = isActive(item.href);

                return (
                  <Link
                    key={item.name}
                    href={item.href}
                    onClick={() => setIsMobileMenuOpen(false)}
                    className={`flex items-center justify-between p-3 rounded-lg transition-colors ${
                      active
                        ? 'bg-blue-100 text-blue-700'
                        : 'text-gray-600 hover:text-blue-600 hover:bg-gray-50'
                    }`}
                  >
                    <div className="flex items-center space-x-3">
                      <IconComponent className="w-5 h-5" />
                      <div>
                        <div className="font-medium">{item.name}</div>
                        <div className="text-xs text-gray-500">{item.description}</div>
                      </div>
                    </div>
                    {active && (
                      <div className="w-2 h-2 bg-blue-500 rounded-full"></div>
                    )}
                  </Link>
                );
              })}
            </nav>

            {/* 모바일 상태 정보 */}
            <div className="mt-4 pt-4 border-t border-gray-200">
              <div className="flex items-center justify-between text-sm text-gray-600">
                <div className="flex items-center space-x-2">
                  <Database className="w-4 h-4" />
                  <span>
                    {dbStatus.isConnected
                      ? `${(dbStatus.availableVehicles / 1000).toFixed(0)}K 매물 연결됨`
                      : '데이터베이스 연결 중...'
                    }
                  </span>
                </div>
                <div className={`w-2 h-2 rounded-full ${
                  dbStatus.isConnected ? 'bg-green-500' : 'bg-red-500'
                }`}></div>
              </div>
            </div>
          </div>
        )}
      </div>
    </header>
  );
}

// 페이지별 브레드크럼 컴포넌트
export function PageBreadcrumb({ title, description }: { title: string; description?: string }) {
  return (
    <div className="bg-gradient-to-r from-blue-50 to-purple-50 border-b border-gray-200">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-6">
        <h1 className="text-2xl font-bold text-gray-900">{title}</h1>
        {description && (
          <p className="text-gray-600 mt-1">{description}</p>
        )}
      </div>
    </div>
  );
}

// A2AVisualization.tsx - 실시간 Agent-to-Agent 협업 시각화 컴포넌트

import React, { useState, useEffect } from 'react';

interface A2AEvent {
  type: 'agent_question' | 'agent_answer' | 'agent_response' | 'pattern_detected' | 'collaboration_complete';
  agentId: string;
  content: string;
  timestamp: Date;
  metadata?: {
    targetAgent?: string;
    pattern?: { type: string };
    persona?: string;
    round?: number;
  };
}

interface A2AVisualizationProps {
  isActive: boolean;
  currentPersona?: string;
}

const agentInfo = {
  concierge: {
    name: '컨시어지 매니저',
    emoji: '👨‍💼',
    color: 'blue',
    role: '전체 상담 관리'
  },
  needs_analyst: {
    name: '니즈 분석 전문가',
    emoji: '🧠',
    color: 'purple',
    role: '숨은 니즈 발굴'
  },
  data_analyst: {
    name: '데이터 분석 전문가',
    emoji: '📊',
    color: 'green',
    role: '최적 차량 검색'
  }
};

export default function A2AVisualization({ isActive, currentPersona }: A2AVisualizationProps) {
  const [collaborationEvents, setCollaborationEvents] = useState<A2AEvent[]>([]);
  const [activeConnections, setActiveConnections] = useState<string[]>([]);
  const [currentRound, setCurrentRound] = useState(0);

  // 실시간 A2A 이벤트 시뮬레이션
  useEffect(() => {
    if (!isActive) return;

    const simulateA2AEvents = () => {
      const events: A2AEvent[] = [
        {
          type: 'pattern_detected',
          agentId: 'system',
          content: currentPersona ? `${currentPersona} 페르소나 패턴 감지됨` : '고객 패턴 분석 완료',
          timestamp: new Date(),
          metadata: { pattern: { type: currentPersona || 'general' } }
        },
        {
          type: 'agent_question',
          agentId: 'concierge',
          content: '고객님 상황 분석 완료. 니즈 분석 의뢰드립니다',
          timestamp: new Date(),
          metadata: { targetAgent: 'needs_analyst', round: 1 }
        },
        {
          type: 'agent_answer',
          agentId: 'needs_analyst',
          content: '숨은 니즈 파악 완료. 데이터 분석 의뢰합니다',
          timestamp: new Date(),
          metadata: { round: 1 }
        },
        {
          type: 'agent_response',
          agentId: 'data_analyst',
          content: '117,129대 매물 스캔 및 최적 차량 선별 완료',
          timestamp: new Date(),
          metadata: { round: 2 }
        }
      ];

      events.forEach((event, index) => {
        setTimeout(() => {
          setCollaborationEvents(prev => [...prev, event]);
          setCurrentRound(prev => Math.max(prev, event.metadata?.round || 0));

          // 연결 상태 업데이트
          if (event.type === 'agent_question' && event.metadata?.targetAgent) {
            setActiveConnections(prev => [...prev, `${event.agentId} → ${event.metadata!.targetAgent}`]);
          }
        }, index * 2000);
      });
    };

    simulateA2AEvents();
  }, [isActive, currentPersona]);

  if (!isActive) return null;

  return (
    <div className="bg-gradient-to-br from-slate-50 to-blue-50 rounded-xl p-6 border border-slate-200">
      {/* 헤더 */}
      <div className="flex items-center justify-between mb-6">
        <div>
          <h3 className="text-lg font-semibold text-slate-800 flex items-center gap-2">
            🚀 실시간 A2A 협업 진행 중
            <div className="flex space-x-1">
              <div className="w-2 h-2 bg-green-500 rounded-full animate-pulse"></div>
              <div className="w-2 h-2 bg-green-500 rounded-full animate-pulse" style={{animationDelay: '0.5s'}}></div>
              <div className="w-2 h-2 bg-green-500 rounded-full animate-pulse" style={{animationDelay: '1s'}}></div>
            </div>
          </h3>
          <p className="text-sm text-slate-600">3명의 AI 전문가가 실시간으로 협업하고 있습니다</p>
        </div>
        <div className="text-right">
          <div className="text-sm text-slate-500">현재 라운드</div>
          <div className="text-2xl font-bold text-blue-600">{currentRound}</div>
        </div>
      </div>

      {/* 에이전트 네트워크 시각화 */}
      <div className="grid grid-cols-3 gap-4 mb-6">
        {Object.entries(agentInfo).map(([id, info]) => (
          <div
            key={id}
            className={`bg-white rounded-lg p-4 border-2 transition-all duration-300 ${
              activeConnections.some(conn => conn.includes(id))
                ? `border-${info.color}-400 shadow-lg scale-105`
                : 'border-slate-200'
            }`}
          >
            <div className="text-center">
              <div className="text-2xl mb-2">{info.emoji}</div>
              <div className="font-medium text-sm text-slate-700">{info.name}</div>
              <div className="text-xs text-slate-500">{info.role}</div>
              {activeConnections.some(conn => conn.includes(id)) && (
                <div className="mt-2">
                  <div className="w-2 h-2 bg-green-500 rounded-full mx-auto animate-ping"></div>
                </div>
              )}
            </div>
          </div>
        ))}
      </div>

      {/* 실시간 협업 로그 */}
      <div className="space-y-3 max-h-60 overflow-y-auto">
        <div className="text-sm font-medium text-slate-700 mb-2">💬 실시간 협업 메시지</div>
        {collaborationEvents.map((event, index) => (
          <div
            key={index}
            className="flex items-start gap-3 p-3 bg-white rounded-lg border border-slate-100 animate-fade-in"
          >
            <div className="text-lg">
              {event.agentId === 'system' ? '⚡' : agentInfo[event.agentId as keyof typeof agentInfo]?.emoji}
            </div>
            <div className="flex-1">
              <div className="flex items-center gap-2 text-xs text-slate-500 mb-1">
                <span className="font-medium">
                  {event.agentId === 'system' ? 'System' : agentInfo[event.agentId as keyof typeof agentInfo]?.name}
                </span>
                {event.metadata?.targetAgent && (
                  <span>→ {agentInfo[event.metadata.targetAgent as keyof typeof agentInfo]?.name}</span>
                )}
                <span>{event.timestamp.toLocaleTimeString()}</span>
              </div>
              <div className="text-sm text-slate-700">{event.content}</div>
              {event.metadata?.round && (
                <div className="text-xs text-blue-600 mt-1">Round {event.metadata.round}</div>
              )}
            </div>
          </div>
        ))}
      </div>

      {/* 하단 기술 설명 */}
      <div className="mt-6 pt-4 border-t border-slate-200">
        <div className="text-xs text-slate-600 text-center">
          ⚡ 이것이 바로 <span className="font-semibold text-blue-600">멀티 에이전트 A2A 프로토콜</span>입니다
          <br />
          각 전문가가 서로 질문하고 답변하며 최적의 결과를 도출합니다
        </div>
      </div>

      <style jsx>{`
        .animate-fade-in {
          animation: fadeIn 0.5s ease-in;
        }

        @keyframes fadeIn {
          from { opacity: 0; transform: translateY(10px); }
          to { opacity: 1; transform: translateY(0); }
        }
      `}</style>
    </div>
  );
}

'use client';

import { useState } from 'react';

interface AgentInsightCardProps {
  agent: string;
  content: string;
  tcoSummary?: {
    averageTCO: number;
    bestValueVehicle: string;
    costRange: string;
  };
}

export default function AgentInsightCard({ agent, content, tcoSummary }: AgentInsightCardProps) {
  const [isExpanded, setIsExpanded] = useState(false);

  const getAgentInfo = (agent: string) => {
    switch (agent) {
      case 'needs_analyst':
        return {
          emoji: '🔍',
          name: '니즈 분석',
          color: 'orange',
          bgClass: 'bg-gradient-to-r from-orange-50 to-orange-100',
          borderClass: 'border-orange-200',
          summary: extractSummary(content, agent)
        };
      case 'data_analyst':
        return {
          emoji: '📊',
          name: '데이터 분석',
          color: 'green',
          bgClass: 'bg-gradient-to-r from-green-50 to-green-100',
          borderClass: 'border-green-200',
          summary: extractSummary(content, agent)
        };
      case 'concierge':
        return {
          emoji: '🎯',
          name: '컨시어지',
          color: 'blue',
          bgClass: 'bg-gradient-to-r from-blue-50 to-blue-100',
          borderClass: 'border-blue-200',
          summary: extractSummary(content, agent)
        };
      default:
        return {
          emoji: '🤖',
          name: '전문가',
          color: 'gray',
          bgClass: 'bg-gradient-to-r from-gray-50 to-gray-100',
          borderClass: 'border-gray-200',
          summary: extractSummary(content, agent)
        };
    }
  };

  // 에이전트별 개성있는 핵심 인사이트 추출 함수 - 멘토링 피드백 반영
  const extractSummary = (content: string, agent: string) => {
    const sentences = content.split(/[.!?]/).filter(s => s.trim().length > 10);

    const getAgentCoreInsight = (text: string, agentType: string) => {
      switch (agentType) {
        case 'needs_analyst':
          // 핵심 니즈만 요약 (긴 추론과정 → 핵심 인사이트만)
          if (text.includes('CEO') || text.includes('사장') || text.includes('법인차')) {
            return '🔍 CEO 페르소나 감지: 골프백 수납, 비즈니스 품격, 절세 효과를 우선 고려';
          }
          if (text.includes('가족') || text.includes('아이') || text.includes('워킹맘')) {
            return '🔍 가족 중심 라이프스타일: 안전성과 편의성이 최우선';
          }
          if (text.includes('MZ') || text.includes('젊은') || text.includes('직장')) {
            return '🔍 MZ세대 감지: 디자인, 연비, 스타일을 중시하는 패턴';
          }
          if (text.includes('캠핑') || text.includes('레저') || text.includes('활동')) {
            return '🔍 액티브 라이프스타일: 공간 활용과 내구성 중심 니즈';
          }
          if (text.includes('첫차') || text.includes('초보') || text.includes('불안')) {
            return '🔍 첫차 구매 불안감: 안전성과 신뢰성이 핵심 관심사';
          }

          // 일반적인 핵심 니즈 추출
          const keyNeedsPattern = /(?:가장|특히|중요한|우선|핵심)\s*(.{10,50})/gi;
          const match = text.match(keyNeedsPattern);
          if (match && match[0]) {
            return `🔍 핵심 니즈: ${match[0].replace(/^(가장|특히|중요한|우선|핵심)\s*/, '').slice(0, 40)}`;
          }

          return '🔍 고객님의 라이프스타일과 우선순위를 파악했습니다';

        case 'data_analyst':
          // TCO와 매물 분석 핵심만 요약
          const priceMatch = text.match(/(\d{1,4}(?:,\d{3})*)\s*만원/);
          const vehicleMatch = text.match(/(\d+)\s*대/);

          if (priceMatch && vehicleMatch) {
            return `📊 매물 분석: ${vehicleMatch[1]}대 검토, 평균 ${priceMatch[1]}만원대 추천`;
          }
          if (text.includes('TCO') || text.includes('총소유비용')) {
            return '📊 TCO 분석: 구매가격 + 유지비 + 감가상각 종합 고려';
          }
          if (text.includes('가성비') || text.includes('경제성')) {
            return '📊 가성비 최적화: 예산 대비 최고 효율 차량 선별';
          }
          if (text.includes('감가') || text.includes('잔가')) {
            return '📊 감가율 분석: 향후 3년 가치 보존력 평가';
          }

          // 구체적 수치가 있으면 표시
          const specificData = text.match(/(\d+(?:,\d+)*(?:\s*만원|\s*대|\s*%|\s*년))/g);
          if (specificData && specificData.length > 0) {
            return `📊 데이터 분석: ${specificData.slice(0, 2).join(', ')} 기준 최적화`;
          }

          return '📊 실제 매물 데이터로 최적 조건을 선별했습니다';

        case 'concierge':
          // 친근한 결론과 다음 단계 안내
          if (text.includes('환영') || text.includes('시작')) {
            return '🎯 CarFin AI 컨시어지가 맞춤 상담을 시작합니다';
          }
          if (text.includes('완료') || text.includes('분석')) {
            return '🎯 전문가팀 협업 완료: 고객님께 최적 매칭 차량을 준비했습니다';
          }
          if (text.includes('3명') || text.includes('협업') || text.includes('전문가')) {
            return '🎯 3명의 전문가가 머리를 맞대고 최고의 답변을 준비했습니다';
          }
          if (text.includes('질문') || text.includes('궁금')) {
            return '🎯 추가 궁금한 점이 있으시면 언제든 말씀해 주세요';
          }

          // 첫 문장에서 핵심 메시지 추출
          const firstSentence = sentences[0]?.trim();
          if (firstSentence && firstSentence.length > 15) {
            return `🎯 ${firstSentence.slice(0, 50)}${firstSentence.length > 50 ? '...' : ''}`;
          }

          return '🎯 고객님만을 위한 맞춤 상담을 진행하겠습니다';

        default:
          const defaultFirstSentence = sentences[0];
          if (defaultFirstSentence && defaultFirstSentence.length > 10) {
            return defaultFirstSentence.length > 80 ? defaultFirstSentence.slice(0, 77) + '...' : defaultFirstSentence;
          }
          return text.slice(0, 50) + '...';
      }
    };

    return getAgentCoreInsight(content, agent);
  };

  const agentInfo = getAgentInfo(agent);

  // 핵심 키워드 추출 (카드 우상단 배지용)
  const extractKeyInsight = (content: string, agent: string) => {
    switch (agent) {
      case 'needs_analyst':
        if (content.includes('CEO') || content.includes('사장') || content.includes('법인차')) return 'CEO급';
        if (content.includes('가족') || content.includes('아이')) return '가족형';
        if (content.includes('MZ') || content.includes('젊은')) return 'MZ세대';
        if (content.includes('캠핑') || content.includes('레저')) return '레저형';
        return '분석완료';

      case 'data_analyst':
        if (content.includes('TCO') || content.includes('총소유비용')) return 'TCO분석';
        if (content.includes('가성비') || content.includes('경제성')) return '가성비';
        if (content.includes('감가') || content.includes('잔가')) return '감가분석';
        if (content.includes('추천') || content.includes('매물')) return '매물분석';
        return '데이터완료';

      case 'concierge':
        if (content.includes('환영') || content.includes('시작')) return '상담시작';
        if (content.includes('완료') || content.includes('준비')) return '준비완료';
        if (content.includes('매칭') || content.includes('추천')) return '매칭완료';
        return '진행중';

      default:
        return '완료';
    }
  };

  const keyInsight = extractKeyInsight(content, agent);

  return (
    <div
      className={`${agentInfo.bgClass} p-5 rounded-2xl border ${agentInfo.borderClass} mb-4 shadow-lg hover:shadow-xl hover:scale-[1.02] transition-all duration-300 animate-in slide-in-from-left-4 fade-in-0 relative overflow-hidden backdrop-blur-sm`}
      role="article"
      aria-label={`${agentInfo.name} 전문가 인사이트`}
    >
      {/* 강화된 배경 효과 */}
      <div className="absolute top-0 right-0 w-24 h-24 bg-gradient-to-bl from-white/60 to-transparent rounded-full -mr-12 -mt-12"></div>
      <div className="absolute bottom-0 left-0 w-16 h-16 bg-gradient-to-tr from-white/30 to-transparent rounded-full -ml-8 -mb-8"></div>

      {/* 분석 완료 진행률 표시 */}
      <div className="absolute top-2 left-2">
        <div className="w-3 h-3 bg-green-400 rounded-full animate-pulse shadow-lg border-2 border-white" title="분석 완료"></div>
      </div>

      {/* 핵심 인사이트 배지 - 강화된 디자인 */}
      <div className="absolute top-3 right-3">
        <span className={`inline-flex items-center px-3 py-1.5 rounded-full text-xs font-bold shadow-md ${
          agent === 'needs_analyst' ? 'bg-gradient-to-r from-orange-100 to-orange-200 text-orange-800 border border-orange-300' :
          agent === 'data_analyst' ? 'bg-gradient-to-r from-green-100 to-green-200 text-green-800 border border-green-300' :
          'bg-gradient-to-r from-blue-100 to-blue-200 text-blue-800 border border-blue-300'
        }`}>
          ✅ {keyInsight}
        </span>
      </div>

      <div className="flex items-start gap-3 pr-16">
        <div className="text-2xl flex-shrink-0 hover:scale-110 transition-transform duration-200" aria-hidden="true">{agentInfo.emoji}</div>
        <div className="flex-1 min-w-0">
          <div className="flex items-center justify-between mb-3">
            <div className="font-bold text-gray-900 text-base flex items-center gap-2" id={`agent-${agent}-title`}>
              <span className="bg-white/60 rounded-lg px-2 py-1 text-sm">
                {agentInfo.name} 전문가
              </span>
              <span className="text-xs text-gray-500 bg-white/40 rounded-full px-2 py-0.5">
                분석 완료
              </span>
            </div>
          </div>

          {/* 핵심 인사이트 표시 - 카드 중심 디자인 */}
          <div className="mb-4">
            <div className="text-sm text-gray-800 leading-relaxed font-semibold bg-white/80 rounded-lg p-3 border border-gray-100 shadow-sm">
              {agentInfo.summary}
            </div>
          </div>

          {/* 에이전트별 맞춤 액션 버튼 */}
          {agent === 'needs_analyst' && (
            <div className="mb-3 flex flex-wrap gap-2">
              <button className="text-xs px-3 py-1.5 bg-orange-100 text-orange-700 rounded-full hover:bg-orange-200 transition-colors border border-orange-200">
                🎯 니즈 상세
              </button>
              <button className="text-xs px-3 py-1.5 bg-purple-100 text-purple-700 rounded-full hover:bg-purple-200 transition-colors border border-purple-200">
                👤 페르소나 확인
              </button>
            </div>
          )}

          {agent === 'data_analyst' && (
            <div className="mb-3 flex flex-wrap gap-2">
              <button className="text-xs px-3 py-1.5 bg-green-100 text-green-700 rounded-full hover:bg-green-200 transition-colors border border-green-200">
                💰 TCO 상세
              </button>
              <button className="text-xs px-3 py-1.5 bg-blue-100 text-blue-700 rounded-full hover:bg-blue-200 transition-colors border border-blue-200">
                📊 매물 분석
              </button>
            </div>
          )}

          {agent === 'concierge' && (
            <div className="mb-3 flex flex-wrap gap-2">
              <button className="text-xs px-3 py-1.5 bg-blue-100 text-blue-700 rounded-full hover:bg-blue-200 transition-colors border border-blue-200">
                🤝 상담 진행
              </button>
              <button className="text-xs px-3 py-1.5 bg-indigo-100 text-indigo-700 rounded-full hover:bg-indigo-200 transition-colors border border-indigo-200">
                ❓ 추가 질문
              </button>
            </div>
          )}

          {/* 상세 내용 토글 - 개선된 디자인 */}
          {content.length > 150 && (
            <details className="group">
              <summary className="cursor-pointer text-xs text-gray-500 hover:text-gray-700 transition-colors list-none flex items-center gap-2 p-2 bg-gray-50 rounded-lg hover:bg-gray-100">
                <span className="group-open:rotate-90 transition-transform text-blue-500">▶</span>
                <span className="group-open:hidden">🔍 상세한 분석 과정 보기</span>
                <span className="hidden group-open:block">📄 분석 과정 접기</span>
                <span className="ml-auto text-xs bg-gray-200 px-2 py-0.5 rounded-full">
                  {Math.ceil(content.length / 50)}줄
                </span>
              </summary>
              <div className="mt-3 p-4 bg-white rounded-lg text-xs text-gray-600 leading-relaxed border border-gray-200 shadow-sm">
                <div className="mb-2 text-xs text-gray-500 font-medium flex items-center gap-1">
                  <span>{agentInfo.emoji}</span>
                  <span>{agentInfo.name} 전문가의 상세 분석</span>
                </div>
                <div className="border-l-2 border-gray-200 pl-3">
                  {content}
                </div>
              </div>
            </details>
          )}

          {/* 데이터 분석가용 TCO 요약 정보 - 개선된 버전 */}
          {agent === 'data_analyst' && tcoSummary && (
            <div className="mt-4 pt-3 border-t border-gray-200">
              <div className="text-xs text-gray-500 font-medium mb-3 flex items-center gap-1">
                <span>📊</span>
                <span>경제성 분석 요약</span>
              </div>
              <div className="grid grid-cols-3 gap-2 text-xs">
                <div className="bg-blue-50 p-2.5 rounded-lg text-center border border-blue-100">
                  <div className="font-bold text-blue-800 text-sm">{tcoSummary.averageTCO.toLocaleString()}만원</div>
                  <div className="text-blue-600 text-xs mt-0.5">평균 3년 TCO</div>
                </div>
                <div className="bg-green-50 p-2.5 rounded-lg text-center border border-green-100">
                  <div className="font-bold text-green-800 text-sm truncate">{tcoSummary.bestValueVehicle}</div>
                  <div className="text-green-600 text-xs mt-0.5">최고 가성비</div>
                </div>
                <div className="bg-orange-50 p-2.5 rounded-lg text-center border border-orange-100">
                  <div className="font-bold text-orange-800 text-sm">{tcoSummary.costRange}</div>
                  <div className="text-orange-600 text-xs mt-0.5">비용 범위</div>
                </div>
              </div>
            </div>
          )}

          {/* CEO 페르소나 특별 표시 */}
          {(content.includes('CEO') || content.includes('사장') || content.includes('법인차') || content.includes('골프')) && (
            <div className="mt-3 p-2 bg-gradient-to-r from-purple-50 to-blue-50 rounded-lg border border-purple-100">
              <div className="text-xs text-purple-700 font-medium flex items-center gap-1">
                <span>👔</span>
                <span>CEO 페르소나 맞춤 분석</span>
              </div>
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

'use client';

import { useState, useEffect } from 'react';
import { Heart, Car, Search } from 'lucide-react';

interface CarFinWaitingUIProps {
  isVisible: boolean;
  currentMessage?: string;
  isProcessing: boolean;
}

export default function CarFinWaitingUI({
  isVisible,
  currentMessage,
  isProcessing
}: CarFinWaitingUIProps) {
  const [currentMessageIndex, setCurrentMessageIndex] = useState(0);
  const [dots, setDots] = useState('');

  // AI 분석 메시지
  const getAnalysisMessages = (message?: string) => {
    return [
      '고객님의 요구사항을 정확히 분석하고 있어요...',
      '90만+ 실제 매물에서 최적의 차량을 찾고 있어요',
      '가격, 성능, 신뢰도를 종합적으로 검토 중이에요',
      '완벽한 매칭을 위해 마지막 점검을 하고 있어요! 😊'
    ];
  };

  const messages = getAnalysisMessages(currentMessage);

  // 메시지 순차 표시
  useEffect(() => {
    if (!isProcessing) return;

    const interval = setInterval(() => {
      setCurrentMessageIndex(prev =>
        prev < messages.length - 1 ? prev + 1 : prev
      );
    }, 2500);

    return () => clearInterval(interval);
  }, [isProcessing, messages.length]);

  // 로딩 점 애니메이션
  useEffect(() => {
    if (!isProcessing) return;

    const interval = setInterval(() => {
      setDots(prev => {
        if (prev === '...') return '';
        return prev + '.';
      });
    }, 400);

    return () => clearInterval(interval);
  }, [isProcessing]);

  if (!isVisible) return null;

  return (
    <div className="bg-gradient-to-br from-blue-50 to-purple-50 border border-blue-200 rounded-2xl p-8 mb-6 shadow-lg">
      {/* 헤더 */}
      <div className="flex items-center gap-4 mb-8">
        <div className="flex items-center justify-center w-12 h-12 bg-gradient-to-br from-blue-500 to-purple-600 rounded-xl">
          <Heart className="w-6 h-6 text-white" />
        </div>
        <div>
          <h3 className="text-xl font-bold text-slate-800">🤖 AI가 분석하고 있어요</h3>
          <p className="text-slate-600">
            고객님만을 위한 최적의 차량을 찾고 있습니다
          </p>
        </div>
        {isProcessing && (
          <div className="ml-auto">
            <div className="flex items-center gap-2 px-4 py-2 bg-blue-100 text-blue-700 rounded-full text-sm font-medium">
              <div className="w-2 h-2 bg-blue-500 rounded-full animate-pulse"></div>
              분석 중{dots}
            </div>
          </div>
        )}
      </div>

      {/* 메인 메시지 */}
      <div className="text-center mb-8">
        <div className="bg-white rounded-xl p-6 shadow-sm border border-blue-100">
          <div className="flex items-center justify-center gap-3 mb-4">
            <Car className="w-8 h-8 text-blue-500" />
            <Search className="w-6 h-6 text-purple-500" />
          </div>

          <div className="text-lg font-medium text-slate-800 mb-2">
            {messages[currentMessageIndex]}
          </div>

          {currentMessageIndex < messages.length - 1 && (
            <div className="flex justify-center gap-2 mt-4">
              {messages.map((_, index) => (
                <div
                  key={index}
                  className={`w-2 h-2 rounded-full transition-colors duration-300 ${
                    index <= currentMessageIndex ? 'bg-blue-500' : 'bg-gray-300'
                  }`}
                />
              ))}
            </div>
          )}
        </div>
      </div>

      {/* 간단한 진행 표시 */}
      {isProcessing && (
        <div className="bg-white rounded-lg p-4 border border-blue-100">
          <div className="flex items-center justify-between text-sm text-slate-600 mb-3">
            <span>🎯 AI 시스템 분석 중</span>
            <span>90만+ 매물 검색</span>
          </div>

          <div className="w-full bg-gray-200 rounded-full h-2">
            <div
              className="bg-gradient-to-r from-blue-500 to-purple-500 h-2 rounded-full transition-all duration-1000"
              style={{
                width: `${Math.min(((currentMessageIndex + 1) / messages.length) * 100, 85)}%`
              }}
            ></div>
          </div>

          <div className="text-center mt-3 text-xs text-slate-500">
            걱정마세요! 완전 무료로 끝까지 함께 해드립니다 💝
          </div>
        </div>
      )}
    </div>
  );
}

