  cons: string[];
  suitabilityScore: number;
  // 🔥 리뷰 인사이트 추가
  reviewInsight?: {
    insight: string;
    sentimentScore: number;
    brandTierAdjustment: string;
    personaRelevance: string;
    sourceReviewCount: number;
    confidence: 'high' | 'medium' | 'low';
  };
  tcoCost?: number;
  tcoBreakdown?: {
    initialCost: number;
    depreciationCost: number;
    maintenanceCost: number;
    fuelCost: number;
    insuranceCost: number;
    totalTCO: number;
    monthlyAverage: number;
    costPerKm: number;
  };
  statisticalInsight?: {
    depreciationTrend: 'stable' | 'declining' | 'volatile';
    marketPosition: 'undervalued' | 'fair' | 'overvalued';
    reliabilityRank: 'excellent' | 'good' | 'average' | 'below_average';
    fuelEconomyRank: 'excellent' | 'good' | 'average' | 'poor';
    totalCostRank: 'budget' | 'mid-range' | 'premium' | 'luxury';
  };
  imageUrl?: string;
  rank: number;
}

interface CompactVehicleCardProps {
  vehicle: VehicleRecommendation;
  personaName?: string;
  rank: number;
}

export default function CompactVehicleCard({ vehicle, personaName, rank }: CompactVehicleCardProps) {
  const [showDetails, setShowDetails] = useState(false);
  const [imageError, setImageError] = useState(false);
  const [realVehicleImage, setRealVehicleImage] = useState<string | null>(null);
  const [imageLoading, setImageLoading] = useState(false);

  const getRankConfig = (rank: number) => {
    switch (rank) {
      case 1:
        return {
          color: 'from-yellow-400 to-orange-500',
          textColor: 'text-yellow-800',
          bgColor: 'bg-yellow-50',
          icon: '🥇',
          label: '1순위 추천',
          borderColor: 'border-yellow-300'
        };
      case 2:
        return {
          color: 'from-gray-400 to-gray-600',
          textColor: 'text-gray-800',
          bgColor: 'bg-gray-50',
          icon: '🥈',
          label: '2순위 추천',
          borderColor: 'border-gray-300'
        };
      case 3:
        return {
          color: 'from-orange-600 to-red-500',
          textColor: 'text-orange-800',
          bgColor: 'bg-orange-50',
          icon: '🥉',
          label: '3순위 추천',
          borderColor: 'border-orange-300'
        };
      default:
        return {
          color: 'from-blue-400 to-blue-600',
          textColor: 'text-blue-800',
          bgColor: 'bg-blue-50',
          icon: '⭐',
          label: '추천 차량',
          borderColor: 'border-blue-300'
        };
    }
  };

  const rankConfig = getRankConfig(rank);

  const getPlatformName = (platform: string) => {
    switch (platform) {
      case 'encar': return '엔카';
      case 'kbchachacha': return 'KB차차차';
      default: return platform;
    }
  };

  // 실제 엔카 매물 이미지를 가져오는 함수
  const fetchRealVehicleImage = async (detailUrl: string) => {
    if (!detailUrl) return null;

    try {
      setImageLoading(true);
      const response = await fetch(`/api/get-vehicle-image?detailUrl=${encodeURIComponent(detailUrl)}`);
      const data = await response.json();

      if (data.success && data.primaryImage) {
        return data.primaryImage;
      } else {
        return null;
      }
    } catch (error) {
      console.error('이미지 크롤링 실패:', error);
      return null;
    } finally {
      setImageLoading(false);
    }
  };

  // 엔카 이미지 URL 생성 함수
  const buildEncarImageUrl = (photoPath: string) => {
    if (photoPath.startsWith('http')) return photoPath;

    const encarImageServers = [
      'https://img1.encar.com',
      'https://img2.encar.com',
      'https://img3.encar.com',
      'https://img4.encar.com'
    ];

    const randomServer = encarImageServers[Math.floor(Math.random() * encarImageServers.length)];
    const cleanPath = photoPath.startsWith('/') ? photoPath : `/${photoPath}`;
    return `${randomServer}${cleanPath}`;
  };

  // 컴포넌트 마운트 시 실제 매물 이미지 가져오기
  useEffect(() => {
    if (vehicle.photo) {
      const imageUrl = buildEncarImageUrl(vehicle.photo);
      setRealVehicleImage(imageUrl);
      return;
    }

    if (vehicle.detailurl && !realVehicleImage) {
      fetchRealVehicleImage(vehicle.detailurl).then(imageUrl => {
        if (imageUrl) {
          setRealVehicleImage(imageUrl);
        }
      });
    }
  }, [vehicle.detailurl, vehicle.photo, realVehicleImage]);

  const handleDetailClick = () => {
    if (vehicle.detailurl) {
      window.open(vehicle.detailurl, '_blank');
    }
  };

  return (
    <div className={`bg-white rounded-xl border-2 ${rankConfig.borderColor} shadow-lg hover:shadow-xl transition-all duration-300 overflow-hidden`}>
      {/* 랭킹 헤더 */}
      <div className={`bg-gradient-to-r ${rankConfig.color} p-4 text-white`}>
        <div className="flex items-center justify-between">
          <div className="flex items-center space-x-3">
            <div className="text-3xl">{rankConfig.icon}</div>
            <div>
              <div className="text-lg font-bold">{rankConfig.label}</div>
              <div className="text-sm opacity-90">{personaName}님 맞춤 추천</div>
            </div>
          </div>
          <div className="text-right">
            <div className="flex items-center space-x-2">
              <Star className="w-5 h-5 fill-current" />
              <span className="text-2xl font-bold">{vehicle.suitabilityScore}</span>
              <span className="text-sm opacity-75">점</span>
            </div>
          </div>
        </div>
      </div>

      {/* 메인 컨텐츠 */}
      <div className="p-5">
        <div className="flex gap-5">
          {/* 차량 이미지 */}
          <div className="w-48 h-32 flex-shrink-0">
            <div className="w-full h-full bg-gradient-to-br from-gray-100 to-gray-200 rounded-lg overflow-hidden">
              {(() => {
                if (realVehicleImage && !imageError) {
                  return (
                    <img
                      src={`/api/proxy-image?url=${encodeURIComponent(realVehicleImage)}`}
                      alt={`${vehicle.manufacturer} ${vehicle.model} 실제 매물 사진`}
                      className="w-full h-full object-cover"
                      onError={() => {
                        if (!realVehicleImage.includes('proxy-image')) {
                          const img = new (globalThis as any).Image();
                          img.onload = () => setRealVehicleImage(realVehicleImage + '?direct=true');
                          img.onerror = () => setImageError(true);
                          img.src = realVehicleImage;
                        } else {
                          setImageError(true);
                        }
                      }}
                      onLoad={() => setImageLoading(false)}
                    />
                  );
                } else {
                  return (
                    <div className="w-full h-full flex items-center justify-center text-gray-500">
                      <div className="text-center">
                        {imageLoading ? (
                          <>
                            <div className="w-6 h-6 mx-auto mb-2 border-3 border-blue-200 border-t-blue-600 rounded-full animate-spin"></div>
                            <p className="text-xs">로딩중...</p>
                          </>
                        ) : (
                          <>
                            <Car className="w-8 h-8 mx-auto mb-2 text-gray-400" />
                            <p className="text-xs font-medium text-gray-600">{vehicle.manufacturer}</p>
                            <p className="text-xs text-gray-500">{vehicle.model}</p>
                          </>
                        )}
                      </div>
                    </div>
                  );
                }
              })()}
            </div>
          </div>

          {/* 차량 정보 */}
          <div className="flex-1">
            {/* 차량명과 가격 */}
            <div className="flex items-start justify-between mb-3">
              <div>
                <h3 className="text-xl font-bold text-gray-900">
                  {vehicle.manufacturer} {vehicle.model}
                </h3>
                <p className="text-sm text-gray-600 mt-1">
                  {vehicle.modelyear}년식 • {vehicle.color} • {vehicle.location}
                </p>
              </div>
              <div className="text-right">
                <div className="text-2xl font-bold text-blue-700 flex items-center space-x-1">
                  <span>{vehicle.price?.toLocaleString()}</span>
                  <span className="text-lg">만원</span>
                </div>
                {vehicle.originprice && vehicle.originprice > vehicle.price && (
                  <div className="text-sm text-gray-500 line-through">
                    {vehicle.originprice.toLocaleString()}만원
                  </div>
                )}
                {vehicle.tcoCost && (
                  <div className="text-xs text-green-600 mt-1">
                    3년 총비용 {vehicle.tcoCost.toLocaleString()}만원
                  </div>
                )}
              </div>
            </div>

            {/* 핵심 스펙 */}
            <div className="grid grid-cols-3 gap-3 mb-3 text-sm">
              <div className="flex items-center space-x-1 text-gray-600">
                <Gauge className="w-4 h-4" />
                <span>{vehicle.distance?.toLocaleString()}km</span>
              </div>
              <div className="flex items-center space-x-1 text-gray-600">
                <Fuel className="w-4 h-4" />
                <span>{vehicle.fueltype}</span>
              </div>
              <div className="flex items-center space-x-1 text-gray-600">
                <MapPin className="w-4 h-4" />
                <span>{vehicle.location}</span>
              </div>
            </div>

            {/* AI 추천 이유 */}
            <div className={`${rankConfig.bgColor} border ${rankConfig.borderColor} rounded-lg p-3 mb-3`}>
              <div className="flex items-start space-x-2">
                <div className="text-lg">🤖</div>
                <div>
                  <p className={`text-sm font-medium ${rankConfig.textColor} mb-1`}>
                    {personaName}님께 {rank}순위로 추천하는 이유
                  </p>
                  <p className="text-sm text-gray-700">
                    {vehicle.recommendationReason}
                  </p>
                </div>
              </div>
            </div>

            {/* 🔥 사용자 리뷰 인사이트 */}
            {vehicle.reviewInsight && (
              <div className="bg-gradient-to-r from-purple-50 to-indigo-50 border border-purple-200 rounded-lg p-3 mb-3">
                <div className="flex items-start space-x-2">
                  <div className="text-lg">💬</div>
                  <div className="flex-1">
                    <div className="flex items-center justify-between mb-1">
                      <p className="text-sm font-medium text-purple-800">
                        실제 사용자 리뷰 기반 인사이트
                      </p>
                      <div className="flex items-center space-x-1">
                        <Star className="w-3 h-3 text-yellow-500 fill-current" />
                        <span className="text-xs text-purple-600 font-medium">
                          {vehicle.reviewInsight.sentimentScore.toFixed(1)}
                        </span>
                      </div>
                    </div>
                    <p className="text-sm text-purple-700 mb-2 font-medium">
                      "{vehicle.reviewInsight.insight}"
                    </p>
                    <div className="flex items-center justify-between text-xs text-purple-600">
                      <span className="flex items-center space-x-1">
                        <Shield className={`w-3 h-3 ${
                          vehicle.reviewInsight.confidence === 'high' ? 'text-green-500' :
                          vehicle.reviewInsight.confidence === 'medium' ? 'text-yellow-500' : 'text-gray-500'
                        }`} />
                        <span>
                          {vehicle.reviewInsight.confidence === 'high' ? '높은 신뢰도' :
                           vehicle.reviewInsight.confidence === 'medium' ? '보통 신뢰도' : '낮은 신뢰도'}
                        </span>
                      </span>
                      <span>{vehicle.reviewInsight.sourceReviewCount.toLocaleString()}개 리뷰 기반</span>
                    </div>
                  </div>
                </div>
              </div>
            )}

            {/* 액션 버튼들 */}
            <div className="flex gap-2">
              {vehicle.detailurl && (
                <button
                  onClick={handleDetailClick}
                  className="flex-1 px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 transition-colors text-sm font-medium flex items-center justify-center space-x-1"
                >
                  <ExternalLink className="w-4 h-4" />
                  <span>실제매물 보기</span>
                </button>
              )}
              <button
                onClick={() => setShowDetails(!showDetails)}
                className="px-4 py-2 text-blue-600 border border-blue-600 rounded-lg hover:bg-blue-50 transition-colors text-sm font-medium flex items-center space-x-1"
              >
                <Eye className="w-4 h-4" />
                <span>{showDetails ? '접기' : '상세보기'}</span>
              </button>
            </div>
          </div>
        </div>

        {/* 상세 정보 토글 */}
        {showDetails && (
          <div className="mt-5 pt-5 border-t border-gray-200 animate-in slide-in-from-top-4 fade-in-0 duration-300">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              {/* 장점 */}
              <div>
                <h5 className="font-semibold text-gray-800 mb-3 flex items-center space-x-2">
                  <ThumbsUp className="w-4 h-4 text-green-600" />
                  <span>주요 장점</span>
                </h5>
                <ul className="text-sm text-gray-600 space-y-2">
                  {vehicle.pros.slice(0, 3).map((pro, idx) => (
                    <li key={idx} className="flex items-start space-x-2">
                      <span className="text-green-500 mt-1 text-xs">✓</span>
                      <span>{pro}</span>
                    </li>
                  ))}
                </ul>
              </div>

              {/* 고려사항 */}
              <div>
                <h5 className="font-semibold text-gray-800 mb-3 flex items-center space-x-2">
                  <ThumbsDown className="w-4 h-4 text-orange-600" />
                  <span>고려사항</span>
                </h5>
                <ul className="text-sm text-gray-600 space-y-2">
                  {vehicle.cons.slice(0, 3).map((con, idx) => (
                    <li key={idx} className="flex items-start space-x-2">
                      <span className="text-orange-500 mt-1 text-xs">!</span>
                      <span>{con}</span>
                    </li>
                  ))}
                </ul>
              </div>
            </div>

            {/* 통계 정보 */}
            {vehicle.statisticalInsight && (
              <div className="mt-6 grid grid-cols-2 md:grid-cols-4 gap-3">
                <div className="text-center p-3 bg-gray-50 rounded-lg">
                  <div className="text-xs font-medium text-gray-600 mb-1">시장포지션</div>
                  <div className={`text-sm font-bold ${
                    vehicle.statisticalInsight.marketPosition === 'undervalued' ? 'text-green-600' :
                    vehicle.statisticalInsight.marketPosition === 'fair' ? 'text-blue-600' : 'text-red-600'
                  }`}>
                    {vehicle.statisticalInsight.marketPosition === 'undervalued' ? '💎 저평가' :
                     vehicle.statisticalInsight.marketPosition === 'fair' ? '⚖️ 적정가' : '⚠️ 고평가'}
                  </div>
                </div>

                <div className="text-center p-3 bg-gray-50 rounded-lg">
                  <div className="text-xs font-medium text-gray-600 mb-1">신뢰성</div>
                  <div className={`text-sm font-bold ${
                    vehicle.statisticalInsight.reliabilityRank === 'excellent' ? 'text-green-600' :
                    vehicle.statisticalInsight.reliabilityRank === 'good' ? 'text-blue-600' : 'text-yellow-600'
                  }`}>
                    {vehicle.statisticalInsight.reliabilityRank === 'excellent' ? '⭐ 최우수' :
                     vehicle.statisticalInsight.reliabilityRank === 'good' ? '👍 우수' : '📊 보통'}
                  </div>
                </div>

                <div className="text-center p-3 bg-gray-50 rounded-lg">
                  <div className="text-xs font-medium text-gray-600 mb-1">연비등급</div>
                  <div className={`text-sm font-bold ${
                    vehicle.statisticalInsight.fuelEconomyRank === 'excellent' ? 'text-green-600' :
                    vehicle.statisticalInsight.fuelEconomyRank === 'good' ? 'text-blue-600' : 'text-yellow-600'
                  }`}>
                    {vehicle.statisticalInsight.fuelEconomyRank === 'excellent' ? '⛽ 최우수' :
                     vehicle.statisticalInsight.fuelEconomyRank === 'good' ? '🚗 우수' : '📊 보통'}
                  </div>
                </div>

                <div className="text-center p-3 bg-gray-50 rounded-lg">
                  <div className="text-xs font-medium text-gray-600 mb-1">비용등급</div>
                  <div className={`text-sm font-bold ${
                    vehicle.statisticalInsight.totalCostRank === 'budget' ? 'text-green-600' :
                    vehicle.statisticalInsight.totalCostRank === 'mid-range' ? 'text-blue-600' : 'text-purple-600'
                  }`}>
                    {vehicle.statisticalInsight.totalCostRank === 'budget' ? '💰 경제형' :
                     vehicle.statisticalInsight.totalCostRank === 'mid-range' ? '🎯 중급형' : '👑 프리미엄'}
                  </div>
                </div>
              </div>
            )}
          </div>
        )}
      </div>

      {/* 하단 정보 */}
      <div className="bg-gray-50 px-5 py-3 border-t border-gray-200">
        <div className="flex items-center justify-between text-xs text-gray-600">
          <div className="flex items-center space-x-3">
            <div className="flex items-center space-x-1">
              <Shield className="w-3 h-3 text-blue-600" />
              <span className="font-medium">실제 {getPlatformName(vehicle.platform || 'encar')} 매물</span>
            </div>
            {vehicle.platform && (
              <div className="flex items-center space-x-1">
                <div className="w-1.5 h-1.5 bg-green-500 rounded-full animate-pulse"></div>
                <span className="text-green-700 font-medium">실시간 연동</span>
              </div>
            )}
          </div>
          <div className="flex items-center space-x-2">
            <span>AI 분석 완료</span>
            <div className="w-1 h-1 bg-gray-400 rounded-full"></div>
            <span className="font-medium text-blue-600">적합도 {vehicle.suitabilityScore}점</span>
          </div>
        </div>
      </div>
    </div>
  );
}

'use client';

import React, { useState } from 'react';
import { Car, Calendar, Gauge, MapPin, DollarSign, Star, ExternalLink, Award, Fuel, Shield } from 'lucide-react';

interface VehicleData {
  vehicle_id?: number;
  manufacturer: string;
  model: string;
  modelyear?: number;
  model_year?: number; // 데이터베이스 컬럼명
  price: number;
  distance: number;
  location: string;
  fueltype?: string;
  fuel_type?: string; // 데이터베이스 컬럼명
  car_type?: string;
  transmission?: string;
  trim?: string;
  color_name?: string; // 차량 색상
  rank: number;
  suitabilityScore?: number;
  detailurl?: string;
  detail_url?: string; // 데이터베이스 컬럼명
  platform?: string;
  photo?: string;
  origin_price?: number;
  sell_type?: string;
}

interface EnhancedVehicleCardProps {
  vehicle: VehicleData;
  onClick?: () => void;
  className?: string;
}

export default function EnhancedVehicleCard({ vehicle, onClick, className = '' }: EnhancedVehicleCardProps) {
  const [imageError, setImageError] = useState(false);

  const getRankIcon = (rank: number) => {
    switch (rank) {
      case 1: return { icon: '🥇', color: 'from-yellow-400 to-amber-500', text: '최고 추천' };
      case 2: return { icon: '🥈', color: 'from-gray-300 to-gray-400', text: '우수 추천' };
      case 3: return { icon: '🥉', color: 'from-orange-400 to-orange-500', text: '좋은 선택' };
      default: return { icon: '⭐', color: 'from-blue-400 to-blue-500', text: '추천' };
    }
  };

  const getPlatformName = (platform?: string) => {
    switch (platform) {
      case 'encar': return '엔카';
      case 'kbchachacha': return 'KB차차차';
      default: return '중고차 플랫폼';
    }
  };

  const rankInfo = getRankIcon(vehicle.rank);

  // 브랜드별 컬러 테마
  const getBrandTheme = (manufacturer: string) => {
    const themes: Record<string, { primary: string; secondary: string; accent: string }> = {
      '현대': { primary: 'from-blue-500 to-blue-600', secondary: 'bg-blue-50', accent: 'text-blue-700' },
      '기아': { primary: 'from-red-500 to-red-600', secondary: 'bg-red-50', accent: 'text-red-700' },
      '제네시스': { primary: 'from-gray-800 to-black', secondary: 'bg-gray-100', accent: 'text-gray-800' },
      'BMW': { primary: 'from-blue-400 to-blue-500', secondary: 'bg-blue-50', accent: 'text-blue-600' },
      '벤츠': { primary: 'from-gray-600 to-gray-700', secondary: 'bg-gray-50', accent: 'text-gray-700' },
      '아우디': { primary: 'from-red-600 to-red-700', secondary: 'bg-red-50', accent: 'text-red-700' },
      '폭스바겐': { primary: 'from-blue-600 to-blue-700', secondary: 'bg-blue-50', accent: 'text-blue-700' },
      '토요타': { primary: 'from-red-500 to-red-600', secondary: 'bg-red-50', accent: 'text-red-700' },
      '렉서스': { primary: 'from-gray-700 to-gray-800', secondary: 'bg-gray-50', accent: 'text-gray-800' },
      default: { primary: 'from-gray-500 to-gray-600', secondary: 'bg-gray-50', accent: 'text-gray-700' }
    };

    return themes[manufacturer] || themes.default;
  };

  const brandTheme = getBrandTheme(vehicle.manufacturer);

  // 필드 값 정규화 함수들
  const getModelYear = () => vehicle.model_year || vehicle.modelyear;
  const getFuelType = () => vehicle.fuel_type || vehicle.fueltype;
  const getDetailUrl = () => vehicle.detail_url || vehicle.detailurl;

  // 이미지 로딩 핸들러
  const handleImageLoad = () => setImageError(false);
  const handleImageError = () => setImageError(true);

  const generateVehicleVisualization = () => {
    // 차량 종류에 따른 SVG 아이콘 생성
    const isSUV = vehicle.model.toLowerCase().includes('suv') ||
                  vehicle.model.includes('토스') || vehicle.model.includes('싼타') ||
                  vehicle.model.includes('셀토스') || vehicle.model.includes('스포');

    const isSedan = vehicle.model.includes('그랜저') || vehicle.model.includes('소나타') ||
                    vehicle.model.includes('아반떼') || vehicle.model.includes('K5') ||
                    vehicle.model.includes('K7') || vehicle.model.includes('K9');

    const carType = isSUV ? 'SUV' : isSedan ? 'Sedan' : 'Car';

    return (
      <div className={`relative p-6 rounded-xl ${brandTheme.secondary} border-2 border-gray-200 bg-gradient-to-br from-white to-gray-50`}>
        {/* 순위 배지 */}
        <div className={`absolute -top-2 -right-2 bg-gradient-to-r ${rankInfo.color} text-white px-3 py-1 rounded-full text-sm font-bold shadow-lg`}>
          {rankInfo.icon} #{vehicle.rank}
        </div>

        {/* 실제 차량 이미지 또는 아이콘 */}
        <div className="flex items-center justify-center mb-4">
          {vehicle.photo && !imageError ? (
            <div className="relative w-24 h-16 rounded-lg overflow-hidden border-2 border-gray-200">
              <img
                src={vehicle.photo}
                alt={`${vehicle.manufacturer} ${vehicle.model}`}
                className="w-full h-full object-cover"
                onLoad={handleImageLoad}
                onError={handleImageError}
              />
            </div>
          ) : (
            <div className={`p-4 rounded-full bg-gradient-to-r ${brandTheme.primary} text-white shadow-lg`}>
              <Car className="w-8 h-8" />
            </div>
          )}
        </div>

        {/* 차량 정보 */}
        <div className="text-center mb-4">
          <div className={`text-sm font-medium ${brandTheme.accent} mb-1`}>{vehicle.manufacturer}</div>
          <h3 className="text-lg font-bold text-gray-900 leading-tight">{vehicle.model}</h3>
          <div className="text-sm text-gray-600">
            {getModelYear() && `${getModelYear()}년식`}
            {getModelYear() && getFuelType() && ' • '}
            {getFuelType()}
            {vehicle.color_name && ` • ${vehicle.color_name}`}
          </div>
          {vehicle.trim && (
            <div className="text-xs text-gray-500 mt-1">{vehicle.trim}</div>
          )}
        </div>

        {/* 주요 정보 그리드 */}
        <div className="grid grid-cols-2 gap-3 mb-4">
          <div className="text-center p-2 bg-white rounded-lg border">
            <DollarSign className="w-4 h-4 mx-auto mb-1 text-green-600" />
            <div className="text-xs text-gray-600">가격</div>
            <div className="font-bold text-green-700">{vehicle.price?.toLocaleString()}만원</div>
          </div>
          <div className="text-center p-2 bg-white rounded-lg border">
            <Gauge className="w-4 h-4 mx-auto mb-1 text-blue-600" />
            <div className="text-xs text-gray-600">주행거리</div>
            <div className="font-bold text-blue-700">{vehicle.distance?.toLocaleString()}km</div>
          </div>
        </div>

        {/* 적합도 점수 */}
        {vehicle.suitabilityScore && (
          <div className="bg-gradient-to-r from-purple-50 to-pink-50 p-3 rounded-lg border border-purple-200 mb-4">
            <div className="flex items-center justify-center space-x-2">
              <Star className="w-5 h-5 text-yellow-500 fill-current" />
              <span className="font-bold text-purple-700">AI 적합도</span>
              <span className="text-2xl font-bold text-purple-800">{vehicle.suitabilityScore}</span>
              <span className="text-purple-600">/100</span>
            </div>
          </div>
        )}

        {/* 추가 정보 */}
        <div className="space-y-2 text-sm">
          <div className="flex items-center space-x-2 text-gray-600">
            <MapPin className="w-4 h-4" />
            <span>{vehicle.location}</span>
          </div>
          <div className="flex items-center space-x-2 text-gray-600">
            <Award className="w-4 h-4" />
            <span>{getPlatformName(vehicle.platform)} 매물</span>
          </div>
        </div>

        {/* 액션 버튼들 */}
        <div className="mt-4 space-y-2">
          <button
            onClick={onClick}
            className={`w-full py-2 px-4 bg-gradient-to-r ${brandTheme.primary} text-white rounded-lg hover:opacity-90 transition-all font-medium`}
          >
            상세 분석 보기
          </button>

          {getDetailUrl() && (
            <a
              href={getDetailUrl()}
              target="_blank"
              rel="noopener noreferrer"
              className="w-full py-2 px-4 border border-gray-300 text-gray-700 rounded-lg hover:bg-gray-50 transition-colors font-medium flex items-center justify-center space-x-2"
            >
              <ExternalLink className="w-4 h-4" />
              <span>실제 매물 보기</span>
            </a>
          )}
        </div>

        {/* 추천 이유 미리보기 */}
        <div className="mt-4 p-3 bg-blue-50 rounded-lg border border-blue-200">
          <div className="text-xs text-blue-700 mb-1">🤖 AI 추천 이유</div>
          <div className="text-sm text-blue-800">
            {vehicle.rank === 1 && "가격, 성능, 브랜드 신뢰도 모든 면에서 최적의 선택입니다."}
            {vehicle.rank === 2 && "전체적으로 균형잡힌 훌륭한 옵션이며 높은 만족도를 보장합니다."}
            {vehicle.rank === 3 && "가성비가 뛰어나며 실용적인 선택으로 추천드립니다."}
            {vehicle.rank > 3 && "고려해볼 만한 좋은 조건의 차량입니다."}
          </div>
        </div>
      </div>
    );
  };

  return (
    <div className={`snap-center flex-shrink-0 w-80 ${className}`}>
      {generateVehicleVisualization()}
    </div>
  );
}

'use client';

import { useState, useEffect } from 'react';
import { AlertTriangle, RefreshCw, Home, MessageCircle } from 'lucide-react';

interface ErrorBoundaryProps {
  error?: Error | null;
  onRetry?: () => void;
  onGoHome?: () => void;
  showContactSupport?: boolean;
}

export default function ErrorBoundary({
  error,
  onRetry,
  onGoHome,
  showContactSupport = true
}: ErrorBoundaryProps) {
  const [isRetrying, setIsRetrying] = useState(false);

  const handleRetry = async () => {
    if (onRetry) {
      setIsRetrying(true);
      try {
        await onRetry();
      } catch (err) {
        console.error('Retry failed:', err);
      } finally {
        setTimeout(() => setIsRetrying(false), 1000);
      }
    }
  };

  const getErrorMessage = () => {
    if (!error) return "알 수 없는 오류가 발생했습니다.";

    const message = error.message.toLowerCase();

    if (message.includes('network') || message.includes('fetch')) {
      return "인터넷 연결을 확인해주세요. 네트워크 연결에 문제가 있는 것 같습니다.";
    }

    if (message.includes('timeout')) {
      return "요청 시간이 초과되었습니다. 잠시 후 다시 시도해주세요.";
    }

    if (message.includes('server') || message.includes('500')) {
      return "서버에 일시적인 문제가 발생했습니다. 잠시 후 다시 시도해주세요.";
    }

    if (message.includes('not found') || message.includes('404')) {
      return "요청하신 페이지를 찾을 수 없습니다.";
    }

    return "시스템에 문제가 발생했습니다. 잠시 후 다시 시도해주세요.";
  };

  const getErrorSuggestions = () => {
    if (!error) return [];

    const message = error.message.toLowerCase();
    const suggestions = [];

    if (message.includes('network') || message.includes('fetch')) {
      suggestions.push("Wi-Fi 또는 모바일 데이터 연결을 확인해보세요");
      suggestions.push("브라우저를 새로고침해보세요");
    } else if (message.includes('timeout')) {
      suggestions.push("인터넷 연결이 느릴 수 있습니다");
      suggestions.push("잠시 후 다시 시도해보세요");
    } else {
      suggestions.push("페이지를 새로고침해보세요");
      suggestions.push("잠시 후 다시 시도해보세요");
    }

    return suggestions;
  };

  return (
    <div className="min-h-[400px] flex items-center justify-center p-6">
      <div className="max-w-md w-full bg-white rounded-xl shadow-lg border border-gray-200 p-8 text-center">
        {/* Error Icon */}
        <div className="mx-auto w-16 h-16 bg-red-100 rounded-full flex items-center justify-center mb-6">
          <AlertTriangle className="w-8 h-8 text-red-600" />
        </div>

        {/* Error Title */}
        <h2 className="text-xl font-bold text-gray-900 mb-3">
          문제가 발생했습니다
        </h2>

        {/* Error Message */}
        <p className="text-gray-600 mb-6 leading-relaxed">
          {getErrorMessage()}
        </p>

        {/* Error Suggestions */}
        {getErrorSuggestions().length > 0 && (
          <div className="bg-blue-50 rounded-lg p-4 mb-6 text-left">
            <h3 className="text-sm font-medium text-blue-900 mb-2">해결 방법:</h3>
            <ul className="text-sm text-blue-800 space-y-1">
              {getErrorSuggestions().map((suggestion, index) => (
                <li key={index} className="flex items-start">
                  <span className="mr-2">•</span>
                  <span>{suggestion}</span>
                </li>
              ))}
            </ul>
          </div>
        )}

        {/* Action Buttons */}
        <div className="space-y-3">
          {onRetry && (
            <button
              onClick={handleRetry}
              disabled={isRetrying}
              className="w-full flex items-center justify-center space-x-2 px-6 py-3 bg-blue-500 text-white rounded-lg hover:bg-blue-600 disabled:bg-blue-300 disabled:cursor-not-allowed transition-all duration-200"
              aria-label="다시 시도하기"
            >
              <RefreshCw className={`w-4 h-4 ${isRetrying ? 'animate-spin' : ''}`} />
              <span>{isRetrying ? '재시도 중...' : '다시 시도'}</span>
            </button>
          )}

          {onGoHome && (
            <button
              onClick={onGoHome}
              className="w-full flex items-center justify-center space-x-2 px-6 py-3 bg-gray-100 text-gray-700 rounded-lg hover:bg-gray-200 transition-colors duration-200"
              aria-label="홈으로 돌아가기"
            >
              <Home className="w-4 h-4" />
              <span>홈으로 돌아가기</span>
            </button>
          )}

          {showContactSupport && (
            <button
              onClick={() => {
                // 실제로는 고객 지원 채널로 연결
                window.location.href = 'mailto:support@carfin.ai?subject=CarFin AI 오류 신고';
              }}
              className="w-full flex items-center justify-center space-x-2 px-6 py-3 text-gray-500 hover:text-gray-700 transition-colors duration-200"
              aria-label="고객 지원 문의하기"
            >
              <MessageCircle className="w-4 h-4" />
              <span className="text-sm">문제가 계속되면 문의해주세요</span>
            </button>
          )}
        </div>

        {/* Technical Details (for development) */}
        {process.env.NODE_ENV === 'development' && error && (
          <details className="mt-6 text-left">
            <summary className="text-xs text-gray-400 cursor-pointer hover:text-gray-600">
              기술적 세부 정보 (개발용)
            </summary>
            <div className="mt-2 p-3 bg-gray-100 rounded text-xs text-gray-600 font-mono whitespace-pre-wrap break-all">
              {error.stack || error.message}
            </div>
          </details>
        )}
      </div>
    </div>
  );
}

// 빠른 사용을 위한 특정 에러 컴포넌트들
export const NetworkError = ({ onRetry }: { onRetry?: () => void }) => (
  <ErrorBoundary
    error={new Error('Network error')}
    onRetry={onRetry}
  />
);

export const ServerError = ({ onRetry }: { onRetry?: () => void }) => (
  <ErrorBoundary
    error={new Error('Server error')}
    onRetry={onRetry}
  />
);

export const NotFoundError = ({ onGoHome }: { onGoHome?: () => void }) => (
  <ErrorBoundary
    error={new Error('Not found')}
    onGoHome={onGoHome}
    showContactSupport={false}
  />
);

'use client';

import { useState, useEffect } from 'react';
import { Brain, Lightbulb, Search, CheckCircle, Clock, MessageSquare, Car, Users } from 'lucide-react';

interface ThinkingStep {
  id: string;
  type: 'analysis' | 'search' | 'reasoning' | 'decision' | 'collaboration';
  content: string;
  status: 'pending' | 'in_progress' | 'completed';
  timestamp: Date;
  details?: string;
  agent?: 'concierge' | 'needs_analyst' | 'data_analyst' | 'system';
}

interface GPTThinkingUIProps {
  isVisible: boolean;
  currentMessage?: string;
  isProcessing: boolean;
  agentCollaboration?: {
    currentAgent?: string;
    step?: string;
    progress?: number;
  };
}

export default function GPTThinkingUI({
  isVisible,
  currentMessage,
  isProcessing,
  agentCollaboration
}: GPTThinkingUIProps) {
  const [thinkingSteps, setThinkingSteps] = useState<ThinkingStep[]>([]);
  const [currentStepIndex, setCurrentStepIndex] = useState(0);

  // 실제 AI 협업 과정을 시뮬레이션하는 단계들
  const generateThinkingSteps = (message: string): ThinkingStep[] => {
    const now = new Date();

    return [
      {
        id: '1',
        type: 'analysis',
        content: '사용자의 질문을 분석하고 숨겨진 니즈를 파악합니다',
        status: 'pending',
        timestamp: now,
        details: `"${message?.substring(0, 50)}..." 에서 핵심 요구사항 추출 중`,
        agent: 'needs_analyst'
      },
      {
        id: '2',
        type: 'collaboration',
        content: '3명의 전문가 에이전트 간 협업 패턴을 결정합니다',
        status: 'pending',
        timestamp: new Date(now.getTime() + 1000),
        details: '컨시어지 → 니즈분석 → 데이터분석 순서로 A2A 협업 시작',
        agent: 'system'
      },
      {
        id: '3',
        type: 'search',
        content: '실시간 데이터베이스에서 관련 차량 정보를 검색합니다',
        status: 'pending',
        timestamp: new Date(now.getTime() + 2000),
        details: '117,564대 실제 매물에서 조건에 맞는 차량 필터링 중',
        agent: 'data_analyst'
      },
      {
        id: '4',
        type: 'reasoning',
        content: '각 에이전트의 전문성을 바탕으로 심층 분석을 수행합니다',
        status: 'pending',
        timestamp: new Date(now.getTime() + 3000),
        details: '니즈 매칭도, TCO 분석, 가성비 평가 등 다각도 검토',
        agent: 'concierge'
      },
      {
        id: '5',
        type: 'decision',
        content: '최종 추천 결과를 종합하고 응답을 생성합니다',
        status: 'pending',
        timestamp: new Date(now.getTime() + 4000),
        details: '3개 에이전트의 분석 결과를 통합하여 최적 솔루션 도출',
        agent: 'system'
      }
    ];
  };

  // 메시지가 변경될 때 새로운 thinking 프로세스 시작
  useEffect(() => {
    if (currentMessage && isProcessing) {
      const steps = generateThinkingSteps(currentMessage);
      setThinkingSteps(steps);
      setCurrentStepIndex(0);
    }
  }, [currentMessage, isProcessing]);

  // 단계별 진행 시뮬레이션
  useEffect(() => {
    if (!isProcessing || thinkingSteps.length === 0) return;

    const interval = setInterval(() => {
      setThinkingSteps(prev => {
        const updated = [...prev];
        const currentStep = updated[currentStepIndex];

        if (currentStep && currentStep.status === 'pending') {
          currentStep.status = 'in_progress';
          return updated;
        }

        if (currentStep && currentStep.status === 'in_progress') {
          currentStep.status = 'completed';
          if (currentStepIndex < thinkingSteps.length - 1) {
            setCurrentStepIndex(prev => prev + 1);
          }
          return updated;
        }

        return prev;
      });
    }, 1500); // 1.5초마다 다음 단계로

    return () => clearInterval(interval);
  }, [isProcessing, currentStepIndex, thinkingSteps.length]);

  // 에이전트별 아이콘 및 색상
  const getAgentInfo = (agent?: string) => {
    switch (agent) {
      case 'concierge':
        return { icon: Users, color: 'blue', name: '컨시어지 매니저' };
      case 'needs_analyst':
        return { icon: Brain, color: 'purple', name: '니즈 분석 전문가' };
      case 'data_analyst':
        return { icon: Search, color: 'green', name: '데이터 분석 전문가' };
      default:
        return { icon: MessageSquare, color: 'gray', name: 'AI 시스템' };
    }
  };

  // 상태별 아이콘
  const getStatusIcon = (status: string) => {
    switch (status) {
      case 'completed':
        return <CheckCircle className="w-4 h-4 text-green-500" />;
      case 'in_progress':
        return <Clock className="w-4 h-4 text-blue-500 animate-spin" />;
      default:
        return <div className="w-4 h-4 rounded-full border-2 border-gray-300" />;
    }
  };

  if (!isVisible) return null;

  return (
    <div className="bg-gradient-to-br from-slate-50 to-blue-50 border border-slate-200 rounded-xl p-6 mb-4 shadow-sm">
      {/* 헤더 */}
      <div className="flex items-center gap-3 mb-6">
        <div className="flex items-center justify-center w-10 h-10 bg-gradient-to-br from-blue-500 to-purple-600 rounded-lg">
          <Brain className="w-5 h-5 text-white" />
        </div>
        <div>
          <h3 className="text-lg font-bold text-slate-800">🧠 GPT Thinking Process</h3>
          <p className="text-sm text-slate-600">
            AI 에이전트들의 실시간 협업 과정을 보여드려요
          </p>
        </div>
        {isProcessing && (
          <div className="ml-auto">
            <div className="flex items-center gap-2 px-3 py-1 bg-blue-100 text-blue-700 rounded-full text-sm font-medium">
              <div className="w-2 h-2 bg-blue-500 rounded-full animate-pulse"></div>
              처리 중...
            </div>
          </div>
        )}
      </div>

      {/* 현재 에이전트 협업 상태 */}
      {agentCollaboration?.currentAgent && (
        <div className="bg-white rounded-lg p-4 mb-4 border border-slate-200">
          <div className="flex items-center gap-3 mb-2">
            <div className="w-8 h-8 bg-gradient-to-br from-orange-400 to-red-500 rounded-lg flex items-center justify-center">
              <Car className="w-4 h-4 text-white" />
            </div>
            <div>
              <div className="text-sm font-semibold text-slate-800">현재 협업 단계</div>
              <div className="text-sm text-slate-600">
                {agentCollaboration.currentAgent} • {agentCollaboration.step}
              </div>
            </div>
          </div>
          {agentCollaboration.progress && (
            <div className="w-full bg-gray-200 rounded-full h-2">
              <div
                className="bg-gradient-to-r from-blue-500 to-purple-500 h-2 rounded-full transition-all duration-300"
                style={{ width: `${agentCollaboration.progress}%` }}
              ></div>
            </div>
          )}
        </div>
      )}

      {/* 생각 과정 단계들 */}
      <div className="space-y-4">
        {thinkingSteps.map((step, index) => {
          const agentInfo = getAgentInfo(step.agent);
          const AgentIcon = agentInfo.icon;

          return (
            <div
              key={step.id}
              className={`relative flex gap-4 p-4 rounded-lg border transition-all duration-300 ${
                step.status === 'completed'
                  ? 'bg-green-50 border-green-200'
                  : step.status === 'in_progress'
                  ? 'bg-blue-50 border-blue-200 shadow-sm'
                  : 'bg-gray-50 border-gray-200'
              }`}
            >
              {/* 연결선 */}
              {index < thinkingSteps.length - 1 && (
                <div className="absolute left-6 top-12 w-0.5 h-8 bg-gray-300"></div>
              )}

              {/* 상태 아이콘 */}
              <div className="flex-shrink-0 mt-1">
                {getStatusIcon(step.status)}
              </div>

              {/* 내용 */}
              <div className="flex-1 min-w-0">
                <div className="flex items-center gap-2 mb-2">
                  <div className={`w-6 h-6 bg-${agentInfo.color}-100 rounded-lg flex items-center justify-center`}>
                    <AgentIcon className={`w-3 h-3 text-${agentInfo.color}-600`} />
                  </div>
                  <span className={`text-xs font-medium text-${agentInfo.color}-700 uppercase tracking-wide`}>
                    {agentInfo.name}
                  </span>
                  <span className="text-xs text-gray-500">
                    {step.timestamp.toLocaleTimeString('ko-KR', {
                      hour: '2-digit',
                      minute: '2-digit',
                      second: '2-digit'
                    })}
                  </span>
                </div>

                <div className="text-sm font-medium text-slate-800 mb-1">
                  {step.content}
                </div>

                {step.details && (
                  <div className="text-xs text-slate-600 bg-white p-2 rounded border border-slate-200">
                    💭 {step.details}
                  </div>
                )}

                {/* 진행 중일 때 추가 효과 */}
                {step.status === 'in_progress' && (
                  <div className="mt-2 flex items-center gap-2 text-xs text-blue-600">
                    <div className="flex gap-1">
                      <div className="w-1 h-1 bg-blue-500 rounded-full animate-bounce" style={{ animationDelay: '0ms' }}></div>
                      <div className="w-1 h-1 bg-blue-500 rounded-full animate-bounce" style={{ animationDelay: '150ms' }}></div>
                      <div className="w-1 h-1 bg-blue-500 rounded-full animate-bounce" style={{ animationDelay: '300ms' }}></div>
                    </div>
                    <span>처리 중...</span>
                  </div>
                )}
              </div>
            </div>
          );
        })}
      </div>

      {/* 요약 정보 */}
      {isProcessing && (
        <div className="mt-6 p-4 bg-gradient-to-r from-blue-50 to-purple-50 rounded-lg border border-blue-200">
          <div className="flex items-center gap-2 text-sm text-slate-700">
            <Lightbulb className="w-4 h-4 text-yellow-500" />
            <span className="font-medium">실시간 AI 협업:</span>
            <span>3개 전문 에이전트가 117,564대 실제 매물을 분석하여 최적의 답변을 준비 중입니다</span>
          </div>
        </div>
      )}
    </div>
  );
}

// HorizontalVehicleCard.tsx - 가로형 차량 추천 카드

import React, { useState, useEffect } from 'react';
import Image from 'next/image';
import { Car, DollarSign, Gauge, Calendar, MapPin, Fuel, Shield, Star, ThumbsUp, ThumbsDown, ExternalLink } from 'lucide-react';

interface VehicleRecommendation {
  manufacturer: string;
  model: string;
  modelyear: number;
  price: number;
  distance: number;
  location: string;
  fueltype: string;
  displacement?: number;
  color?: string;
  // 실제 매물 정보
  detailurl?: string;
  photo?: string;
  platform?: string;
  originprice?: number;
  // AI 분석 결과
  recommendationReason: string;
  pros: string[];
  cons: string[];
  suitabilityScore: number;
  tcoCost?: number;
  tcoBreakdown?: {
    initialCost: number;
    depreciationCost: number;
    maintenanceCost: number;
    fuelCost: number;
    insuranceCost: number;
    totalTCO: number;
    monthlyAverage: number;
    costPerKm: number;
  };
  statisticalInsight?: {
    depreciationTrend: 'stable' | 'declining' | 'volatile';
    marketPosition: 'undervalued' | 'fair' | 'overvalued';
    reliabilityRank: 'excellent' | 'good' | 'average' | 'below_average';
    fuelEconomyRank: 'excellent' | 'good' | 'average' | 'poor';
    totalCostRank: 'budget' | 'mid-range' | 'premium' | 'luxury';
  };
  imageUrl?: string;
  rank: number;
}

interface HorizontalVehicleCardProps {
  vehicle: VehicleRecommendation;
  personaName?: string;
  rank: number;
}

export default function HorizontalVehicleCard({ vehicle, personaName, rank }: HorizontalVehicleCardProps) {
  const [showDetails, setShowDetails] = useState(false);
  const [imageError, setImageError] = useState(false);
  const [realVehicleImage, setRealVehicleImage] = useState<string | null>(null);
  const [imageLoading, setImageLoading] = useState(false);

  const getRankColor = (rank: number) => {
    switch (rank) {
      case 1: return 'from-yellow-400 to-orange-500';
      case 2: return 'from-gray-400 to-gray-600';
      case 3: return 'from-orange-600 to-red-500';
      default: return 'from-blue-400 to-blue-600';
    }
  };

  const getRankIcon = (rank: number) => {
    switch (rank) {
      case 1: return '🥇';
      case 2: return '🥈';
      case 3: return '🥉';
      default: return '⭐';
    }
  };

  const getPlatformName = (platform: string) => {
    switch (platform) {
      case 'encar': return '엔카';
      case 'kbchachacha': return 'KB차차차';
      default: return platform;
    }
  };

  // 실제 엔카 매물 이미지를 가져오는 함수
  const fetchRealVehicleImage = async (detailUrl: string) => {
    if (!detailUrl) return null;

    try {
      setImageLoading(true);
      console.log('🔍 차량 이미지 크롤링 시작:', detailUrl);

      const response = await fetch(`/api/get-vehicle-image?detailUrl=${encodeURIComponent(detailUrl)}`);
      const data = await response.json();

      if (data.success && data.primaryImage) {
        console.log('✅ 실제 매물 이미지 발견:', data.primaryImage);
        return data.primaryImage;
      } else {
        console.log('❌ 실제 매물 이미지 없음:', data.error);
        return null;
      }
    } catch (error) {
      console.error('🚨 이미지 크롤링 실패:', error);
      return null;
    } finally {
      setImageLoading(false);
    }
  };

  // 엔카 이미지 URL 생성 함수
  const buildEncarImageUrl = (photoPath: string) => {
    if (photoPath.startsWith('http')) return photoPath;

    // 엔카 이미지 서버 패턴 매칭
    const encarImageServers = [
      'https://img1.encar.com',
      'https://img2.encar.com',
      'https://img3.encar.com',
      'https://img4.encar.com'
    ];

    // 랜덤 서버 선택 (로드 밸런싱)
    const randomServer = encarImageServers[Math.floor(Math.random() * encarImageServers.length)];

    // 경로 정리
    const cleanPath = photoPath.startsWith('/') ? photoPath : `/${photoPath}`;
    return `${randomServer}${cleanPath}`;
  };

  // 컴포넌트 마운트 시 실제 매물 이미지 가져오기
  useEffect(() => {
    // 1순위: 데이터베이스의 photo 필드 사용 (완전한 URL 또는 경로)
    if (vehicle.photo) {
      const imageUrl = buildEncarImageUrl(vehicle.photo);
      console.log('📸 Using database photo:', imageUrl);
      setRealVehicleImage(imageUrl);
      return;
    }

    // 2순위: detailurl이 있으면 크롤링 시도
    if (vehicle.detailurl && !realVehicleImage) {
      console.log('🔍 Attempting to crawl images from:', vehicle.detailurl);
      fetchRealVehicleImage(vehicle.detailurl).then(imageUrl => {
        if (imageUrl) {
          setRealVehicleImage(imageUrl);
        }
      });
    }
  }, [vehicle.detailurl, vehicle.photo, realVehicleImage]);

  const handleDetailClick = () => {
    if (vehicle.detailurl) {
      window.open(vehicle.detailurl, '_blank');
    }
  };

  return (
    <div className="bg-white rounded-xl border border-gray-200 shadow-md hover:shadow-lg transition-all duration-300 hover:scale-[1.01] overflow-hidden w-full h-fit group">
      {/* 헤더 - 순위와 기본 정보 */}
      <div className={`bg-gradient-to-r ${getRankColor(rank)} p-4 text-white relative overflow-hidden`}>
        {/* 배경 패턴 */}
        <div className="absolute inset-0 bg-white/10 opacity-0 group-hover:opacity-100 transition-opacity duration-300" style={{backgroundImage: 'radial-gradient(circle at 20% 50%, rgba(255,255,255,0.2) 0%, transparent 50%)'}}></div>
        <div className="flex items-center justify-between">
          <div className="flex items-center space-x-3">
            <div className="text-2xl">{getRankIcon(rank)}</div>
            <div>
              <h3 className="text-xl font-bold">
                {vehicle.manufacturer} {vehicle.model}
              </h3>
              <p className="text-sm opacity-90">
                {vehicle.modelyear}년식 • {vehicle.location}
                {vehicle.platform && (
                  <span className="ml-2 px-2 py-1 bg-white/20 rounded-full text-xs">
                    {getPlatformName(vehicle.platform)}
                  </span>
                )}
              </p>
            </div>
          </div>
          <div className="text-right relative z-10">
            <div className="text-2xl font-bold flex items-center justify-end space-x-2">
              <span>{vehicle.price?.toLocaleString()}만원</span>
              {vehicle.originprice && vehicle.originprice > vehicle.price && (
                <span className="text-xs bg-white/20 px-2 py-1 rounded-full">
                  -{Math.round((1 - vehicle.price / vehicle.originprice) * 100)}%
                </span>
              )}
            </div>
            {vehicle.originprice && vehicle.originprice > vehicle.price && (
              <div className="text-sm opacity-75 line-through">
                {vehicle.originprice.toLocaleString()}만원
              </div>
            )}
            <div className="text-sm opacity-90 flex items-center justify-end space-x-1 mt-1">
              <div className="flex items-center space-x-1 bg-white/20 px-2 py-1 rounded-full">
                <Star className="w-3 h-3 fill-current" />
                <span className="font-bold">{vehicle.suitabilityScore}</span>
                <span className="text-xs opacity-75">점</span>
              </div>
            </div>
          </div>
        </div>
      </div>

      {/* 컴팩트 메인 섹션 */}
      <div className="p-4">
        <div className="flex flex-col lg:flex-row gap-4 mb-3">
          {/* 차량 이미지 */}
          <div className="w-full lg:w-64 flex-shrink-0">
            <div className="aspect-video bg-gradient-to-br from-gray-100 to-gray-200 rounded-xl overflow-hidden relative group-hover:shadow-lg transition-shadow duration-300">
              {(() => {
                // 실제 매물 이미지가 있으면 사용, 없으면 로딩 중이거나 플레이스홀더 표시
                if (realVehicleImage && !imageError) {
                  return (
                    <img
                      src={`/api/proxy-image?url=${encodeURIComponent(realVehicleImage)}`}
                      alt={`${vehicle.manufacturer} ${vehicle.model} 실제 매물 사진`}
                      className="w-full h-full object-cover transition-opacity duration-300"
                      onError={() => {
                        console.log('실제 매물 이미지 로딩 실패:', realVehicleImage);
                        // 첫 번째 실패시 직접 URL로 재시도
                        if (!realVehicleImage.includes('proxy-image')) {
                          console.log('🔄 Direct URL 재시도:', realVehicleImage);
                          const img = new (globalThis as any).Image();
                          img.onload = () => {
                            console.log('✅ Direct URL 성공');
                            setRealVehicleImage(realVehicleImage + '?direct=true');
                          };
                          img.onerror = () => {
                            console.log('❌ Direct URL도 실패');
                            setImageError(true);
                          };
                          img.src = realVehicleImage;
                        } else {
                          setImageError(true);
                        }
                      }}
                      onLoad={() => {
                        console.log('✅ 실제 매물 이미지 로딩 성공:', realVehicleImage);
                        setImageLoading(false);
                      }}
                    />
                  );
                } else {
                  return (
                    <div className="w-full h-full flex items-center justify-center text-gray-500">
                      <div className="text-center">
                        {imageLoading ? (
                          <>
                            <div className="w-8 h-8 mx-auto mb-2 border-4 border-blue-200 border-t-blue-600 rounded-full animate-spin"></div>
                            <p className="text-sm">실제 매물 이미지 로딩 중...</p>
                          </>
                        ) : imageError ? (
                          <>
                            <div className="w-16 h-16 mx-auto mb-3 bg-gradient-to-br from-blue-400 to-blue-600 rounded-lg flex items-center justify-center">
                              <Car className="w-8 h-8 text-white" />
                            </div>
                            <p className="text-sm font-medium text-gray-700">{vehicle.manufacturer} {vehicle.model}</p>
                            <p className="text-xs text-gray-500 mt-1">{vehicle.modelyear}년식 • {vehicle.fueltype}</p>
                            <div className="mt-2 px-3 py-1 bg-blue-100 text-blue-700 rounded-full text-xs">
                              {vehicle.platform ? getPlatformName(vehicle.platform) : '엔카'} 실제 매물
                            </div>
                          </>
                        ) : (
                          <>
                            <div className="w-16 h-16 mx-auto mb-3 bg-gradient-to-br from-gray-300 to-gray-500 rounded-lg flex items-center justify-center">
                              <Car className="w-8 h-8 text-white" />
                            </div>
                            <p className="text-sm font-medium text-gray-700">실제 매물 이미지</p>
                            <p className="text-xs text-gray-500 mt-1">
                              {vehicle.platform ? getPlatformName(vehicle.platform) : '엔카'} 제공
                            </p>
                          </>
                        )}
                        {process.env.NODE_ENV === 'development' && (
                          <div className="text-xs text-blue-400 mt-2 space-y-1">
                            <p>매물URL: {vehicle.detailurl ? '✓' : '✗'}</p>
                            <p>DB photo: {vehicle.photo ? '✓' : '✗'}</p>
                            <p>실제이미지: {realVehicleImage ? '✓' : '✗'}</p>
                            <p>로딩상태: {imageLoading ? '로딩중' : '완료'}</p>
                            <p>에러상태: {imageError ? '에러' : '정상'}</p>
                            {vehicle.photo && (
                              <p className="text-xs text-green-400">Photo: {vehicle.photo.substring(0, 50)}...</p>
                            )}
                          </div>
                        )}
                      </div>
                    </div>
                  );
                }
              })()}
            </div>
          </div>

          {/* 핵심 정보 */}
          <div className="flex-1">
            {/* AI 한줄 요약 */}
            <div className="bg-gradient-to-r from-blue-50 to-indigo-50 border border-blue-100 rounded-lg p-3 mb-3">
              <div className="flex items-center space-x-2">
                <div className="text-lg">🤖</div>
                <div className="flex-1">
                  <p className="text-sm font-medium text-blue-800">
                    {personaName ? `${personaName}님께 추천` : 'AI 추천'}
                  </p>
                  <p className="text-xs text-blue-700 mt-1">{vehicle.recommendationReason.slice(0, 60)}...</p>
                </div>
                <div className="text-right">
                  <div className="text-lg font-bold text-blue-700">{vehicle.suitabilityScore}</div>
                  <div className="text-xs text-blue-500">점</div>
                </div>
              </div>
            </div>

            {/* 핵심 스펙 한줄 */}
            <div className="flex items-center justify-between text-sm text-gray-600 mb-3">
              <div className="flex items-center space-x-4">
                <span className="flex items-center space-x-1">
                  <Gauge className="w-3 h-3" />
                  <span>{vehicle.distance?.toLocaleString()}km</span>
                </span>
                <span className="flex items-center space-x-1">
                  <Fuel className="w-3 h-3" />
                  <span>{vehicle.fueltype}</span>
                </span>
                <span className="flex items-center space-x-1">
                  <Calendar className="w-3 h-3" />
                  <span>{vehicle.modelyear}년</span>
                </span>
              </div>
              <span className="flex items-center space-x-1 text-gray-500">
                <MapPin className="w-3 h-3" />
                <span>{vehicle.location}</span>
              </span>
            </div>

            {/* TCO 요약 + 액션 버튼 */}
            <div className="flex items-center justify-between">
              {vehicle.tcoCost && (
                <div className="bg-gradient-to-r from-green-50 to-blue-50 border border-green-100 rounded-lg p-2 flex-1 mr-3">
                  <div className="flex items-center space-x-2">
                    <DollarSign className="w-4 h-4 text-green-600" />
                    <div>
                      <div className="text-sm font-bold text-gray-800">{vehicle.tcoCost.toLocaleString()}만원</div>
                      <div className="text-xs text-gray-600">3년 총 비용</div>
                    </div>
                  </div>
                </div>
              )}
              <div className="flex gap-2">
                {vehicle.detailurl && (
                  <button
                    onClick={handleDetailClick}
                    className="px-3 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 transition-colors text-xs font-medium"
                  >
                    실제매물
                  </button>
                )}
                <button
                  onClick={() => setShowDetails(!showDetails)}
                  className="px-3 py-2 text-blue-600 border border-blue-600 rounded-lg hover:bg-blue-50 transition-colors text-xs font-medium"
                >
                  {showDetails ? '접기' : '더보기'}
                </button>
              </div>
            </div>
          </div>
        </div>

      </div>

      {/* 상세 정보 토글 */}
      {showDetails && (
        <div className="mx-6 mb-6 pt-6 border-t border-gray-200 animate-in slide-in-from-top-4 fade-in-0 duration-300">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
              {/* 전체 장단점 */}
              <div>
                <h5 className="font-semibold text-gray-800 mb-3 flex items-center space-x-2">
                  <ThumbsUp className="w-4 h-4 text-green-600" />
                  <span>상세 장점</span>
                </h5>
                <ul className="text-sm text-gray-600 space-y-2">
                  {vehicle.pros.map((pro, idx) => (
                    <li key={idx} className="flex items-start space-x-2">
                      <span className="text-green-500 mt-1">✓</span>
                      <span className="break-words">{pro}</span>
                    </li>
                  ))}
                </ul>
              </div>

              <div>
                <h5 className="font-semibold text-gray-800 mb-3 flex items-center space-x-2">
                  <ThumbsDown className="w-4 h-4 text-red-600" />
                  <span>고려해야 할 점</span>
                </h5>
                <ul className="text-sm text-gray-600 space-y-2">
                  {vehicle.cons.map((con, idx) => (
                    <li key={idx} className="flex items-start space-x-2">
                      <span className="text-red-500 mt-1">!</span>
                      <span className="break-words">{con}</span>
                    </li>
                  ))}
                </ul>
              </div>
            </div>

            {/* TCO 통계 정보 */}
            {vehicle.tcoBreakdown && vehicle.statisticalInsight && (
              <div className="mt-6 pt-6 border-t border-gray-200">
                <h5 className="font-semibold text-gray-800 mb-4 flex items-center space-x-2">
                  <DollarSign className="w-4 h-4 text-green-600" />
                  <span>📊 통계 기반 TCO 분석</span>
                </h5>

                <div className="grid grid-cols-1 md:grid-cols-3 gap-4 mb-4">
                  {/* 3년 총비용 */}
                  <div className="bg-blue-50 p-3 rounded-lg">
                    <div className="text-xs text-blue-600 font-medium">3년 총 소유비용</div>
                    <div className="text-lg font-bold text-blue-800">
                      {Math.round(vehicle.tcoBreakdown.totalTCO / 10000).toLocaleString()}만원
                    </div>
                    <div className="text-xs text-blue-600">
                      월평균 {Math.round(vehicle.tcoBreakdown.monthlyAverage).toLocaleString()}만원
                    </div>
                  </div>

                  {/* 감가상각 */}
                  <div className="bg-orange-50 p-3 rounded-lg">
                    <div className="text-xs text-orange-600 font-medium">감가상각비</div>
                    <div className="text-lg font-bold text-orange-800">
                      {Math.round(vehicle.tcoBreakdown.depreciationCost / 10000).toLocaleString()}만원
                    </div>
                    <div className="text-xs text-orange-600">
                      {vehicle.statisticalInsight.depreciationTrend === 'stable' ? '📈 안정적' :
                       vehicle.statisticalInsight.depreciationTrend === 'declining' ? '📉 하락세' : '📊 변동성'}
                    </div>
                  </div>

                  {/* 유지비 */}
                  <div className="bg-green-50 p-3 rounded-lg">
                    <div className="text-xs text-green-600 font-medium">유지관리비</div>
                    <div className="text-lg font-bold text-green-800">
                      {Math.round((vehicle.tcoBreakdown.maintenanceCost + vehicle.tcoBreakdown.fuelCost) / 10000).toLocaleString()}만원
                    </div>
                    <div className="text-xs text-green-600">
                      정비비 + 연료비 3년
                    </div>
                  </div>
                </div>

                {/* 통계적 인사이트 */}
                <div className="grid grid-cols-2 md:grid-cols-4 gap-3 text-xs">
                  <div className="text-center p-2 bg-gray-50 rounded">
                    <div className="font-medium text-gray-600">시장 포지션</div>
                    <div className={`font-bold ${
                      vehicle.statisticalInsight.marketPosition === 'undervalued' ? 'text-green-600' :
                      vehicle.statisticalInsight.marketPosition === 'fair' ? 'text-blue-600' : 'text-red-600'
                    }`}>
                      {vehicle.statisticalInsight.marketPosition === 'undervalued' ? '💎 저평가' :
                       vehicle.statisticalInsight.marketPosition === 'fair' ? '⚖️ 적정가' : '⚠️ 고평가'}
                    </div>
                  </div>

                  <div className="text-center p-2 bg-gray-50 rounded">
                    <div className="font-medium text-gray-600">신뢰성</div>
                    <div className={`font-bold ${
                      vehicle.statisticalInsight.reliabilityRank === 'excellent' ? 'text-green-600' :
                      vehicle.statisticalInsight.reliabilityRank === 'good' ? 'text-blue-600' :
                      vehicle.statisticalInsight.reliabilityRank === 'average' ? 'text-yellow-600' : 'text-red-600'
                    }`}>
                      {vehicle.statisticalInsight.reliabilityRank === 'excellent' ? '⭐ 최우수' :
                       vehicle.statisticalInsight.reliabilityRank === 'good' ? '👍 우수' :
                       vehicle.statisticalInsight.reliabilityRank === 'average' ? '📊 보통' : '⚠️ 주의'}
                    </div>
                  </div>

                  <div className="text-center p-2 bg-gray-50 rounded">
                    <div className="font-medium text-gray-600">연비 등급</div>
                    <div className={`font-bold ${
                      vehicle.statisticalInsight.fuelEconomyRank === 'excellent' ? 'text-green-600' :
                      vehicle.statisticalInsight.fuelEconomyRank === 'good' ? 'text-blue-600' :
                      vehicle.statisticalInsight.fuelEconomyRank === 'average' ? 'text-yellow-600' : 'text-red-600'
                    }`}>
                      {vehicle.statisticalInsight.fuelEconomyRank === 'excellent' ? '⛽ 최우수' :
                       vehicle.statisticalInsight.fuelEconomyRank === 'good' ? '🚗 우수' :
                       vehicle.statisticalInsight.fuelEconomyRank === 'average' ? '📊 보통' : '⚠️ 개선'}
                    </div>
                  </div>

                  <div className="text-center p-2 bg-gray-50 rounded">
                    <div className="font-medium text-gray-600">비용 등급</div>
                    <div className={`font-bold ${
                      vehicle.statisticalInsight.totalCostRank === 'budget' ? 'text-green-600' :
                      vehicle.statisticalInsight.totalCostRank === 'mid-range' ? 'text-blue-600' :
                      vehicle.statisticalInsight.totalCostRank === 'premium' ? 'text-purple-600' : 'text-red-600'
                    }`}>
                      {vehicle.statisticalInsight.totalCostRank === 'budget' ? '💰 경제형' :
                       vehicle.statisticalInsight.totalCostRank === 'mid-range' ? '🎯 중급형' :
                       vehicle.statisticalInsight.totalCostRank === 'premium' ? '👑 프리미엄' : '💎 럭셔리'}
                    </div>
                  </div>
                </div>
              </div>
            )}
        </div>
      )}

      {/* 하단 정보 */}
      <div className="bg-gradient-to-r from-gray-50 to-gray-100 px-6 py-4 border-t border-gray-200">
        <div className="flex items-center justify-between text-sm text-gray-600">
          <div className="flex items-center space-x-4">
            <div className="flex items-center space-x-2">
              <div className="p-1 bg-blue-100 rounded">
                <Shield className="w-3 h-3 text-blue-600" />
              </div>
              <span className="font-medium">실제 {getPlatformName(vehicle.platform || '')} 매물 데이터</span>
            </div>
            {vehicle.platform && (
              <div className="flex items-center space-x-2">
                <div className="w-2 h-2 bg-green-500 rounded-full animate-pulse"></div>
                <span className="text-green-700 font-medium">실시간 연동</span>
              </div>
            )}
          </div>
          <div className="text-xs text-gray-500 flex items-center space-x-2">
            <span>AI 분석 완료</span>
            <div className="w-1 h-1 bg-gray-400 rounded-full"></div>
            <span className="font-medium text-blue-600">적합도 {vehicle.suitabilityScore}점</span>
          </div>
        </div>
      </div>
    </div>
  );
}

