 */

import React from 'react';
import { Brain, BarChart3, Users, Sparkles } from 'lucide-react';

interface PaperInsightBadgeProps {
  type: 'MACRec' | 'Alibaba' | 'TOPSIS' | 'Integration';
  insight: string;
  accuracy?: number;
  compact?: boolean;
}

const PaperInsightBadge: React.FC<PaperInsightBadgeProps> = ({
  type,
  insight,
  accuracy,
  compact = false
}) => {
  const configs = {
    MACRec: {
      color: 'bg-blue-50 border-blue-200 text-blue-700',
      icon: <Users className="w-3 h-3" />,
      label: 'MACRec'
    },
    Alibaba: {
      color: 'bg-orange-50 border-orange-200 text-orange-700',
      icon: <Brain className="w-3 h-3" />,
      label: 'Alibaba AI'
    },
