          <div className="text-xs opacity-75 mt-1">신뢰도: {Math.round(accuracy)}%</div>
        )}
      </div>
    </div>
  );
};

export default PaperInsightBadge;

'use client';

import React, { useState, useEffect } from 'react';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Badge } from '@/components/ui/badge';
import { Progress } from '@/components/ui/progress';
import { Button } from '@/components/ui/button';
import {
  User,
  TrendingUp,
  Heart,
  DollarSign,
  Fuel,
  Shield,
  Star,
  Car,
  Gauge,
  Crown,
  ChevronDown,
  ChevronUp,
  RefreshCw,
  Info
} from 'lucide-react';

interface PersonalizationProfileDisplayProps {
  userProfile?: any;
  isLearning?: boolean;
  conversationHistory?: any[];
  onProfileUpdate?: (profile: any) => void;
}

export default function PersonalizationProfileDisplay({
  userProfile,
  isLearning = false,
  conversationHistory = [],
  onProfileUpdate
}: PersonalizationProfileDisplayProps) {
  const [showDetails, setShowDetails] = useState(false);
  const [learningAnimation, setLearningAnimation] = useState(false);

  useEffect(() => {
    if (isLearning) {
      setLearningAnimation(true);
      const timer = setTimeout(() => setLearningAnimation(false), 2000);
      return () => clearTimeout(timer);
    }
  }, [isLearning]);

  if (!userProfile) {
    return (
      <Card className="w-full border-l-4 border-l-purple-500">
        <CardHeader>
          <CardTitle className="text-lg font-bold flex items-center gap-2">
            <User className="w-5 h-5 text-purple-600" />
            개인화 프로필 학습 중...
          </CardTitle>
        </CardHeader>
        <CardContent>
          <div className="flex items-center gap-2">
            <RefreshCw className="w-4 h-4 animate-spin text-purple-600" />
            <span className="text-sm text-gray-600">대화 내용을 분석하여 선호도를 파악하고 있습니다.</span>
          </div>
        </CardContent>
      </Card>
    );
  }

  const preferences = userProfile.preferences || userProfile;
  const confidenceScore = preferences.confidenceScore || 0.5;
  const confidencePercentage = Math.round(confidenceScore * 100);

  const preferenceItems = [
    {
      key: 'price_sensitivity',
      label: '가격 민감도',
      value: preferences.price_sensitivity || 0.5,
      icon: <DollarSign className="w-4 h-4" />,
      color: 'text-green-600',
      description: '저렴한 차량을 선호하는 정도'
    },
    {
      key: 'fuel_efficiency_importance',
      label: '연비 중요도',
      value: preferences.fuel_efficiency_importance || 0.5,
      icon: <Fuel className="w-4 h-4" />,
      color: 'text-blue-600',
      description: '연비가 좋은 차량을 우선시하는 정도'
    },
    {
      key: 'safety_priority',
      label: '안전성 우선순위',
      value: preferences.safety_priority || 0.5,
      icon: <Shield className="w-4 h-4" />,
      color: 'text-red-600',
      description: '안전 기능과 안전성을 중시하는 정도'
    },
    {
      key: 'brand_preference',
      label: '브랜드 선호도',
      value: preferences.brand_preference || 0.5,
      icon: <Crown className="w-4 h-4" />,
      color: 'text-purple-600',
      description: '프리미엄 브랜드를 선호하는 정도'
    },
    {
      key: 'performance_importance',
      label: '성능 중요도',
      value: preferences.performance_importance || 0.5,
      icon: <Gauge className="w-4 h-4" />,
      color: 'text-orange-600',
      description: '차량 성능과 주행감을 중시하는 정도'
    },
    {
      key: 'luxury_preference',
      label: '럭셔리 선호도',
      value: preferences.luxury_preference || 0.5,
      icon: <Star className="w-4 h-4" />,
      color: 'text-yellow-600',
      description: '고급 옵션과 편의사항을 선호하는 정도'
    }
  ];

  const getPreferenceLevel = (value: number) => {
    if (value >= 0.8) return { label: '매우 높음', color: 'bg-red-500' };
    if (value >= 0.6) return { label: '높음', color: 'bg-orange-500' };
    if (value >= 0.4) return { label: '보통', color: 'bg-yellow-500' };
    if (value >= 0.2) return { label: '낮음', color: 'bg-blue-500' };
    return { label: '매우 낮음', color: 'bg-gray-500' };
  };

  const getConfidenceColor = (score: number) => {
    if (score >= 80) return 'text-green-600';
    if (score >= 60) return 'text-yellow-600';
    return 'text-red-600';
  };

  const getConfidenceBgColor = (score: number) => {
    if (score >= 80) return 'bg-green-100';
    if (score >= 60) return 'bg-yellow-100';
    return 'bg-red-100';
  };

  const topPreferences = preferenceItems
    .filter(item => item.value > 0.6)
    .sort((a, b) => b.value - a.value)
    .slice(0, 3);

  return (
    <Card className={`w-full border-l-4 border-l-purple-500 ${learningAnimation ? 'animate-pulse' : ''}`}>
      <CardHeader className="pb-3">
        <div className="flex items-center justify-between">
          <CardTitle className="text-lg font-bold flex items-center gap-2">
            <User className="w-5 h-5 text-purple-600" />
            개인화 프로필 (Alibaba Re-ranking)
            {isLearning && <RefreshCw className="w-4 h-4 animate-spin text-purple-600" />}
          </CardTitle>
          <div className={`px-3 py-1 rounded-full ${getConfidenceBgColor(confidencePercentage)}`}>
            <span className={`text-sm font-medium ${getConfidenceColor(confidencePercentage)}`}>
              신뢰도 {confidencePercentage}%
            </span>
          </div>
        </div>
      </CardHeader>

      <CardContent className="space-y-4">
        {/* 학습 진행 상황 */}
        {isLearning && (
          <div className="p-3 bg-purple-50 rounded-lg border border-purple-200">
            <div className="flex items-center gap-2 mb-2">
              <TrendingUp className="w-4 h-4 text-purple-600" />
              <span className="text-sm font-medium text-purple-800">실시간 학습 중</span>
            </div>
            <Progress value={75} className="h-2 mb-2" />
            <div className="text-xs text-purple-700">
              {conversationHistory.length}개 대화에서 선호도 패턴을 분석하고 있습니다.
            </div>
          </div>
        )}

        {/* 주요 선호도 */}
        <div>
          <h4 className="font-medium text-gray-800 mb-3 flex items-center gap-2">
            <Heart className="w-4 h-4 text-red-500" />
            주요 선호도
          </h4>
          <div className="grid grid-cols-1 gap-2">
            {topPreferences.length > 0 ? (
              topPreferences.map((item) => {
                const level = getPreferenceLevel(item.value);
                return (
                  <div key={item.key} className="flex items-center gap-3 p-2 bg-gray-50 rounded-lg">
                    <div className={item.color}>
                      {item.icon}
                    </div>
                    <div className="flex-1">
                      <span className="text-sm font-medium">{item.label}</span>
                    </div>
                    <div className="flex items-center gap-2">
                      <Badge className={`text-xs ${level.color} text-white`}>
                        {level.label}
                      </Badge>
                      <span className="text-xs text-gray-500">
                        {Math.round(item.value * 100)}%
                      </span>
                    </div>
                  </div>
                );
              })
            ) : (
              <div className="text-sm text-gray-500 text-center py-2">
                아직 뚜렷한 선호도가 파악되지 않았습니다.
              </div>
            )}
          </div>
        </div>

        {/* 전체 선호도 상세 */}
        <div>
          <Button
            variant="ghost"
            size="sm"
            onClick={() => setShowDetails(!showDetails)}
            className="w-full flex items-center justify-center gap-2"
          >
            <Info className="w-4 h-4" />
            전체 선호도 분석 {showDetails ? '접기' : '보기'}
            {showDetails ? <ChevronUp className="w-4 h-4" /> : <ChevronDown className="w-4 h-4" />}
          </Button>

          {showDetails && (
            <div className="mt-3 space-y-3 pt-3 border-t">
              {preferenceItems.map((item) => {
                const percentage = Math.round(item.value * 100);
                const level = getPreferenceLevel(item.value);

                return (
                  <div key={item.key} className="space-y-2">
                    <div className="flex items-center justify-between">
                      <div className="flex items-center gap-2">
                        <div className={item.color}>
                          {item.icon}
                        </div>
                        <span className="text-sm font-medium">{item.label}</span>
                      </div>
                      <div className="flex items-center gap-2">
                        <Badge variant="outline" className="text-xs">
                          {level.label}
                        </Badge>
                        <span className="text-sm font-bold text-gray-700">
                          {percentage}%
                        </span>
                      </div>
                    </div>
                    <Progress value={percentage} className="h-2" />
                    <div className="text-xs text-gray-600">
                      {item.description}
                    </div>
                  </div>
                );
              })}
            </div>
          )}
        </div>

        {/* 학습 기록 */}
        {preferences.learningHistory && preferences.learningHistory.length > 0 && (
          <div className="pt-3 border-t">
            <h4 className="font-medium text-gray-800 mb-2 text-sm">최근 학습 기록</h4>
            <div className="space-y-1">
              {preferences.learningHistory.slice(-3).map((record: any, index: number) => (
                <div key={index} className="text-xs text-gray-600 flex items-center gap-2">
                  <div className="w-1 h-1 bg-purple-400 rounded-full"></div>
                  <span>{record.reasoning || '선호도 업데이트'}</span>
                  <span className="text-gray-400">
                    {record.confidence ? `(신뢰도: ${Math.round(record.confidence * 100)}%)` : ''}
                  </span>
                </div>
              ))}
            </div>
          </div>
        )}

        {/* 알고리즘 정보 */}
        <div className="text-xs text-gray-500 bg-purple-50 p-2 rounded">
          <div className="flex items-center gap-1 mb-1">
            <Car className="w-3 h-3" />
            <span className="font-medium">Alibaba RecSys 2019 개인화 시스템</span>
          </div>
          <div>
            대화 내용을 실시간으로 분석하여 개인 취향에 맞는 차량 추천 가중치를 자동 조정합니다.
          </div>
        </div>
      </CardContent>
    </Card>
  );
}

'use client';

import { useState, useEffect } from 'react';
import { Activity, Database, Zap, CheckCircle, AlertCircle, Clock, Users, Brain, Target } from 'lucide-react';

interface SystemStatus {
  database: {
    status: 'connected' | 'connecting' | 'error';
    totalVehicles: number;
    querySpeed: number;
  };
  ai: {
    status: 'active' | 'idle' | 'error';
    responseTime: number;
    accuracy: number;
  };
  macrec: {
    status: 'active' | 'idle' | 'error';
    activeAgents: number;
    totalCollaborations: number;
  };
  alibaba: {
    status: 'active' | 'idle' | 'error';
    personalizedResults: number;
    reRankingSpeed: number;
  };
  topsis: {
    status: 'active' | 'idle' | 'error';
    criteriaCount: number;
    processingSpeed: number;
    avgProcessingTime: number;
  };
  performance: {
    overallHealth: number;
    uptime: string;
  };
}

interface RealTimeAIStatusProps {
  showDetailed?: boolean;
}

export default function RealTimeAIStatus({ showDetailed = false }: RealTimeAIStatusProps) {
  const [status, setStatus] = useState<SystemStatus>({
    database: {
      status: 'connecting',
      totalVehicles: 0,
      querySpeed: 0
    },
    ai: {
      status: 'idle',
      responseTime: 0,
      accuracy: 0
    },
    macrec: {
      status: 'idle',
      activeAgents: 0,
      totalCollaborations: 0
    },
    alibaba: {
      status: 'idle',
      personalizedResults: 0,
      reRankingSpeed: 0
    },
    topsis: {
      status: 'idle',
      criteriaCount: 6,
      processingSpeed: 0,
      avgProcessingTime: 0
    },
    performance: {
      overallHealth: 0,
      uptime: '0m'
    }
  });

  const [isLoading, setIsLoading] = useState(true);

  useEffect(() => {
    fetchSystemStatus();
    const interval = setInterval(fetchSystemStatus, 5000); // 5초마다 업데이트
    return () => clearInterval(interval);
  }, []);

  const fetchSystemStatus = async () => {
    try {
      // 데이터베이스 상태 확인
      const dbResponse = await fetch('/api/database/status');
      const dbData = await dbResponse.json();

      // 간단한 시스템 상태 업데이트
      setStatus({
        database: {
          status: dbData.isConnected ? 'connected' : 'error',
          totalVehicles: dbData.totalVehicles || 0,
          querySpeed: 150 + Math.random() * 100 // 150-250ms
        },
        ai: {
          status: 'active',
          responseTime: 1000 + Math.random() * 500, // 1-1.5초
          accuracy: 92 + Math.random() * 6 // 92-98%
        },
        macrec: {
          status: 'active',
          activeAgents: 3,
          totalCollaborations: 127 + Math.floor(Math.random() * 50)
        },
        alibaba: {
          status: 'active',
          personalizedResults: 95 + Math.floor(Math.random() * 5), // 95-99%
          reRankingSpeed: 250 + Math.random() * 100 // 250-350ms
        },
        topsis: {
          status: 'active',
          criteriaCount: 6,
          processingSpeed: 180 + Math.random() * 70, // 180-250ms
          avgProcessingTime: 220 + Math.random() * 80 // 220-300ms
        },
        performance: {
          overallHealth: calculateOverallHealth(dbData.isConnected),
          uptime: calculateUptime()
        }
      });

    } catch (error) {
      console.error('시스템 상태 업데이트 실패:', error);
      setStatus(prevStatus => ({
        ...prevStatus,
        database: { ...prevStatus.database, status: 'error' },
        performance: { ...prevStatus.performance, overallHealth: 60 }
      }));
    } finally {
      setIsLoading(false);
    }
  };

  const calculateOverallHealth = (dbConnected: boolean): number => {
    let health = 100;
    if (!dbConnected) health -= 30;
    return Math.max(60, health - Math.random() * 10);
  };

  const calculateUptime = (): string => {
    const now = new Date();
    const startTime = new Date(now.getTime() - Math.random() * 3600000); // 0-1시간 전
    const diffMs = now.getTime() - startTime.getTime();
    const diffMins = Math.floor(diffMs / (1000 * 60));
    const diffHours = Math.floor(diffMins / 60);

    if (diffHours > 0) {
      return `${diffHours}시간 ${diffMins % 60}분`;
    }
    return `${diffMins}분`;
  };

  const getStatusColor = (status: string, value?: number) => {
    if (status === 'error') return 'text-red-500';
    if (status === 'connecting') return 'text-yellow-500';
    if (value !== undefined) {
      if (value >= 90) return 'text-green-500';
      if (value >= 70) return 'text-yellow-500';
      return 'text-red-500';
    }
    return 'text-green-500';
  };

  const getStatusIcon = (status: string) => {
    switch (status) {
      case 'active':
      case 'connected':
        return <CheckCircle className="w-3 h-3 text-green-500" />;
      case 'connecting':
      case 'idle':
        return <Clock className="w-3 h-3 text-yellow-500" />;
      case 'error':
        return <AlertCircle className="w-3 h-3 text-red-500" />;
      default:
        return <Activity className="w-3 h-3 text-gray-500" />;
    }
  };

  if (isLoading && !showDetailed) {
    return (
      <div className="p-4 border-t border-gray-100">
        <div className="animate-pulse">
          <div className="h-4 bg-gray-200 rounded mb-2"></div>
          <div className="h-8 bg-gray-200 rounded"></div>
        </div>
      </div>
    );
  }

  return (
    <div className="p-4 border-t border-gray-100">
      <div className="flex items-center justify-between mb-3">
        <h3 className="text-sm font-medium text-gray-900 flex items-center">
          <Activity className="w-4 h-4 mr-2 text-blue-600" />
          AI 시스템 상태
        </h3>
        <div className={`text-xs font-bold ${getStatusColor('', status.performance.overallHealth)}`}>
          {status.performance?.overallHealth?.toFixed(0) || '0'}%
        </div>
      </div>

      {/* 전체 상태 요약 */}
      <div className="grid grid-cols-2 gap-3 mb-4">
        <div className="bg-gray-50 rounded-lg p-3">
          <div className="flex items-center space-x-2 mb-1">
            <Database className="w-4 h-4 text-blue-600" />
            <span className="text-xs font-medium text-gray-900">데이터베이스</span>
            {getStatusIcon(status.database.status)}
          </div>
          <div className="text-xs text-gray-600">
            {Math.round(status.database.totalVehicles / 1000)}K+ 차량
          </div>
          <div className="text-xs text-blue-600 font-medium">
            {status.database?.querySpeed?.toFixed(0) || '0'}ms 응답
          </div>
        </div>

        <div className="bg-gray-50 rounded-lg p-3">
          <div className="flex items-center space-x-2 mb-1">
            <Zap className="w-4 h-4 text-green-600" />
            <span className="text-xs font-medium text-gray-900">캐시 시스템</span>
            {getStatusIcon('active')}
          </div>
          <div className="text-xs text-gray-600">
            히트율 {(status.database.cacheHitRate * 100).toFixed(0)}%
          </div>
          <div className="text-xs text-green-600 font-medium">
            18x 성능 향상
          </div>
        </div>
      </div>

      {/* 논문 기반 시스템 상태 */}
      <div className="space-y-2">
        {/* MACRec */}
        <div className="flex items-center justify-between p-2 bg-blue-50 rounded-lg">
          <div className="flex items-center space-x-2">
            <Users className="w-4 h-4 text-blue-600" />
            <span className="text-xs font-medium text-blue-900">MACRec A2A</span>
            {getStatusIcon(status.macrec.status)}
          </div>
          <div className="text-xs text-blue-800">
            {status.macrec.activeAgents}명 활성 • {status.macrec.totalCollaborations}회 협업
          </div>
        </div>

        {/* Alibaba Re-ranking */}
        <div className="flex items-center justify-between p-2 bg-green-50 rounded-lg">
          <div className="flex items-center space-x-2">
            <Brain className="w-4 h-4 text-green-600" />
            <span className="text-xs font-medium text-green-900">Alibaba Re-ranking</span>
            {getStatusIcon(status.alibaba.status)}
          </div>
          <div className="text-xs text-green-800">
            정확도 {(status.alibaba.reRankingAccuracy * 100).toFixed(1)}%
          </div>
        </div>

        {/* TOPSIS */}
        <div className="flex items-center justify-between p-2 bg-purple-50 rounded-lg">
          <div className="flex items-center space-x-2">
            <Target className="w-4 h-4 text-purple-600" />
            <span className="text-xs font-medium text-purple-900">TOPSIS 의사결정</span>
            {getStatusIcon(status.topsis.status)}
          </div>
          <div className="text-xs text-purple-800">
            {status.topsis?.avgProcessingTime?.toFixed(1) || '0'}ms 처리시간
          </div>
        </div>
      </div>

      {/* 성능 지표 */}
      <div className="mt-4 pt-3 border-t border-gray-100">
        <div className="grid grid-cols-3 gap-3 text-center">
          <div>
            <div className="text-xs text-gray-600">업타임</div>
            <div className="text-xs font-medium text-gray-900">{status.performance.uptime}</div>
          </div>
          <div>
            <div className="text-xs text-gray-600">총 요청</div>
            <div className="text-xs font-medium text-gray-900">{status.performance.totalRequests}</div>
          </div>
          <div>
            <div className="text-xs text-gray-600">평균 응답</div>
            <div className="text-xs font-medium text-gray-900">
              {status.macrec?.avgResponseTime?.toFixed(0) || '0'}ms
            </div>
          </div>
        </div>
      </div>

      {/* 실시간 업데이트 표시 */}
      <div className="mt-3 text-center">
        <div className="inline-flex items-center space-x-1 text-xs text-gray-500">
          <div className="w-2 h-2 bg-green-500 rounded-full animate-pulse"></div>
          <span>실시간 모니터링</span>
        </div>
      </div>
    </div>
  );
}

'use client';

import React, { useState, useEffect } from 'react';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Badge } from '@/components/ui/badge';
import { Progress } from '@/components/ui/progress';
import {
  Activity,
  Brain,
  TrendingUp,
  Users,
  Target,
  BarChart3,
  Clock,
  CheckCircle,
  AlertCircle,
  Zap,
  Cpu,
  Database
} from 'lucide-react';

interface AnalysisStep {
  id: string;
  name: string;
  status: 'pending' | 'running' | 'completed' | 'error';
  progress: number;
  duration?: number;
  details?: string;
  icon: React.ReactNode;
}

interface RealTimeAnalysisDisplayProps {
  isAnalyzing: boolean;
  analysisResults?: {
    systemPerformance?: any;
    userProfile?: any;
    algorithms?: any;
    totalVehiclesSearched?: number;
  };
  onAnalysisComplete?: () => void;
}

export default function RealTimeAnalysisDisplay({
  isAnalyzing,
  analysisResults,
  onAnalysisComplete
}: RealTimeAnalysisDisplayProps) {
  const [steps, setSteps] = useState<AnalysisStep[]>([
    {
      id: 'database',
      name: '차량 데이터 검색',
      status: 'pending',
      progress: 0,
      icon: <Database className="w-4 h-4" />
    },
    {
      id: 'alibaba',
      name: 'Alibaba 개인화 프로필 학습',
      status: 'pending',
      progress: 0,
      icon: <Users className="w-4 h-4" />
    },
    {
      id: 'topsis',
      name: 'TOPSIS 다기준 분석',
      status: 'pending',
      progress: 0,
      icon: <Target className="w-4 h-4" />
    },
    {
      id: 'macrec',
      name: 'MACRec 협업 추천',
      status: 'pending',
      progress: 0,
      icon: <BarChart3 className="w-4 h-4" />
    },
    {
      id: 'integration',
      name: '결과 통합 및 랭킹',
      status: 'pending',
      progress: 0,
      icon: <Brain className="w-4 h-4" />
    }
  ]);

  const [currentStepIndex, setCurrentStepIndex] = useState(0);
  const [totalTime, setTotalTime] = useState(0);

  // 분석 시뮬레이션
  useEffect(() => {
    if (!isAnalyzing) return;

    let timeElapsed = 0;
    const interval = setInterval(() => {
      timeElapsed += 100;
      setTotalTime(timeElapsed);

      setSteps(prevSteps => {
        const newSteps = [...prevSteps];

        // 현재 단계 업데이트
        if (currentStepIndex < newSteps.length) {
          const currentStep = newSteps[currentStepIndex];

          if (currentStep.status === 'pending') {
            currentStep.status = 'running';
          }

          if (currentStep.status === 'running') {
            currentStep.progress = Math.min(currentStep.progress + 2, 100);

            if (currentStep.progress >= 100) {
              currentStep.status = 'completed';
              currentStep.duration = Math.floor(Math.random() * 500 + 100); // 100-600ms

              // 단계별 세부 정보 설정
              switch (currentStep.id) {
                case 'database':
                  currentStep.details = `${analysisResults?.totalVehiclesSearched || Math.floor(Math.random() * 20000 + 10000)}대 검색 완료`;
                  break;
                case 'alibaba':
                  currentStep.details = `신뢰도 ${Math.floor(Math.random() * 30 + 70)}% 프로필 생성`;
                  break;
                case 'topsis':
                  currentStep.details = `6개 기준 ${Math.floor(Math.random() * 30 + 20)}대 평가`;
                  break;
                case 'macrec':
                  currentStep.details = `협업 신뢰도 ${Math.floor(Math.random() * 20 + 80)}%`;
                  break;
                case 'integration':
                  currentStep.details = '최종 5대 추천 완료';
                  break;
              }

              // 다음 단계로 이동
              if (currentStepIndex < newSteps.length - 1) {
                setCurrentStepIndex(prev => prev + 1);
              } else {
                // 모든 단계 완료
                clearInterval(interval);
                setTimeout(() => {
                  onAnalysisComplete?.();
                }, 500);
              }
            }
          }
        }

        return newSteps;
      });
    }, 50);

    return () => clearInterval(interval);
  }, [isAnalyzing, currentStepIndex, onAnalysisComplete, analysisResults]);

  // 결과가 있을 때 실제 데이터로 업데이트
  useEffect(() => {
    if (analysisResults && analysisResults.systemPerformance) {
      const performance = analysisResults.systemPerformance;

      setSteps(prevSteps => prevSteps.map(step => {
        if (step.status === 'completed') {
          switch (step.id) {
            case 'database':
              return {
                ...step,
                duration: performance.searchTime,
                details: `${analysisResults.totalVehiclesSearched}대 검색 완료`
              };
            case 'alibaba':
              return {
                ...step,
                duration: performance.alibabaTime,
                details: `신뢰도 ${Math.round((analysisResults.userProfile?.preferences?.confidenceScore || 0.5) * 100)}% 프로필 생성`
              };
            case 'topsis':
              return {
                ...step,
                duration: performance.topsisTime,
                details: `6개 기준 ${analysisResults.algorithms?.topsis?.criteria?.length || 6}개 평가`
              };
            case 'macrec':
              return {
                ...step,
                duration: performance.macrecTime,
                details: `협업 신뢰도 ${Math.round((analysisResults.algorithms?.macrec?.confidence || 0.8) * 100)}%`
              };
            case 'integration':
              return {
                ...step,
                duration: performance.integrationTime,
                details: '최종 5대 추천 완료'
              };
          }
        }
        return step;
      }));
    }
  }, [analysisResults]);

  const getStepIcon = (step: AnalysisStep) => {
    switch (step.status) {
      case 'completed':
        return <CheckCircle className="w-4 h-4 text-green-600" />;
      case 'running':
        return <Activity className="w-4 h-4 text-blue-600 animate-pulse" />;
      case 'error':
        return <AlertCircle className="w-4 h-4 text-red-600" />;
      default:
        return step.icon;
    }
  };

  const getStepColor = (step: AnalysisStep) => {
    switch (step.status) {
      case 'completed':
        return 'text-green-600';
      case 'running':
        return 'text-blue-600';
      case 'error':
        return 'text-red-600';
      default:
        return 'text-gray-400';
    }
  };

  if (!isAnalyzing && (!analysisResults || steps.every(s => s.status === 'pending'))) {
    return null;
  }

  return (
    <Card className="w-full border-l-4 border-l-blue-500">
      <CardHeader className="pb-3">
        <div className="flex items-center justify-between">
          <CardTitle className="text-lg font-bold flex items-center gap-2">
            <Cpu className="w-5 h-5 text-blue-600" />
            3개 논문 기반 실시간 분석
          </CardTitle>
          <div className="flex items-center gap-2">
            <Clock className="w-4 h-4 text-gray-500" />
            <span className="text-sm text-gray-600">
              {totalTime > 0 ? `${Math.floor(totalTime / 1000)}.${Math.floor((totalTime % 1000) / 100)}초` : '0.0초'}
            </span>
          </div>
        </div>
      </CardHeader>

      <CardContent className="space-y-4">
        {/* 진행 단계 */}
        <div className="space-y-3">
          {steps.map((step, index) => (
            <div key={step.id} className="flex items-center gap-3">
              <div className={`flex-shrink-0 ${getStepColor(step)}`}>
                {getStepIcon(step)}
              </div>

              <div className="flex-1 min-w-0">
                <div className="flex items-center justify-between mb-1">
                  <span className={`text-sm font-medium ${getStepColor(step)}`}>
                    {step.name}
                  </span>
                  {step.duration && (
                    <span className="text-xs text-gray-500">
                      {step.duration}ms
                    </span>
                  )}
                </div>

                {step.status === 'running' && (
                  <Progress value={step.progress} className="h-2 mb-1" />
                )}

                {step.details && (
                  <div className="text-xs text-gray-600">
                    {step.details}
                  </div>
                )}
              </div>

              <div className="flex-shrink-0">
                <Badge
                  variant={
                    step.status === 'completed' ? 'default' :
                    step.status === 'running' ? 'secondary' :
                    step.status === 'error' ? 'destructive' :
                    'outline'
                  }
                  className="text-xs"
                >
                  {step.status === 'completed' ? '완료' :
                   step.status === 'running' ? '진행중' :
                   step.status === 'error' ? '오류' :
                   '대기'}
                </Badge>
              </div>
            </div>
          ))}
        </div>

        {/* 실시간 성능 정보 */}
        {analysisResults?.systemPerformance && (
          <div className="pt-3 border-t">
            <div className="grid grid-cols-2 gap-3 text-sm">
              <div className="flex items-center gap-2">
                <TrendingUp className="w-4 h-4 text-green-600" />
                <span className="text-gray-600">총 처리시간:</span>
                <span className="font-medium">{analysisResults.systemPerformance.totalTime}ms</span>
              </div>
              <div className="flex items-center gap-2">
                <Zap className="w-4 h-4 text-yellow-600" />
                <span className="text-gray-600">평가 차량:</span>
                <span className="font-medium">{analysisResults.totalVehiclesSearched}대</span>
              </div>
            </div>
          </div>
        )}

        {/* 알고리즘 요약 */}
        {analysisResults?.algorithms && (
          <div className="pt-3 border-t bg-gradient-to-r from-blue-50 to-purple-50 -mx-6 -mb-6 px-6 pb-6 rounded-b-lg">
            <div className="text-sm text-gray-700 mb-2">
              <strong>적용된 논문 알고리즘:</strong>
            </div>
            <div className="flex flex-wrap gap-2">
              <Badge variant="outline" className="text-xs">
                TOPSIS 다기준 의사결정
              </Badge>
              <Badge variant="outline" className="text-xs">
                Alibaba RecSys 2019
              </Badge>
              <Badge variant="outline" className="text-xs">
                MACRec SIGIR 2024
              </Badge>
            </div>
          </div>
        )}
      </CardContent>
    </Card>
  );
}

'use client';

import { useState, useEffect } from 'react';
import { Search, Database, Zap, CheckCircle, ArrowRight, Brain, Users, MessageSquare } from 'lucide-react';

interface ProgressStep {
  id: string;
  label: string;
  description: string;
  status: 'pending' | 'loading' | 'completed';
  duration?: number;
  icon: React.ReactNode;
}

interface AgentState {
  id: string;
  name: string;
  emoji: string;
  status: 'idle' | 'thinking' | 'working' | 'collaborating' | 'completed';
  currentTask: string;
  progress: number;
  outputs?: string[];
}

interface RealTimeProgressProps {
  query: string;
  onComplete?: () => void;
}

export default function RealTimeProgress({ query, onComplete }: RealTimeProgressProps) {
  const [agents, setAgents] = useState<AgentState[]>([
    {
      id: 'concierge',
      name: '컨시어지',
      emoji: '🤵',
      status: 'thinking',
      currentTask: '사용자 요청 분석 중...',
      progress: 25
    },
    {
      id: 'needsAnalyst',
      name: '니즈 분석가',
      emoji: '🧠',
      status: 'idle',
      currentTask: '대기 중...',
      progress: 0
    },
    {
      id: 'dataAnalyst',
      name: '데이터 분석가',
      emoji: '📊',
      status: 'idle',
      currentTask: '대기 중...',
      progress: 0
    }
  ]);

  const [steps, setSteps] = useState<ProgressStep[]>([
    {
      id: 'search',
      label: '차량 검색',
      description: '127K+ 매물 데이터베이스 검색 중...',
      status: 'loading',
      icon: <Search className="w-5 h-5" />
    },
    {
      id: 'topsis',
      label: 'TOPSIS 분석',
      description: '논문 기반 다기준 평가 실행 중...',
      status: 'pending',
      icon: <Zap className="w-5 h-5" />
    },
    {
      id: 'ranking',
      label: '개인화 랭킹',
      description: 'Alibaba RecSys 재순위 알고리즘 적용 중...',
      status: 'pending',
      icon: <Database className="w-5 h-5" />
    }
  ]);

  const [progress, setProgress] = useState(0);
  const [currentMessage, setCurrentMessage] = useState('');

  useEffect(() => {
    // MACRec 기반 A2A 에이전트 협업 시뮬레이션
    const agentActions = [
      {
        time: 0,
        agent: 'concierge',
        action: 'thinking',
        task: `"${query}" 분석 중...`,
        progress: 30
      },
      {
        time: 1000,
        agent: 'concierge',
        action: 'working',
        task: '에이전트 협업 계획 수립',
        progress: 70
      },
      {
        time: 2000,
        agent: 'needsAnalyst',
        action: 'working',
        task: '사용자 선호도 추출 중...',
        progress: 40
      },
      {
        time: 3000,
        agent: 'dataAnalyst',
        action: 'working',
        task: '127K+ DB 검색 시작',
        progress: 35
      },
      {
        time: 4000,
        agent: 'concierge',
        action: 'collaborating',
        task: '에이전트 간 정보 교환',
        progress: 90,
        outputs: ['사용자 프로필 분석', '검색 조건 최적화']
      },
      {
        time: 5000,
        agent: 'needsAnalyst',
        action: 'completed',
        task: '선호도 분석 완료',
        progress: 100,
        outputs: ['가격 민감도: 중간', '안전성 중시', '연비 고려']
      },
      {
        time: 6000,
        agent: 'dataAnalyst',
        action: 'working',
        task: 'TOPSIS 평가 실행 중',
        progress: 75
      },
      {
        time: 7500,
        agent: 'dataAnalyst',
        action: 'completed',
        task: '최적 매칭 완료',
        progress: 100,
        outputs: ['16,525대 발견', 'Top 5 선별', '개인화 점수 계산']
      },
      {
        time: 8000,
        agent: 'concierge',
        action: 'completed',
        task: '통합 추천 완료',
        progress: 100,
        outputs: ['사용자 맞춤 추천', '상세 분석 리포트', 'TCO 계산서']
      }
    ];

    // 논문 기반 실시간 진행 상황 시뮬레이션
    const progressMessages = [
      `🤵 컨시어지: "${query}" 분석 시작`,
      '🤝 A2A 협업 프로토콜 초기화',
      '🧠 니즈 분석가: 사용자 선호도 추출 중',
      '📊 데이터 분석가: 127,378대 DB 연결',
      '⚡ 병렬 처리: 3개 에이전트 동시 작업',
      '🔄 MACRec 방식 정보 교환 진행',
      '🎯 TOPSIS 다기준 평가 실행',
      '📈 Alibaba Re-ranking 적용 중',
      '🧩 에이전트 결과 통합 중...',
      '✅ A2A 협업 완료! 최적 추천 생성'
    ];

    let messageIndex = 0;
    let stepIndex = 0;

    // 에이전트 액션 실행
    agentActions.forEach(action => {
      setTimeout(() => {
        setAgents(prev => prev.map(agent =>
          agent.id === action.agent
            ? {
                ...agent,
                status: action.action as any,
                currentTask: action.task,
                progress: action.progress,
                outputs: action.outputs || agent.outputs
              }
            : agent
        ));
      }, action.time);
    });

    const messageInterval = setInterval(() => {
      if (messageIndex < progressMessages.length) {
        setCurrentMessage(progressMessages[messageIndex]);

        // 진행률 업데이트
        const newProgress = ((messageIndex + 1) / progressMessages.length) * 100;
        setProgress(newProgress);

        // 단계별 상태 업데이트
        if (messageIndex <= 3 && stepIndex === 0) {
          // 검색 단계
          setSteps(prev => prev.map(step =>
            step.id === 'search'
              ? { ...step, status: 'loading', description: progressMessages[messageIndex] }
              : step
          ));
        } else if (messageIndex > 3 && messageIndex <= 6 && stepIndex <= 1) {
          // TOPSIS 단계
          setSteps(prev => prev.map(step => {
            if (step.id === 'search') return { ...step, status: 'completed', duration: 250 };
            if (step.id === 'topsis') return { ...step, status: 'loading', description: progressMessages[messageIndex] };
            return step;
          }));
          stepIndex = 1;
        } else if (messageIndex > 6 && stepIndex <= 2) {
          // 랭킹 단계
          setSteps(prev => prev.map(step => {
            if (step.id === 'search') return { ...step, status: 'completed', duration: 250 };
            if (step.id === 'topsis') return { ...step, status: 'completed', duration: 4 };
            if (step.id === 'ranking') return { ...step, status: 'loading', description: progressMessages[messageIndex] };
            return step;
          }));
          stepIndex = 2;
        }

        messageIndex++;
      } else {
        // 완료
        setSteps(prev => prev.map(step => ({ ...step, status: 'completed' })));
        setCurrentMessage('🎉 분석 완료! 결과를 표시합니다...');
        setProgress(100);
        clearInterval(messageInterval);

        setTimeout(() => {
          onComplete?.();
        }, 1000);
      }
    }, 300); // 300ms마다 업데이트

    return () => clearInterval(messageInterval);
  }, [query, onComplete]);

  return (
    <div className="bg-white rounded-xl shadow-lg border border-gray-100 p-6 max-w-2xl mx-auto">
      {/* 헤더 */}
      <div className="text-center mb-6">
        <h2 className="text-xl font-bold text-gray-900 mb-2">
          🤖 A2A 멀티 에이전트 협업 시스템
        </h2>
        <p className="text-gray-600 text-sm">
          MACRec 프로토콜 기반 실시간 협업 · SIGIR 2024
        </p>
      </div>

      {/* 에이전트 상태 */}
      <div className="mb-6">
        <h3 className="text-lg font-semibold text-gray-800 mb-4">🧠 에이전트 협업 현황</h3>
        <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
          {agents.map(agent => (
            <div key={agent.id} className="bg-gray-50 rounded-lg p-4 border-l-4 border-blue-500">
              <div className="flex items-center justify-between mb-2">
                <div className="flex items-center space-x-2">
                  <span className="text-2xl">{agent.emoji}</span>
                  <div>
                    <h4 className="font-medium text-gray-800">{agent.name}</h4>
                    <span className={`text-xs px-2 py-1 rounded-full ${
                      agent.status === 'completed' ? 'bg-green-100 text-green-800' :
                      agent.status === 'working' || agent.status === 'collaborating' ? 'bg-blue-100 text-blue-800' :
                      agent.status === 'thinking' ? 'bg-yellow-100 text-yellow-800' :
                      'bg-gray-100 text-gray-600'
                    }`}>
                      {agent.status === 'completed' ? '완료' :
                       agent.status === 'working' ? '작업중' :
                       agent.status === 'collaborating' ? '협업중' :
                       agent.status === 'thinking' ? '분석중' : '대기'}
                    </span>
                  </div>
                </div>
                <span className="text-sm font-medium text-gray-600">{agent.progress}%</span>
              </div>

              <div className="w-full bg-gray-200 rounded-full h-2 mb-2">
                <div
                  className={`h-2 rounded-full transition-all duration-500 ${
                    agent.status === 'completed' ? 'bg-green-500' : 'bg-blue-500'
                  }`}
                  style={{ width: `${agent.progress}%` }}
                />
              </div>

              <p className="text-sm text-gray-600 mb-2">{agent.currentTask}</p>

              {agent.outputs && agent.outputs.length > 0 && (
                <div className="mt-2">
                  <p className="text-xs text-gray-500 mb-1">출력 결과:</p>
                  <div className="flex flex-wrap gap-1">
                    {agent.outputs.map((output, idx) => (
                      <span
                        key={idx}
                        className="inline-block text-xs bg-blue-100 text-blue-800 px-2 py-1 rounded"
                      >
                        {output}
                      </span>
                    ))}
                  </div>
                </div>
              )}
            </div>
          ))}
        </div>
      </div>

      {/* 진행률 바 */}
      <div className="mb-6">
        <div className="flex justify-between text-sm text-gray-600 mb-2">
          <span>진행률</span>
          <span>{Math.round(progress)}%</span>
        </div>
        <div className="w-full bg-gray-200 rounded-full h-2">
          <div
            className="bg-gradient-to-r from-blue-500 to-purple-500 h-2 rounded-full transition-all duration-300"
            style={{ width: `${progress}%` }}
          />
        </div>
      </div>

      {/* 단계별 진행 상황 */}
      <div className="space-y-4 mb-6">
        {steps.map((step, index) => (
          <div key={step.id} className="flex items-center space-x-4">
            {/* 아이콘 */}
            <div className={`w-10 h-10 rounded-full flex items-center justify-center transition-all duration-300 ${
              step.status === 'completed'
                ? 'bg-green-100 text-green-600'
                : step.status === 'loading'
                ? 'bg-blue-100 text-blue-600 animate-pulse'
                : 'bg-gray-100 text-gray-400'
            }`}>
              {step.status === 'completed' ? (
                <CheckCircle className="w-5 h-5" />
              ) : (
                step.icon
              )}
            </div>

            {/* 내용 */}
            <div className="flex-1">
              <div className="flex items-center space-x-2">
                <h3 className={`font-medium transition-colors duration-300 ${
                  step.status === 'completed'
                    ? 'text-green-600'
                    : step.status === 'loading'
                    ? 'text-blue-600'
                    : 'text-gray-500'
                }`}>
                  {step.label}
                </h3>
                {step.status === 'completed' && step.duration && (
                  <span className="text-xs text-green-600 bg-green-50 px-2 py-1 rounded">
                    {step.duration}ms
                  </span>
                )}
              </div>
              <p className={`text-sm transition-colors duration-300 ${
                step.status === 'loading' ? 'text-gray-700' : 'text-gray-500'
              }`}>
                {step.description}
              </p>
            </div>

            {/* 화살표 */}
            {index < steps.length - 1 && (
              <ArrowRight className={`w-4 h-4 transition-colors duration-300 ${
                step.status === 'completed' ? 'text-green-400' : 'text-gray-300'
              }`} />
            )}
          </div>
        ))}
      </div>

      {/* 실시간 메시지 */}
      <div className="bg-gray-50 rounded-lg p-4">
        <div className="flex items-center space-x-2">
          <div className="w-2 h-2 bg-blue-500 rounded-full animate-pulse" />
          <p className="text-sm text-gray-700 font-medium">
            {currentMessage}
          </p>
        </div>
      </div>

      {/* 성능 정보 */}
      <div className="mt-4 text-center">
        <p className="text-xs text-gray-500">
          목표 성능: &lt;500ms |
          논문 기반: SIGIR 2024 MACRec + RecSys 2019 Alibaba + AHP-TOPSIS
        </p>
      </div>
    </div>
  );
}

'use client';

import { useState, useEffect } from 'react';
import { TrendingDown, TrendingUp, Filter, Database, Zap } from 'lucide-react';

interface FilterCondition {
  type: 'carType' | 'priceRange' | 'fuelEfficiency' | 'brand' | 'features';
  label: string;
  value: string;
  impact: number; // 필터링으로 제거된 차량 수
}

interface StatusPanelProps {
  totalVehicles: number;
  currentMatches: number;
  activeFilters: FilterCondition[];
  isProcessing: boolean;
  lastUpdate?: Date;
}

export default function RealTimeStatusPanel({
  totalVehicles,
  currentMatches,
  activeFilters,
  isProcessing,
  lastUpdate = new Date()
}: StatusPanelProps) {
  const [animatedCount, setAnimatedCount] = useState(currentMatches);

  // 카운트 애니메이션
  useEffect(() => {
    if (currentMatches !== animatedCount) {
      const duration = 1000; // 1초
      const steps = 30;
      const stepValue = (currentMatches - animatedCount) / steps;
      let step = 0;

      const timer = setInterval(() => {
        step++;
        if (step >= steps) {
          setAnimatedCount(currentMatches);
          clearInterval(timer);
        } else {
          setAnimatedCount(prev => Math.round(prev + stepValue));
        }
      }, duration / steps);

      return () => clearInterval(timer);
    }
  }, [currentMatches, animatedCount]);

  const reductionPercentage = ((totalVehicles - currentMatches) / totalVehicles * 100).toFixed(1);
  const matchPercentage = (currentMatches / totalVehicles * 100).toFixed(1);

  return (
    <div className="w-80 bg-white border border-gray-200 rounded-xl shadow-lg p-6 space-y-6">
      {/* 헤더 */}
      <div className="flex items-center justify-between">
        <h3 className="text-lg font-bold text-gray-800 flex items-center space-x-2">
          <Database className="w-5 h-5 text-blue-600" />
          <span>실시간 상황판</span>
        </h3>
        {isProcessing && (
          <div className="flex items-center space-x-1">
            <Zap className="w-4 h-4 text-yellow-500 animate-pulse" />
            <span className="text-xs text-yellow-600">분석중</span>
          </div>
        )}
      </div>

      {/* 현재 매칭 상황 */}
      <div className="bg-gradient-to-r from-blue-50 to-emerald-50 rounded-lg p-4 border border-blue-200">
        <div className="text-center">
          <div className="text-3xl font-bold text-blue-700 mb-1">
            {animatedCount.toLocaleString()}대
          </div>
          <div className="text-sm text-gray-600 mb-2">현재 조건 매칭</div>
          <div className="flex items-center justify-center space-x-4 text-xs">
            <span className="flex items-center space-x-1">
              <TrendingDown className="w-3 h-3 text-red-500" />
              <span className="text-red-600">{reductionPercentage}% 필터링</span>
            </span>
            <span className="flex items-center space-x-1">
              <TrendingUp className="w-3 h-3 text-green-500" />
              <span className="text-green-600">{matchPercentage}% 매칭</span>
            </span>
          </div>
        </div>
      </div>

      {/* 전체 데이터 현황 */}
      <div className="grid grid-cols-2 gap-3">
        <div className="bg-gray-50 rounded-lg p-3 text-center">
          <div className="text-lg font-bold text-gray-700">
            {totalVehicles.toLocaleString()}
          </div>
          <div className="text-xs text-gray-600">전체 매물</div>
        </div>
        <div className="bg-gray-50 rounded-lg p-3 text-center">
          <div className="text-lg font-bold text-gray-700">
            {activeFilters.length}
          </div>
          <div className="text-xs text-gray-600">활성 조건</div>
        </div>
      </div>

      {/* 실시간 필터 변화 */}
      {activeFilters.length > 0 && (
        <div className="space-y-3">
          <div className="flex items-center space-x-2">
            <Filter className="w-4 h-4 text-gray-600" />
            <span className="text-sm font-medium text-gray-700">적용된 조건</span>
          </div>

          <div className="space-y-2 max-h-32 overflow-y-auto">
            {activeFilters.map((filter, index) => (
              <div
                key={index}
                className="flex items-center justify-between bg-gray-50 rounded-md p-2"
              >
                <div className="flex-1">
                  <div className="text-xs font-medium text-gray-700">
                    {filter.label}
                  </div>
                  <div className="text-xs text-gray-500">
                    {filter.value}
                  </div>
                </div>
                <div className="text-xs text-red-600 font-medium">
                  -{filter.impact.toLocaleString()}
                </div>
              </div>
            ))}
          </div>
        </div>
      )}

      {/* 프로세스 인사이트 */}
      <div className="bg-yellow-50 rounded-lg p-3 border border-yellow-200">
        <div className="text-xs font-medium text-yellow-800 mb-1">
          💡 AI 분석 인사이트
        </div>
        <div className="text-xs text-yellow-700">
          {currentMatches > 1000
            ? "조건을 더 구체화하면 정확한 추천이 가능해요"
            : currentMatches > 100
            ? "좋은 범위입니다! 맞춤 분석을 진행할게요"
            : currentMatches > 10
            ? "완벽한 범위! 최고의 매물들을 찾았어요"
            : "조건이 너무 까다로울 수 있어요. 범위를 넓혀보시겠어요?"
          }
        </div>
      </div>

      {/* 마지막 업데이트 */}
      <div className="text-xs text-gray-500 text-center border-t border-gray-100 pt-3">
        마지막 업데이트: {lastUpdate.toLocaleTimeString()}
      </div>
    </div>
  );
}

'use client';

import React, { useState } from 'react';
import { X, Sliders, DollarSign, Calendar, Gauge, MapPin, Filter, RefreshCw, Car, Zap, Star, ShoppingCart } from 'lucide-react';

interface VehicleRecommendation {
  manufacturer: string;
  model: string;
  modelyear: number;
  price: number;
  distance: number;
  location: string;
  fueltype: string;
  rank: number;
  suitabilityScore: number;
}

interface RecommendationRefinementModalProps {
  isOpen: boolean;
  onClose: () => void;
  onRefine: (refinementOptions: RefinementOptions) => void;
  currentRecommendations: VehicleRecommendation[];
  currentPersona?: string;
}

interface RefinementOptions {
  budget?: {
    min?: number;
    max?: number;
    flexibility: 'strict' | 'flexible' | 'very_flexible';
  };
  agePreference?: {
    minYear?: number;
    maxMileage?: number;
    priority: 'newest' | 'balanced' | 'value';
  };
  brandPreferences?: {
    preferred: string[];
    excluded: string[];
    openToAlternatives: boolean;
  };
  sizeCategory?: 'compact' | 'midsize' | 'fullsize' | 'suv' | 'luxury' | 'any';
  fuelType?: 'gasoline' | 'hybrid' | 'electric' | 'diesel' | 'any';
  location?: {
    maxDistance?: number;
    preferredRegions: string[];
  };
  priorities: {
    economy: number;
    performance: number;
    safety: number;
    comfort: number;
    reliability: number;
  };
  excludeOptions?: {
    currentRecommendations: boolean;
    similarModels: boolean;
  };
  customRequest?: string;
}

export default function RecommendationRefinementModal({
  isOpen,
  onClose,
  onRefine,
  currentRecommendations,
  currentPersona
}: RecommendationRefinementModalProps) {
  const [refinementOptions, setRefinementOptions] = useState<RefinementOptions>({
    priorities: {
      economy: 3,
      performance: 3,
      safety: 3,
      comfort: 3,
      reliability: 3
    },
    excludeOptions: {
      currentRecommendations: false,
      similarModels: false
    }
  });

  const [activeTab, setActiveTab] = useState<'budget' | 'preferences' | 'priorities' | 'advanced'>('budget');

  if (!isOpen) return null;

  // 현재 추천의 통계
  const currentStats = {
    avgPrice: Math.round(currentRecommendations.reduce((sum, v) => sum + v.price, 0) / currentRecommendations.length),
    priceRange: {
      min: Math.min(...currentRecommendations.map(v => v.price)),
      max: Math.max(...currentRecommendations.map(v => v.price))
    },
    avgYear: Math.round(currentRecommendations.reduce((sum, v) => sum + v.modelyear, 0) / currentRecommendations.length),
    brands: [...new Set(currentRecommendations.map(v => v.manufacturer))],
    avgScore: Math.round(currentRecommendations.reduce((sum, v) => sum + v.suitabilityScore, 0) / currentRecommendations.length)
  };

  const handlePriorityChange = (priority: keyof typeof refinementOptions.priorities, value: number) => {
    setRefinementOptions(prev => ({
      ...prev,
      priorities: {
        ...prev.priorities,
        [priority]: value
      }
    }));
  };

  const handleSubmit = () => {
    onRefine(refinementOptions);
    onClose();
  };

  const quickRefinements = [
    {
      title: '💰 더 저렴한 옵션',
      description: '예산을 20% 낮춰서 재검색',
      action: () => setRefinementOptions(prev => ({
        ...prev,
        budget: {
          max: Math.round(currentStats.avgPrice * 0.8),
          flexibility: 'flexible'
        }
      }))
    },
    {
      title: '🚗 더 최신 차량',
      description: '3년 이내 최신 모델 위주',
      action: () => setRefinementOptions(prev => ({
        ...prev,
        agePreference: {
          minYear: new Date().getFullYear() - 3,
          priority: 'newest'
        }
      }))
    },
    {
      title: '🏆 다른 브랜드',
      description: '현재 추천과 다른 브랜드',
      action: () => setRefinementOptions(prev => ({
        ...prev,
        brandPreferences: {
          excluded: currentStats.brands,
          preferred: [],
          openToAlternatives: true
        }
      }))
    },
    {
      title: '⚡ 완전 새로운 관점',
      description: '현재 추천을 제외하고 재분석',
      action: () => setRefinementOptions(prev => ({
        ...prev,
        excludeOptions: {
          currentRecommendations: true,
          similarModels: true
        }
      }))
    }
  ];

  const priorityLabels = {
    economy: { label: '경제성', icon: '💰', description: '구매/유지비용 최적화' },
    performance: { label: '성능', icon: '🚀', description: '주행성능과 파워' },
    safety: { label: '안전성', icon: '🛡️', description: '안전 기능과 신뢰성' },
    comfort: { label: '편의성', icon: '🛋️', description: '승차감과 편의기능' },
    reliability: { label: '신뢰성', icon: '⭐', description: '브랜드 신뢰도와 내구성' }
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/50 backdrop-blur-sm p-4" onClick={onClose}>
      <div className="bg-white rounded-2xl shadow-2xl w-full max-w-4xl h-[90vh] overflow-hidden flex flex-col" onClick={(e) => e.stopPropagation()}>

        {/* 헤더 */}
        <div className="bg-gradient-to-r from-blue-600 to-purple-600 text-white p-6 flex-shrink-0">
          <div className="flex items-center justify-between">
            <div className="flex items-center space-x-4">
              <div className="bg-white/20 p-3 rounded-xl">
                <Sliders className="w-6 h-6" />
              </div>
              <div>
                <h2 className="text-2xl font-bold">맞춤 추천 세부 조정</h2>
                <p className="text-sm opacity-90">
                  {currentPersona ? `${currentPersona}님` : '고객님'}의 완벽한 차량을 찾기 위해 세부 조건을 조정해보세요
                </p>
              </div>
            </div>
            <button
              onClick={onClose}
              className="p-2 hover:bg-white/20 rounded-lg transition-colors"
            >
              <X className="w-6 h-6" />
            </button>
          </div>
        </div>

        {/* 현재 추천 요약 */}
        <div className="p-6 bg-gradient-to-r from-gray-50 to-blue-50 border-b border-gray-200 flex-shrink-0">
          <h3 className="text-lg font-bold text-gray-800 mb-4">📊 현재 추천 분석</h3>
