                    <option value="gasoline">가솔린</option>
                    <option value="hybrid">하이브리드</option>
                    <option value="electric">전기차</option>
                    <option value="diesel">디젤</option>
                  </select>
                </div>
              </div>
            </div>
          )}

          {activeTab === 'priorities' && (
            <div className="space-y-6">
              <h3 className="text-xl font-bold text-gray-800">⚖️ 우선순위 조정</h3>
              <p className="text-gray-600">각 요소의 중요도를 1(낮음)부터 5(높음)까지 설정해주세요</p>

              <div className="space-y-4">
                {Object.entries(priorityLabels).map(([key, config]) => (
                  <div key={key} className="bg-gray-50 p-6 rounded-xl">
                    <div className="flex items-center justify-between mb-4">
                      <div className="flex items-center space-x-3">
                        <span className="text-2xl">{config.icon}</span>
                        <div>
                          <div className="font-bold text-gray-800">{config.label}</div>
                          <div className="text-sm text-gray-600">{config.description}</div>
