                    </div>
                    <input
                      type="range"
                      min="1"
                      max="5"
                      value={refinementOptions.priorities[key as keyof typeof refinementOptions.priorities]}
                      onChange={(e) => handlePriorityChange(key as keyof typeof refinementOptions.priorities, parseInt(e.target.value))}
                      className="w-full h-2 bg-gray-200 rounded-lg appearance-none cursor-pointer"
                    />
                    <div className="flex justify-between text-xs text-gray-500 mt-2">
                      <span>낮음</span>
                      <span>보통</span>
                      <span>높음</span>
                    </div>
                  </div>
                ))}
              </div>
            </div>
          )}

          {activeTab === 'advanced' && (
            <div className="space-y-6">
              <h3 className="text-xl font-bold text-gray-800">🔧 고급 설정</h3>

              <div className="space-y-4">
                <div className="bg-gray-50 p-6 rounded-xl">
                  <h4 className="font-bold text-gray-800 mb-4">제외 옵션</h4>
                  <div className="space-y-3">
                    <label className="flex items-center space-x-3">
                      <input
                        type="checkbox"
                        checked={refinementOptions.excludeOptions?.currentRecommendations}
                        onChange={(e) => setRefinementOptions(prev => ({
                          ...prev,
                          excludeOptions: {
                            ...prev.excludeOptions,
                            currentRecommendations: e.target.checked
                          }
                        }))}
                        className="w-4 h-4 text-blue-600"
                      />
                      <span className="text-gray-700">현재 추천된 차량들 제외</span>
                    </label>
                    <label className="flex items-center space-x-3">
                      <input
                        type="checkbox"
                        checked={refinementOptions.excludeOptions?.similarModels}
                        onChange={(e) => setRefinementOptions(prev => ({
                          ...prev,
                          excludeOptions: {
                            ...prev.excludeOptions,
                            similarModels: e.target.checked
                          }
                        }))}
                        className="w-4 h-4 text-blue-600"
                      />
                      <span className="text-gray-700">유사한 모델들 제외하고 다양화</span>
                    </label>
                  </div>
                </div>

                <div className="bg-gray-50 p-6 rounded-xl">
                  <label className="block text-sm font-medium text-gray-700 mb-2">추가 요청사항</label>
                  <textarea
                    placeholder="예: 골프백이 들어가는 차량, 아이들과 여행하기 좋은 차량, 연비가 특히 좋은 차량 등..."
                    className="w-full p-3 border border-gray-300 rounded-lg resize-none h-24"
                    onChange={(e) => setRefinementOptions(prev => ({
                      ...prev,
                      customRequest: e.target.value
                    }))}
                  />
                </div>
              </div>
            </div>
          )}
        </div>

        {/* 하단 액션 버튼 */}
        <div className="border-t border-gray-200 p-6 bg-gray-50 flex justify-between flex-shrink-0">
          <button
            onClick={onClose}
            className="px-6 py-3 border border-gray-300 text-gray-700 rounded-xl hover:bg-gray-100 transition-colors"
          >
            취소
          </button>
          <button
            onClick={handleSubmit}
            className="flex items-center space-x-2 px-8 py-3 bg-gradient-to-r from-blue-600 to-purple-600 text-white rounded-xl hover:from-blue-700 hover:to-purple-700 transition-all shadow-lg hover:shadow-xl"
          >
            <RefreshCw className="w-5 h-5" />
            <span className="font-bold">새로운 추천 받기</span>
          </button>
        </div>
      </div>
    </div>
  );
}

'use client';

import React, { useState, useEffect } from 'react';
import { Car, Gauge, MapPin, ExternalLink, Eye } from 'lucide-react';

interface VehicleRecommendation {
  manufacturer: string;
  model: string;
  modelyear: number;
  price: number;
  distance: number;
  location: string;
  fueltype: string;
  detailurl?: string;
  photo?: string;
  platform?: string;
  originprice?: number;
  suitabilityScore: number;
  rank: number;
  recommendationReason?: string;
}

interface SimpleVehicleCardProps {
  vehicle: VehicleRecommendation;
  rank: number;
  onDetailClick: () => void;
}

export default function SimpleVehicleCard({ vehicle, rank, onDetailClick }: SimpleVehicleCardProps) {
  const [imageError, setImageError] = useState(false);
  const [realVehicleImage, setRealVehicleImage] = useState<string | null>(null);

  const getRankConfig = (rank: number) => {
    switch (rank) {
      case 1:
        return {
          gradient: 'from-yellow-400 to-orange-500',
          icon: '🥇',
          label: '1순위',
          badgeBg: 'bg-yellow-50',
          badgeText: 'text-yellow-800',
          border: 'border-yellow-300'
        };
      case 2:
        return {
          gradient: 'from-gray-400 to-gray-600',
          icon: '🥈',
          label: '2순위',
          badgeBg: 'bg-gray-50',
          badgeText: 'text-gray-800',
          border: 'border-gray-300'
        };
      case 3:
        return {
          gradient: 'from-orange-600 to-red-500',
          icon: '🥉',
          label: '3순위',
          badgeBg: 'bg-orange-50',
          badgeText: 'text-orange-800',
          border: 'border-orange-300'
        };
      default:
        return {
          gradient: 'from-blue-400 to-blue-600',
          icon: '⭐',
          label: '추천',
          badgeBg: 'bg-blue-50',
          badgeText: 'text-blue-800',
          border: 'border-blue-300'
        };
    }
  };

  const rankConfig = getRankConfig(rank);

  const buildEncarImageUrl = (photoPath: string) => {
    if (photoPath.startsWith('http')) return photoPath;
    const encarImageServers = [
      'https://img1.encar.com',
      'https://img2.encar.com',
      'https://img3.encar.com',
      'https://img4.encar.com'
    ];
    const randomServer = encarImageServers[Math.floor(Math.random() * encarImageServers.length)];
    const cleanPath = photoPath.startsWith('/') ? photoPath : `/${photoPath}`;
    return `${randomServer}${cleanPath}`;
  };

  useEffect(() => {
    if (vehicle.photo) {
      const imageUrl = buildEncarImageUrl(vehicle.photo);
      setRealVehicleImage(imageUrl);
    }
  }, [vehicle.photo]);

  const handleDetailLinkClick = (e: React.MouseEvent) => {
    e.stopPropagation();
    if (vehicle.detailurl) {
      window.open(vehicle.detailurl, '_blank');
    }
  };

  return (
    <div className="flex-shrink-0 w-72 bg-white rounded-xl border-2 border-gray-200 shadow-md hover:shadow-xl transition-all duration-300 overflow-hidden group snap-start">
      {/* 순위 뱃지 */}
      <div className={`bg-gradient-to-r ${rankConfig.gradient} px-3 py-2 text-white relative`}>
        <div className="flex items-center justify-between">
          <div className="flex items-center space-x-2">
            <span className="text-lg">{rankConfig.icon}</span>
            <span className="font-bold text-sm">{rankConfig.label} 추천</span>
          </div>
          <div className="flex items-center space-x-1 bg-white/20 px-2 py-1 rounded-full">
            <span className="text-xs font-bold">⭐ {vehicle.suitabilityScore}</span>
          </div>
        </div>
      </div>

      {/* 차량 이미지 */}
      <div className="aspect-square bg-gradient-to-br from-gray-100 to-gray-200 relative overflow-hidden">
        {realVehicleImage && !imageError ? (
          <img
            src={`/api/proxy-image?url=${encodeURIComponent(realVehicleImage)}`}
            alt={`${vehicle.manufacturer} ${vehicle.model}`}
            className="w-full h-full object-cover group-hover:scale-105 transition-transform duration-300"
            onError={() => setImageError(true)}
          />
        ) : (
          <div className="w-full h-full flex items-center justify-center">
            <div className="text-center">
              <div className="w-16 h-16 mx-auto mb-2 bg-gradient-to-br from-blue-400 to-blue-600 rounded-lg flex items-center justify-center">
                <Car className="w-8 h-8 text-white" />
              </div>
              <p className="text-sm font-medium text-gray-700">{vehicle.manufacturer}</p>
              <p className="text-xs text-gray-500">{vehicle.model}</p>
            </div>
          </div>
        )}
      </div>

      {/* 차량 정보 */}
      <div className="p-3 space-y-2">
        {/* 차량명 */}
        <h3 className="font-bold text-gray-900 text-base truncate">
          {vehicle.manufacturer} {vehicle.model}
        </h3>

        {/* 스펙 정보 */}
        <div className="space-y-1 text-xs text-gray-600">
          <div className="flex items-center justify-between">
            <span className="flex items-center space-x-1">
              <span>📅</span>
              <span>{vehicle.modelyear}년</span>
            </span>
            <span className="flex items-center space-x-1">
              <Gauge className="w-3 h-3" />
              <span>{(vehicle.distance / 10000).toFixed(1)}만km</span>
            </span>
          </div>
          <div className="flex items-center justify-between">
            <span className="flex items-center space-x-1">
              <span>⛽</span>
              <span>{vehicle.fueltype}</span>
            </span>
            <span className="flex items-center space-x-1">
              <MapPin className="w-3 h-3" />
              <span className="truncate max-w-[100px]">{vehicle.location}</span>
            </span>
          </div>
        </div>

        {/* 가격 */}
        <div className="pt-2 border-t border-gray-200">
          <div className="flex items-center justify-between">
            <div>
              <div className="text-lg font-bold text-blue-600">
                {vehicle.price?.toLocaleString()}만원
              </div>
              {vehicle.originprice && vehicle.originprice > vehicle.price && (
                <div className="text-xs text-gray-500 line-through">
                  {vehicle.originprice.toLocaleString()}만원
                </div>
              )}
            </div>
            {vehicle.originprice && vehicle.originprice > vehicle.price && (
              <div className="bg-red-100 text-red-700 px-2 py-1 rounded text-xs font-bold">
                -{Math.round((1 - vehicle.price / vehicle.originprice) * 100)}%
              </div>
            )}
          </div>
        </div>

        {/* 버튼 */}
        <div className="pt-2 flex gap-2">
          {vehicle.detailurl && (
            <button
              onClick={handleDetailLinkClick}
              className="flex-1 px-3 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 transition-colors text-xs font-medium flex items-center justify-center space-x-1"
            >
              <ExternalLink className="w-3 h-3" />
              <span>실매물</span>
            </button>
          )}
          <button
            onClick={onDetailClick}
            className="flex-1 px-3 py-2 bg-gradient-to-r from-purple-600 to-blue-600 text-white rounded-lg hover:from-purple-700 hover:to-blue-700 transition-colors text-xs font-medium flex items-center justify-center space-x-1"
          >
            <Eye className="w-3 h-3" />
            <span>자세히</span>
          </button>
        </div>
      </div>
    </div>
  );
}

'use client';

interface SkeletonLoaderProps {
  variant?: 'card' | 'text' | 'button' | 'progress';
  width?: string;
  height?: string;
  className?: string;
  count?: number;
}

export default function SkeletonLoader({
  variant = 'card',
  width,
  height,
  className = '',
  count = 1
}: SkeletonLoaderProps) {

  const SkeletonItem = ({ index }: { index: number }) => {
    const baseClass = "animate-pulse bg-gradient-to-r from-gray-200 via-gray-100 to-gray-200 bg-[length:200%_100%] rounded";

    switch (variant) {
      case 'card':
        return (
          <div className={`${baseClass} ${className}`} style={{ width, height }}>
            <div className="p-6 space-y-4">
              {/* Image skeleton */}
              <div className="w-full h-36 bg-gray-300 rounded-lg mb-4"></div>

              {/* Title skeleton */}
              <div className="space-y-2">
                <div className="h-6 bg-gray-300 rounded w-3/4"></div>
                <div className="h-4 bg-gray-300 rounded w-1/2"></div>
              </div>

              {/* Price skeleton */}
              <div className="h-8 bg-gray-300 rounded w-1/3"></div>

              {/* Details skeleton */}
              <div className="grid grid-cols-3 gap-4">
                <div className="space-y-2">
                  <div className="h-4 bg-gray-300 rounded w-full"></div>
                  <div className="h-3 bg-gray-300 rounded w-3/4"></div>
                </div>
                <div className="space-y-2">
                  <div className="h-4 bg-gray-300 rounded w-full"></div>
                  <div className="h-3 bg-gray-300 rounded w-3/4"></div>
                </div>
                <div className="space-y-2">
                  <div className="h-4 bg-gray-300 rounded w-full"></div>
                  <div className="h-3 bg-gray-300 rounded w-3/4"></div>
                </div>
              </div>

              {/* Button skeleton */}
              <div className="h-10 bg-gray-300 rounded w-full"></div>
            </div>
          </div>
        );

      case 'text':
        return (
          <div className={`${baseClass} h-4 ${className}`} style={{ width: width || '100%', height }}></div>
        );

      case 'button':
        return (
          <div className={`${baseClass} h-10 ${className}`} style={{ width: width || '120px', height }}></div>
        );

      case 'progress':
        return (
          <div className={`${className}`}>
            <div className="bg-white rounded-xl shadow-lg border border-gray-200 p-6 max-w-2xl mx-auto">
              {/* Header skeleton */}
              <div className="text-center mb-6">
                <div className="h-6 bg-gray-300 rounded w-3/4 mx-auto mb-2"></div>
                <div className="h-4 bg-gray-300 rounded w-1/2 mx-auto"></div>
              </div>

              {/* Agent cards skeleton */}
              <div className="mb-6">
                <div className="h-5 bg-gray-300 rounded w-1/3 mb-4"></div>
                <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                  {[1, 2, 3].map((i) => (
                    <div key={i} className="bg-gray-50 rounded-lg p-4 border-l-4 border-gray-300">
                      <div className="flex items-center justify-between mb-2">
                        <div className="flex items-center space-x-2">
                          <div className="w-8 h-8 bg-gray-300 rounded-full"></div>
                          <div>
                            <div className="h-4 bg-gray-300 rounded w-16 mb-1"></div>
                            <div className="h-3 bg-gray-300 rounded w-12"></div>
                          </div>
                        </div>
                        <div className="h-4 bg-gray-300 rounded w-8"></div>
                      </div>
                      <div className="w-full bg-gray-200 rounded-full h-2 mb-2">
                        <div className="h-2 bg-gray-300 rounded-full w-1/2"></div>
                      </div>
                      <div className="h-3 bg-gray-300 rounded w-3/4"></div>
                    </div>
                  ))}
                </div>
              </div>

              {/* Progress bar skeleton */}
              <div className="mb-6">
                <div className="flex justify-between mb-2">
                  <div className="h-3 bg-gray-300 rounded w-12"></div>
                  <div className="h-3 bg-gray-300 rounded w-8"></div>
                </div>
                <div className="w-full bg-gray-200 rounded-full h-2">
                  <div className="h-2 bg-gradient-to-r from-blue-300 to-purple-300 rounded-full w-1/3"></div>
                </div>
              </div>

              {/* Steps skeleton */}
              <div className="space-y-4 mb-6">
                {[1, 2, 3].map((i) => (
                  <div key={i} className="flex items-center space-x-4">
                    <div className="w-10 h-10 bg-gray-300 rounded-full"></div>
                    <div className="flex-1">
                      <div className="h-4 bg-gray-300 rounded w-1/4 mb-1"></div>
                      <div className="h-3 bg-gray-300 rounded w-3/4"></div>
                    </div>
                  </div>
                ))}
              </div>

              {/* Message skeleton */}
              <div className="bg-gray-50 rounded-lg p-4">
                <div className="flex items-center space-x-2">
                  <div className="w-2 h-2 bg-gray-300 rounded-full"></div>
                  <div className="h-3 bg-gray-300 rounded w-1/2"></div>
                </div>
              </div>
            </div>
          </div>
        );

      default:
        return (
          <div className={`${baseClass} ${className}`} style={{ width, height }}></div>
        );
    }
  };

  return (
    <>
      {Array.from({ length: count }, (_, index) => (
        <SkeletonItem key={index} index={index} />
      ))}
    </>
  );
}

// Individual skeleton components for convenience
export const VehicleCardSkeleton = () => <SkeletonLoader variant="card" />;
export const TextSkeleton = ({ width }: { width?: string }) => <SkeletonLoader variant="text" width={width} />;
export const ButtonSkeleton = () => <SkeletonLoader variant="button" />;
export const ProgressSkeleton = () => <SkeletonLoader variant="progress" />;

'use client';

import { useState, useEffect } from 'react';
import { Car, Heart, DollarSign, Star, Fuel, Users, Zap } from 'lucide-react';

interface QuickAction {
  id: string;
  icon: string;
  title: string;
  description: string;
  query: string;
  category: 'budget' | 'purpose' | 'feature';
  priority: number;
  isPersonalized?: boolean;
}

interface SmartRecommendationActionsProps {
  onActionSelect: (query: string) => void;
  userPreferences?: {
    budgetRange?: [number, number];
    preferredBrands?: string[];
    usagePatterns?: string[];
  };
}

export default function SmartRecommendationActions({
  onActionSelect,
  userPreferences
}: SmartRecommendationActionsProps) {
  const [actions, setActions] = useState<QuickAction[]>([]);
  const [isLoading, setIsLoading] = useState(true);

  useEffect(() => {
    generateQuickActions();
  }, [userPreferences]);

  const generateQuickActions = async () => {
    setIsLoading(true);

    // 실용적인 기본 액션들
    const baseActions: QuickAction[] = [
      {
        id: 'budget_friendly',
        icon: '💰',
        title: '가성비 좋은 차량',
        description: '가격 대비 성능이 뛰어난 차량',
        query: '가성비 좋은 차량 추천해주세요',
        category: 'budget',
        priority: 10
      },
      {
        id: 'family_car',
        icon: '👨‍👩‍👧‍👦',
        title: '가족용 차량',
        description: '안전하고 넓은 가족용 차량',
        query: '가족용 차량 추천해주세요',
        category: 'purpose',
        priority: 9
      },
      {
        id: 'fuel_efficient',
        icon: '⛽',
        title: '연비 좋은 차량',
        description: '기름값 절약할 수 있는 차량',
        query: '연비 좋은 차량 추천해주세요',
        category: 'feature',
        priority: 8
      },
      {
        id: 'compact_city',
        icon: '🏙️',
        title: '도심 운전용',
        description: '주차 편하고 운전하기 쉬운 차량',
        query: '도심 운전하기 좋은 차량 추천해주세요',
        category: 'purpose',
        priority: 7
      },
      {
        id: 'luxury_comfort',
        icon: '✨',
        title: '고급 차량',
        description: '편안하고 품격 있는 차량',
        query: '고급스럽고 편안한 차량 추천해주세요',
        category: 'feature',
        priority: 6
      },
      {
        id: 'first_car',
        icon: '🔰',
        title: '첫 차 추천',
        description: '초보자에게 적합한 차량',
        query: '첫 차로 좋은 차량 추천해주세요',
        category: 'purpose',
        priority: 8
      }
    ];

    // 사용자 맞춤 액션 생성
    const personalizedActions = await generatePersonalizedActions();

    // 모든 액션을 우선순위별로 정렬
    const allActions = [...baseActions, ...personalizedActions].sort((a, b) => b.priority - a.priority);

    setActions(allActions.slice(0, 6)); // 최대 6개만 표시
    setIsLoading(false);
  };

  const generatePersonalizedActions = async (): Promise<QuickAction[]> => {
    const personalizedActions: QuickAction[] = [];

    // 예산 기반 맞춤
    if (userPreferences?.budgetRange) {
      const [min, max] = userPreferences.budgetRange;
      personalizedActions.push({
        id: 'personalized_budget',
        icon: '💳',
        title: `${min}-${max}만원 차량`,
        description: `회원님 예산에 맞는 차량`,
        query: `${min}만원에서 ${max}만원 사이 차량 추천해주세요`,
        category: 'budget',
        priority: 9,
        isPersonalized: true
      });
    }

    // 브랜드 선호도 기반
    if (userPreferences?.preferredBrands?.length) {
      const brands = userPreferences.preferredBrands.slice(0, 2).join(', ');
      personalizedActions.push({
        id: 'personalized_brands',
        icon: '🏷️',
        title: `${brands} 브랜드`,
        description: '선호하시는 브랜드 차량',
        query: `${brands} 브랜드 차량 추천해주세요`,
        category: 'feature',
        priority: 8,
        isPersonalized: true
      });
    }

    // 용도별 맞춤
    if (userPreferences?.usagePatterns?.length) {
      const pattern = userPreferences.usagePatterns[0];
      personalizedActions.push({
        id: 'personalized_usage',
        icon: '🚗',
        title: `${pattern} 차량`,
        description: '회원님 용도에 맞는 차량',
        query: `${pattern}용 차량 추천해주세요`,
        category: 'purpose',
        priority: 7,
        isPersonalized: true
      });
    }

    return personalizedActions;
  };

  const getCategoryColor = (category: string) => {
    switch (category) {
      case 'budget': return 'bg-green-50 border-green-200';
      case 'purpose': return 'bg-blue-50 border-blue-200';
      case 'feature': return 'bg-purple-50 border-purple-200';
      default: return 'bg-gray-50 border-gray-200';
    }
  };

  if (isLoading) {
    return (
      <div className="p-4 border-t border-gray-100">
        <h3 className="text-sm font-medium text-gray-900 mb-3">
          빠른 추천 로딩 중...
        </h3>
        <div className="space-y-2">
          {[1, 2, 3].map(i => (
            <div key={i} className="animate-pulse h-16 bg-gray-200 rounded-lg"></div>
          ))}
        </div>
      </div>
    );
  }

  return (
    <div className="p-4 border-t border-gray-100">
      <div className="flex items-center justify-between mb-3">
        <h3 className="text-sm font-medium text-gray-900 flex items-center">
          <Zap className="w-4 h-4 mr-2 text-blue-600" />
          빠른 추천
        </h3>
        <div className="text-xs text-gray-600">
