'use client';

/**
 * 🎯 TOPSIS 점수 배지
 * 기존 차량 카드에 자연스럽게 추가할 수 있는 TOPSIS 점수 표시
 */

import React from 'react';
import { BarChart3, Award, Star } from 'lucide-react';

interface TOPSISScoreBadgeProps {
  score: number;
  rank?: number;
  showDetails?: boolean;
  compact?: boolean;
}

const TOPSISScoreBadge: React.FC<TOPSISScoreBadgeProps> = ({
  score,
  rank,
  showDetails = false,
  compact = false
}) => {
  const getScoreColor = (score: number) => {
    if (score >= 0.85) return 'bg-green-500 text-white';
    if (score >= 0.70) return 'bg-blue-500 text-white';
    if (score >= 0.55) return 'bg-yellow-500 text-black';
    return 'bg-gray-500 text-white';
  };

  const getScoreLabel = (score: number) => {
    if (score >= 0.85) return '최적';
    if (score >= 0.70) return '우수';
    if (score >= 0.55) return '양호';
    return '보통';
  };

  const getRankIcon = (rank?: number) => {
    if (rank === 1) return <Award className="w-3 h-3 text-yellow-500" />;
    if (rank === 2) return <Star className="w-3 h-3 text-gray-400" />;
    if (rank === 3) return <Star className="w-3 h-3 text-orange-400" />;
    return <BarChart3 className="w-3 h-3" />;
  };

  if (compact) {
    return (
      <div className="flex items-center gap-1">
        {rank && getRankIcon(rank)}
        <div className={`px-2 py-1 rounded-full text-xs font-medium ${getScoreColor(score)}`}>
          {Math.round(score * 100)}점
        </div>
      </div>
    );
  }

  return (
    <div className="bg-white border border-gray-200 rounded-lg p-3 space-y-2">
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-2">
          <BarChart3 className="w-4 h-4 text-green-600" />
          <span className="text-sm font-medium text-gray-700">TOPSIS 종합 점수</span>
        </div>
        {rank && (
          <div className="flex items-center gap-1">
            {getRankIcon(rank)}
            <span className="text-xs text-gray-600">{rank}위</span>
          </div>
        )}
      </div>

      <div className="space-y-1">
        <div className="flex items-center justify-between">
          <div className={`px-3 py-1 rounded-full text-sm font-semibold ${getScoreColor(score)}`}>
            {Math.round(score * 100)}점
          </div>
          <span className="text-sm text-gray-600">{getScoreLabel(score)}</span>
        </div>

        {showDetails && (
          <div className="text-xs text-gray-500 mt-2">
            다기준 평가: 가격, 성능, 브랜드, 연비, 안전성, 디자인
          </div>
        )}
      </div>
    </div>
  );
};

export default TOPSISScoreBadge;

'use client';

import { useState, useEffect } from 'react';
import { MessageSquare, Clock, Trash2, Star } from 'lucide-react';

interface SessionHistory {
  id: string;
  title: string;
  timestamp: Date;
  query: string;
  vehicleCount?: number;
  isStarred?: boolean;
  analysisType?: 'simple' | 'comprehensive' | 'paper_based';
}

interface UserSessionHistoryProps {
  currentSessionId?: string;
  onSessionSelect?: (session: SessionHistory) => void;
  onNewSession?: () => void;
}

export default function UserSessionHistory({
  currentSessionId,
  onSessionSelect,
  onNewSession
}: UserSessionHistoryProps) {
  const [sessions, setSessions] = useState<SessionHistory[]>([]);
  const [isLoading, setIsLoading] = useState(true);

  // 세션 히스토리 로드
  useEffect(() => {
    loadSessionHistory();
  }, []);

  const loadSessionHistory = () => {
    try {
      const storedSessions = localStorage.getItem('carfin_session_history');
      if (storedSessions) {
        const parsed = JSON.parse(storedSessions);
        // 날짜 문자열을 Date 객체로 변환
        const sessions = parsed.map((session: any) => ({
          ...session,
          timestamp: new Date(session.timestamp)
        }));
        // 최신순으로 정렬
        sessions.sort((a: SessionHistory, b: SessionHistory) =>
          b.timestamp.getTime() - a.timestamp.getTime()
        );
        setSessions(sessions.slice(0, 10)); // 최대 10개만 표시
      }
    } catch (error) {
      console.error('세션 히스토리 로드 실패:', error);
    } finally {
      setIsLoading(false);
    }
  };

  // 새 세션 저장
  const saveSession = (query: string, analysisType: 'simple' | 'comprehensive' | 'paper_based' = 'simple') => {
    const newSession: SessionHistory = {
      id: `session_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`,
      title: generateSessionTitle(query),
      timestamp: new Date(),
      query,
      analysisType
    };

    const updatedSessions = [newSession, ...sessions].slice(0, 10);
    setSessions(updatedSessions);

    try {
      localStorage.setItem('carfin_session_history', JSON.stringify(updatedSessions));
    } catch (error) {
      console.error('세션 저장 실패:', error);
    }

    return newSession.id;
  };

  // 세션 삭제
  const deleteSession = (sessionId: string) => {
    const updatedSessions = sessions.filter(s => s.id !== sessionId);
    setSessions(updatedSessions);

    try {
      localStorage.setItem('carfin_session_history', JSON.stringify(updatedSessions));
    } catch (error) {
      console.error('세션 삭제 실패:', error);
    }
  };

  // 세션 즐겨찾기 토글
  const toggleStar = (sessionId: string) => {
    const updatedSessions = sessions.map(session =>
      session.id === sessionId
        ? { ...session, isStarred: !session.isStarred }
        : session
    );
    setSessions(updatedSessions);

    try {
      localStorage.setItem('carfin_session_history', JSON.stringify(updatedSessions));
    } catch (error) {
      console.error('즐겨찾기 업데이트 실패:', error);
    }
  };

  // 질문에서 세션 제목 생성
  const generateSessionTitle = (query: string): string => {
    const keywords = [
      { patterns: ['SUV', 'suv'], title: 'SUV 추천' },
      { patterns: ['세단', 'sedan'], title: '세단 추천' },
      { patterns: ['가족', 'family'], title: '가족용 차량' },
      { patterns: ['연비', '기름값'], title: '연비 좋은 차' },
      { patterns: ['첫차', '첫 차'], title: '첫차 추천' },
      { patterns: ['중고', '중고차'], title: '중고차 상담' },
      { patterns: ['BMW', 'bmw'], title: 'BMW 차량' },
      { patterns: ['현대', 'hyundai'], title: '현대 차량' },
      { patterns: ['기아', 'kia'], title: '기아 차량' },
    ];

    for (const keyword of keywords) {
      if (keyword.patterns.some(pattern => query.includes(pattern))) {
        return keyword.title;
      }
    }

    // 예산 관련 키워드 추출
    const budgetMatch = query.match(/(\d+)만원|(\d+)천만원/);
    if (budgetMatch) {
      const amount = budgetMatch[1] || (parseInt(budgetMatch[2]) * 1000);
      return `${amount}만원대 차량`;
    }

    // 기본값: 질문의 첫 10글자
    return query.length > 10 ? query.substring(0, 10) + '...' : query;
  };

  const formatTimeAgo = (timestamp: Date): string => {
    const now = new Date();
    const diffMs = now.getTime() - timestamp.getTime();
    const diffMins = Math.floor(diffMs / (1000 * 60));
    const diffHours = Math.floor(diffMins / 60);
    const diffDays = Math.floor(diffHours / 24);

    if (diffMins < 1) return '방금 전';
    if (diffMins < 60) return `${diffMins}분 전`;
    if (diffHours < 24) return `${diffHours}시간 전`;
    if (diffDays === 1) return '어제';
    if (diffDays < 7) return `${diffDays}일 전`;
    return timestamp.toLocaleDateString('ko-KR');
  };

  const getAnalysisTypeIcon = (type?: string) => {
    switch (type) {
      case 'comprehensive': return '🧠';
      case 'paper_based': return '📚';
      default: return '💬';
    }
  };

  // 컴포넌트에서 사용할 수 있도록 함수들을 외부로 노출
  useEffect(() => {
    // 전역 함수로 등록 (다른 컴포넌트에서 사용 가능)
    (window as any).carfinSaveSession = saveSession;
  }, [sessions]);

  if (isLoading) {
    return (
      <div className="p-4">
        <div className="animate-pulse space-y-3">
          {[1, 2, 3].map(i => (
            <div key={i} className="h-16 bg-gray-200 rounded-lg"></div>
          ))}
        </div>
      </div>
    );
  }

  return (
    <div className="p-4">
      <div className="flex items-center justify-between mb-3">
        <h3 className="text-sm font-medium text-gray-900 flex items-center">
          <MessageSquare className="w-4 h-4 mr-2" />
          최근 상담 ({sessions.length})
        </h3>
        {onNewSession && (
          <button
            onClick={onNewSession}
            className="text-xs text-blue-600 hover:text-blue-800 font-medium"
          >
            + 새 상담
          </button>
        )}
      </div>

      {sessions.length === 0 ? (
        <div className="text-center py-8">
          <MessageSquare className="w-8 h-8 text-gray-400 mx-auto mb-3" />
          <p className="text-sm text-gray-600">아직 상담 기록이 없습니다</p>
          <p className="text-xs text-gray-500 mt-1">
            첫 질문을 시작해보세요!
          </p>
        </div>
      ) : (
        <div className="space-y-1 max-h-80 overflow-y-auto">
          {sessions.map((session) => (
            <div
              key={session.id}
              className={`group p-3 rounded-lg cursor-pointer transition-all duration-200 ${
                session.id === currentSessionId
                  ? 'bg-blue-50 border border-blue-200 shadow-sm'
                  : 'hover:bg-gray-50 border border-transparent'
              }`}
              onClick={() => onSessionSelect?.(session)}
            >
              <div className="flex items-start justify-between">
                <div className="flex-1 min-w-0">
                  <div className="flex items-center space-x-2 mb-1">
                    <span className="text-sm">
                      {getAnalysisTypeIcon(session.analysisType)}
                    </span>
                    <div className="font-medium text-sm text-gray-900 truncate">
                      {session.title}
                    </div>
                    {session.isStarred && (
                      <Star className="w-3 h-3 text-yellow-500 fill-current" />
                    )}
                  </div>
                  <div className="text-xs text-gray-500 flex items-center">
                    <Clock className="w-3 h-3 mr-1" />
                    {formatTimeAgo(session.timestamp)}
                    {session.vehicleCount && (
                      <span className="ml-2 text-blue-600">
                        • {session.vehicleCount}대 추천
                      </span>
                    )}
                  </div>
                </div>

                <div className="flex items-center space-x-1 opacity-0 group-hover:opacity-100 transition-opacity">
                  <button
                    onClick={(e) => {
                      e.stopPropagation();
                      toggleStar(session.id);
                    }}
                    className="p-1 hover:bg-gray-200 rounded"
                    title={session.isStarred ? "즐겨찾기 해제" : "즐겨찾기 추가"}
                  >
                    <Star className={`w-3 h-3 ${
                      session.isStarred
                        ? 'text-yellow-500 fill-current'
                        : 'text-gray-400'
                    }`} />
                  </button>
                  <button
                    onClick={(e) => {
                      e.stopPropagation();
                      deleteSession(session.id);
                    }}
                    className="p-1 hover:bg-red-100 hover:text-red-600 rounded"
                    title="삭제"
                  >
                    <Trash2 className="w-3 h-3" />
                  </button>
                </div>
              </div>
            </div>
          ))}
        </div>
      )}

      {/* 저장 공간 사용량 표시 */}
      <div className="mt-4 pt-3 border-t border-gray-100">
        <div className="text-xs text-gray-500 text-center">
          {sessions.length}/10 세션 저장됨
        </div>
      </div>
    </div>
  );
}

'use client';

import React, { useState, useEffect } from 'react';
import {
  X,
  Car,
  DollarSign,
  BarChart3,
  AlertTriangle,
  Settings,
  Scale,
  Star,
  TrendingUp,
  TrendingDown,
  Award,
  Shield,
  Fuel,
  Calendar,
  MapPin,
  Wrench,
  Users,
  Zap,
  Target,
  CheckCircle,
  XCircle,
  MessageSquare,
  ThumbsUp,
  Eye,
  PieChart,
  Activity
} from 'lucide-react';
import { reviewSentimentAnalyzer } from '@/lib/review/ReviewSentimentAnalyzer';

interface Vehicle {
  id: string;
  vehicle_id?: string;
  vehicleid?: string;
  manufacturer: string;
  model: string;
  year: number;
  price: number;
  mileage?: number;
  distance?: number;
  fuel_type?: string;
  fuelType?: string;
  location?: string;
  imageUrl?: string;
  topsis_score?: number;
  personalized_score?: number;
}

interface VehicleAnalysisModalProps {
  isOpen: boolean;
  onClose: () => void;
  vehicle: Vehicle;
  topsisScore?: number;
  personalizedScore?: number;
  onRecommendAgain?: () => void;
}

interface TabData {
  id: string;
  label: string;
  icon: React.ReactNode;
  content: React.ReactNode;
}

export default function VehicleAnalysisModal({
  isOpen,
  onClose,
  vehicle,
  topsisScore = 85,
  personalizedScore = 92,
  onRecommendAgain
}: VehicleAnalysisModalProps) {
  const [activeTab, setActiveTab] = useState('overview');
  const [reviewData, setReviewData] = useState<any>(null);
  const [loading, setLoading] = useState(true);

  // 기본값 처리
  const vehicleId = vehicle.vehicle_id || vehicle.vehicleid || vehicle.id;
  const fuelType = vehicle.fuel_type || vehicle.fuelType || '가솔린';
  const mileage = vehicle.mileage || vehicle.distance || 0;

  // 리뷰 데이터 가져오기
  useEffect(() => {
    if (isOpen) {
      fetchReviewData();
    }
  }, [isOpen, vehicle.manufacturer, vehicle.model]);

  const fetchReviewData = async () => {
    setLoading(true);
    try {
      // 브랜드 신뢰도 및 모델 만족도 가져오기
      const [brandTrust, modelSatisfaction, insights] = await Promise.all([
        reviewSentimentAnalyzer.calculateBrandTrustScore(vehicle.manufacturer),
        reviewSentimentAnalyzer.calculateModelSatisfaction(vehicle.manufacturer, vehicle.model),
        reviewSentimentAnalyzer.generateVehicleInsights(vehicle.manufacturer, vehicle.model)
      ]);

      setReviewData({
        brandTrust,
        modelSatisfaction,
        insights
      });
    } catch (error) {
      console.error('리뷰 데이터 로딩 실패:', error);
      setReviewData({
        brandTrust: { manufacturer: vehicle.manufacturer, stars: 4, reviewCount: 0, brandReliability: 75, avgRating: 4.0, strongPoints: [], weakPoints: [] },
        modelSatisfaction: { model_group: vehicle.model, manufacturer: vehicle.manufacturer, overallSatisfaction: 75, categoryScores: { design: 75, performance: 75, maintenance: 75, option: 75 }, recommendationRate: 75, totalReviews: 0 },
        insights: []
      });
    } finally {
      setLoading(false);
    }
  };

  // TCO 계산
  const calculateDetailedTCO = () => {
    const basePrice = vehicle.price;
    const currentYear = new Date().getFullYear();
    const vehicleAge = currentYear - vehicle.year;

    // 연간 비용 계산
    const annualMaintenance = Math.max(80, vehicleAge * 25 + 50); // 차량 연식에 따른 정비비
    const annualFuel = 180; // 연간 연료비 (평균)
    const annualInsurance = 120; // 연간 보험료
    const annualTax = 30; // 연간 세금

    const totalAnnual = annualMaintenance + annualFuel + annualInsurance + annualTax;

    // 3년, 5년 TCO
    const tco3year = totalAnnual * 3;
    const tco5year = totalAnnual * 5;

    // 잔존가치 (감가상각)
    const depreciationRate = 0.15; // 연간 15% 감가상각
    const residualValue3year = basePrice * Math.pow(1 - depreciationRate, 3);
    const residualValue5year = basePrice * Math.pow(1 - depreciationRate, 5);

    return {
      basePrice,
      annual: {
        maintenance: annualMaintenance,
        fuel: annualFuel,
        insurance: annualInsurance,
        tax: annualTax,
        total: totalAnnual
      },
      tco3year: Math.round(tco3year),
      tco5year: Math.round(tco5year),
      residualValue3year: Math.round(residualValue3year),
      residualValue5year: Math.round(residualValue5year),
      totalCost3year: Math.round(basePrice + tco3year - residualValue3year),
      totalCost5year: Math.round(basePrice + tco5year - residualValue5year)
    };
  };

  const tcoData = calculateDetailedTCO();

  // 종합 분석 탭
  const OverviewTab = () => (
    <div className="space-y-6">
      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">

        {/* 종합 점수 */}
        <div className="bg-gradient-to-br from-blue-50 to-blue-100 p-6 rounded-xl">
          <h3 className="text-lg font-bold text-gray-900 mb-4 flex items-center">
            <Award className="w-5 h-5 mr-2 text-blue-600" />
            종합 평가 점수
          </h3>

          <div className="space-y-4">
            <div>
              <div className="flex items-center justify-between mb-2">
                <span className="text-sm font-medium">TOPSIS 전문 평가</span>
                <span className="text-xl font-bold text-green-600">{topsisScore}/100</span>
              </div>
              <div className="w-full bg-white rounded-full h-3">
                <div
                  className="bg-gradient-to-r from-green-400 to-green-600 h-3 rounded-full"
                  style={{ width: `${topsisScore}%` }}
                />
              </div>
            </div>

            <div>
              <div className="flex items-center justify-between mb-2">
                <span className="text-sm font-medium">개인화 매칭도</span>
                <span className="text-xl font-bold text-blue-600">{personalizedScore}%</span>
              </div>
              <div className="w-full bg-white rounded-full h-3">
                <div
                  className="bg-gradient-to-r from-blue-400 to-blue-600 h-3 rounded-full"
                  style={{ width: `${personalizedScore}%` }}
                />
              </div>
            </div>

            {reviewData && (
              <div>
                <div className="flex items-center justify-between mb-2">
                  <span className="text-sm font-medium">실제 만족도</span>
                  <span className="text-xl font-bold text-purple-600">{reviewData.modelSatisfaction.overallSatisfaction}%</span>
                </div>
                <div className="w-full bg-white rounded-full h-3">
                  <div
                    className="bg-gradient-to-r from-purple-400 to-purple-600 h-3 rounded-full"
                    style={{ width: `${reviewData.modelSatisfaction.overallSatisfaction}%` }}
                  />
                </div>
              </div>
            )}
          </div>
        </div>

        {/* 차량 기본 정보 */}
        <div className="bg-white border border-gray-200 p-6 rounded-xl">
          <h3 className="text-lg font-bold text-gray-900 mb-4 flex items-center">
            <Car className="w-5 h-5 mr-2 text-gray-600" />
            차량 정보
          </h3>

          <div className="space-y-3">
            <div className="flex justify-between">
              <span className="text-gray-600">브랜드/모델</span>
              <span className="font-medium">{vehicle.manufacturer} {vehicle.model}</span>
            </div>
            <div className="flex justify-between">
              <span className="text-gray-600">연식</span>
              <span className="font-medium">{vehicle.year}년</span>
            </div>
            <div className="flex justify-between">
              <span className="text-gray-600">주행거리</span>
              <span className="font-medium">{mileage.toLocaleString()}km</span>
            </div>
            <div className="flex justify-between">
              <span className="text-gray-600">연료</span>
              <span className="font-medium">{fuelType}</span>
            </div>
            <div className="flex justify-between">
              <span className="text-gray-600">가격</span>
              <span className="font-bold text-blue-600">{vehicle.price.toLocaleString()}만원</span>
            </div>
            {vehicle.location && (
              <div className="flex justify-between">
                <span className="text-gray-600">위치</span>
                <span className="font-medium">{vehicle.location}</span>
              </div>
            )}
          </div>
        </div>
      </div>

      {/* 강점/약점 분석 */}
      {reviewData && (
        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
          <div className="bg-green-50 p-6 rounded-xl">
            <h3 className="text-lg font-bold text-green-800 mb-4 flex items-center">
              <CheckCircle className="w-5 h-5 mr-2" />
              주요 강점
            </h3>
            <div className="space-y-2">
              {reviewData.brandTrust.strongPoints.length > 0 ? (
                reviewData.brandTrust.strongPoints.map((point: string, idx: number) => (
                  <div key={idx} className="flex items-center space-x-2">
                    <div className="w-2 h-2 bg-green-500 rounded-full" />
                    <span className="text-green-700">{point}</span>
                  </div>
                ))
              ) : (
