      </div>

      <div className="bg-gradient-to-br from-purple-50 to-purple-100 p-6 rounded-xl">
        <h3 className="text-lg font-bold text-gray-900 mb-4">🎯 경쟁 우위 요약</h3>
        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
