          <div>
            <h4 className="font-semibold text-orange-800 mb-2">⚠️ 고려사항</h4>
            <ul className="text-sm space-y-1">
              <li className="flex items-center"><Eye className="w-4 h-4 mr-2 text-orange-500" />차량 연식 및 주행거리 확인</li>
              <li className="flex items-center"><Eye className="w-4 h-4 mr-2 text-orange-500" />실제 연비 테스트 권장</li>
              <li className="flex items-center"><Eye className="w-4 h-4 mr-2 text-orange-500" />정비 이력 점검 필요</li>
            </ul>
          </div>
        </div>
      </div>
    </div>
  );

  const tabs: TabData[] = [
    {
      id: 'overview',
      label: '종합 분석',
      icon: <Award className="w-4 h-4" />,
      content: <OverviewTab />
    },
    {
      id: 'finance',
      label: '금융 분석',
      icon: <DollarSign className="w-4 h-4" />,
      content: <FinanceTab />
    },
    {
      id: 'reviews',
      label: '실제 리뷰',
      icon: <MessageSquare className="w-4 h-4" />,
      content: <ReviewTab />
    },
    {
      id: 'comparison',
      label: '경쟁 비교',
      icon: <Scale className="w-4 h-4" />,
      content: <ComparisonTab />
    }
  ];

  if (!isOpen) return null;

  return (
    <div className="fixed inset-0 bg-black bg-opacity-50 flex items-center justify-center z-50 p-4">
