import { useState, useEffect, useCallback, useRef } from 'react';

export interface ChatMessage {
  type: 'user_message' | 'agent_message' | 'error';
  agent?: string;
  content: string;
  timestamp: Date;
}

export interface Vehicle {
  id: string;
  rank: number;
  name: string;
  year: number;
  price: number;
  mileage: number;
  fuel: string;
  image: string;
  topsisScore: number;
  matchScore: number;
}

export interface ProgressUpdate {
  step: string;
  message: string;
}

export interface VehicleInsights {
  summary: string;
  strengths: string[];
  weaknesses: string[];
  costAnalysis: string;
  recommendation: string;
}

export function useWebSocketChat() {
  const [messages, setMessages] = useState<ChatMessage[]>([]);
  const [vehicles, setVehicles] = useState<Vehicle[]>([]);
  const [progress, setProgress] = useState<ProgressUpdate | null>(null);
  const [insights, setInsights] = useState<{ vehicleId: string; data: VehicleInsights } | null>(null);
  const [isConnected, setIsConnected] = useState(false);
  const wsRef = useRef<WebSocket | null>(null);

  useEffect(() => {
    const protocol = window.location.protocol === 'https:' ? 'wss:' : 'ws:';
    const ws = new WebSocket(`${protocol}//${window.location.host}/ws/chat`);

    ws.onopen = () => {
      console.log('✅ WebSocket 연결 성공');
      setIsConnected(true);
    };

    ws.onmessage = (event) => {
      const data = JSON.parse(event.data);

      if (data.type === 'user_message' || data.type === 'agent_message') {
        setMessages(prev => [...prev, {
          type: data.type,
          agent: data.agent,
          content: data.content,
          timestamp: new Date(data.timestamp),
        }]);
      } else if (data.type === 'vehicles_recommended') {
        setVehicles(data.vehicles);
        setProgress(null);
      } else if (data.type === 'progress') {
        setProgress({
          step: data.step,
          message: data.message,
        });
      } else if (data.type === 'vehicle_insights') {
        setInsights({
          vehicleId: data.vehicleId,
          data: data.insights,
        });
      } else if (data.type === 'error') {
        setMessages(prev => [...prev, {
          type: 'error',
          content: data.content,
          timestamp: new Date(),
        }]);
      }
    };

    ws.onerror = (error) => {
      console.error('WebSocket 에러:', error);
      setIsConnected(false);
    };

    ws.onclose = () => {
      console.log('🔌 WebSocket 연결 종료');
      setIsConnected(false);
    };

    wsRef.current = ws;

    return () => {
      ws.close();
    };
  }, []);

  const sendMessage = useCallback((content: string) => {
    if (wsRef.current && wsRef.current.readyState === WebSocket.OPEN) {
      wsRef.current.send(JSON.stringify({
        type: 'user_message',
        content,
      }));
    }
  }, []);

  const requestInsights = useCallback((vehicleId: string) => {
    if (wsRef.current && wsRef.current.readyState === WebSocket.OPEN) {
      wsRef.current.send(JSON.stringify({
        type: 'get_insights',
        vehicleId,
      }));
    }
  }, []);

  return {
    messages,
    vehicles,
    progress,
    insights,
    isConnected,
    sendMessage,
    requestInsights,
  };
}

